-- GENERATED by `wfj generate` from data/quest/quest-0004.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [4001] = { "何が起きている?", "Kharan Mighthammerと話し、Princess Moira Bronzebeardの誘拐について情報を集める。その情報をOrgrimmarのThrallのところへ持って行って下さい。\n\nGor'shakが、Kharanは近くの独房に捕らわれていると言っていたのを思い出す。", "これまでのところ、廊下の向かいの独房にいるドワーフのKharanとのやり取りは限られている。だが、私が、いや「我々」が彼に危害を加えるつもりはないということは、どうにか納得させた。\n\n彼と話し、王女と彼女を捕らえている者たちについて、できる限り多くの情報を集めてこい。その情報を大族長のもとへ持ち帰るのだ。\n\nThrallは王女が傷つけられることを望んではいない。それどころか、彼女を無事にIronforgeへ帰すことも含んだ壮大な計画を立てておられる。Kharanはこのことをすべて知っている……行け!", "この神聖な地へは何の用で来たのですか?", "これはHordeが、戦に引き裂かれた我々の世界の政治情勢を永久に変える好機だ。よく聞け、{name}。\n\nこの任務の失敗は許されない。", 0x6bdf65cd, 0x16317fb3, 0x09658a85, 0x3f3cae06, 0xf15b0d4a, "....." },
  [4002] = { "Eastern Kingdoms", "Thrallの計画した任務を続ける準備ができたら、彼と話して下さい。", "素晴らしい情報を持ってきてくれた、{name}。\n\n大族長として、Hordeにとって最善のことをするのが私の務めだ。我々の後に続く世代が、希望のない生を強いられることのないように。\n\n将来の同盟を形作る好機が、我々の手に転がり込んできた。ドワーフを助ければ、Eastern Kingdomsでの我々の関係は大きく強まるかもしれん。だからこそ、失敗は許されんのだ!\n\n準備はいいか?", nil, "後戻りはできぬぞ、{name}。", 0x59d013ef, 0xe862d33c, 0x9ba00750, nil, 0x751cb339, "...m." },
  [4003] = { "王女の救出", "Emperor Dagran Thaurissanを討ち取り、彼の邪悪な魔法からPrincess Moira Bronzebeardを解放して下さい。", "Dark Ironのドワーフへのこの一撃が成功すれば、奴らの王国全体に衝撃が走るだろう。\n\nPrincess BronzebeardはEmperor Thaurissanの支配下にある。彼女を解放するには、皇帝を殺さねばならん。気をつけろ、お前の務めは二重に危険だ。皇帝に操られている間、Bronzebeardは迷わずお前に襲いかかってくるだろう。\n\n彼女を傷つけるな!", "<Princess Moiraは恐怖に身をすくめている。>", "何ということを!", 0xb3f1fa82, 0x0fccab9e, 0xf393d85a, 0x73a34525, 0x30978a13, "....." },
  [4004] = { "王女は救われた?", "Thrallのところへ戻って下さい!", "そなたは我が夫を殺したのだ、{race}! 我が子は父を持たずにこの世に生まれることになる。\n\n<Princess Moiraがあなたをまっすぐ指さす。>\n\n断言しよう、この子こそが次なるIronforgeの王国の支配者となる。そなたとその同族は、この不当な行いゆえに、世の終わりまで追われ続けるであろう。\n\n<Princess MoiraはまだThaurissanの呪文の影響が残っているのかもしれない、とあなたは思う。>\n\n我を放っておけ、{race}。そなたの大族長も、己の余計な手出しの結果を聞きたがっていることであろう。", nil, "<Thrallはあなたがもたらした情報に言葉を失っている。>\n\n新たな脅威が地平線に迫っている。Magniの余命が尽きていけば、まだ生まれぬこのDark IronがIronforgeの支配者となる道が開かれることになる。\n\nお前は私が頼んだことを成し遂げた。それには報酬を与えよう。\n\nさあ下がれ、{name}! 私はSylvanasとCairneと協議せねばならん。", 0xe74b8f44, 0x0a323a4f, 0xafcd1b6a, nil, 0x75487453, "...m." },
  [4005] = { "Aquementas", "Book of Aquor、Silvery Claws、Irontree HeartをTanarisへ持って行く。\n\nBook of Aquorを使ってAquementasを呼び出す。\n\nトーテムが完成したら、Marshal's RefugeのJ.D. Collieのところへ持って行って下さい。", "この補給品の袋を持ってTanarisへ行くのだ。Lost Rigger Coveへ向かい、石の輪を探せ。\n\n最も東の岬こそが秘密だ……\n\nこの輪の中からのみbook of Aquorを読み上げ、お前が集めた品をBlazerunnerと戦うためのトーテムに変えられる唯一の生き物を呼び出すのだ。\n\nAquementasは目覚めさせられて喜びはしないだろう。だが忘れるな、彼が品を変えるまで、お前は輪の中に留まっていなければならん。", "戻ってきたのかい、え? ふむ……それを見せてもらおうか、{name}。", "Blazerunnerだって……\n\nああ、クレーターの焦げた中心部に強力なエレメンタルが棲んでいることは知っている。皆、距離を置いているんだ。あいつを取り巻く強力なオーラを突破できた者はいない。立ち向かおうとして、岩の道から下の地面へ突き落とされた者も多い。", 0xa2e8e5f3, 0xc6b51af7, 0x4553998f, 0xa907dd37, 0x25722d4b, "....." },
  [4021] = { "反撃!", "Piece of Krom'zar's BannerをCrossroadsの西にいるRegthar Deathgateに渡して下さい。", "HordeはKolkar族に対する君の成功を賞賛しているぞ。だが、Kolkar族は激怒している。復讐のためにKolkarの派遣部隊が故郷Desolaceを出てBarrensへ向かっている、と報告を受けている。最新の報告では、今も西からこの掩蔽壕へ向かって進んでいるとのことだ!\n\nKolkar族侵略者と対峙し、Barrensの脅威を終わらせよう。指導者、Warlord Krom'zarが現れるまで、奴らを殺すんだ。\n\nKrom'zarを倒し、証拠として旗印の一部を渡して欲しい。\n\n我々は君を信頼しているよ、{name}。", "bannerは持っているか?", "やってくれたな! Kolkarを打ち倒したんだ!\n\n{name}、君のここでの行いについての知らせは、必ずThrallに届けるよ。\n\n堂々と立て。君は自分自身とHordeの誇りだ。", 0xa53d08ff, 0x6d88481e, 0xa8ad7e6b, 0x38ed797c, 0x77820849, "....." },
  [4022] = { "炎の味", "Velarok Windbladeから受け取ったBlack Dragonflight Moltを、Cyrus Therepentousに見せて下さい。", "我らの眷属は、そなたのSearing Gorgeでの働きを知っている。\n\nそれを見せよ、{race}。moltだ、愚か者め。", "<Cyrusの目が、燃え盛る2つの球体と化す。>", "<Cyrusがmoltを調べる。>\n\n貴様が全くの役立たずというわけではないことは証明されたな、定命の者よ。", 0xfcdfe35e, 0xa5ea3cce, 0xd8a51497, 0xe95b54fc, 0xaec23a34, "....." },
  [4023] = { "炎の味", "Cyrus Therepentousに、あなたの価値の証を見せて下さい。\n\nCyrusはもう、あなたにその価値がないことを知っているような気がする。", "Flightを求めるのか？ そなたの価値の証を我に示せ、定命の者よ。", "<Cyrusの目が、燃え盛る2つの球体と化す。>", "<Cyrusがmoltを調べる。>\n\n貴様が全くの役立たずというわけではないことは証明されたな、定命の者よ。", 0xfcdfe35e, 0x5486cd0f, 0x40ef8a00, 0xe95b54fc, 0xaec23a34, "....." },
  [4024] = { "炎の味", "Blackrock Depthsへ行き、Bael'Garを倒す。\n\n分かっているのは、その巨人がBlackrock Depthsの中にいることだけだ。Bael'Garの亡骸にAltered Black Dragonflight Moltを使って、Fiery Essenceを捕らえるのを忘れないこと。\n\nEncased Fiery EssenceをCyrus Therepentousのところへ持ち帰って下さい。", "我は火の山の灼熱の炎を味わいたい。Blackrockの溶けた炎を我が身に降り注がせたいのだ。あの本質、あの灼熱こそ、我が渇望するものだ。\n\nBael'GarはDepths of Blackrockに棲んでいる。Ragnarosの炎から生まれた、純粋な炎の存在だ。Bael'Garを倒し、そのくすぶる亡骸から、内なる炎の一片を我がもとへ持ってこい。\n\nその亡骸にmoltを使い、内なる炎を安全に取り出すのだ。\n\n成し遂げれば、報いよう。", "巨人は倒されたか?", "<Cyrusがあなたの手からfiery essenceをひったくる。>\n\nそうだ!\n\n褒美を受け取って失せろ。今すぐ我が前から消えるがいい!", 0xfcdfe35e, 0xba5ae01f, 0x2e60532b, 0x5af18fe3, 0x9c8fb03f, "....." },
  [4061] = { "機械の発生", "Burning Steppesへ行き、Hierophant Theodora MulvadaniaのためにFractured Elemental Shardsを$N1個回収して下さい。\n\nTheodoraが、その地方のゴーレムやエレメンタルがこの欠片の出どころだと言っていたのを思い出す。", "機械どもが最初に姿を現したのは、私たちがSearing Gorgeに初めて踏み込んだときでした。さらに調べると、それらはBurning Steppes、おそらくはBlackrock Depthsから持ち込まれていることが分かりました。そこであなたの出番なのです、{name}。\n\n最初の務めは、Burning Steppesへ赴き、その地のrock automatonsとlesser rock creationsからelemental shardsを回収することです。十分な量を集めたら私のもとへ戻ってください。その出どころを突き止めましょう。", "この任務を軽く考えるな、{name}!", "<Theodoraが破片を自分の前に並べる。>\n\n<Theodoraが巨大な片眼鏡で破片を注意深く調べる。>\n\n興味深いですね。これらの破片それぞれの構造の基部に刻まれているのは……頭文字です。", 0x87eb97c7, 0x8a45dca1, 0xa054896b, 0x52f4b0fd, 0xc32121eb, "....." },
  [4062] = { "機械の発生", "Elemental Shard SampleをLotwil Veriatusのところへ持って行って下さい。\n\nTheodoraが、Lotwilは東の野営地に駐留していると言っていたのを思い出す。", "G.L.A.\n\nこれが元素の欠片に刻まれていた「頭文字」だ。頭文字の下には、何らかの階級を示す印がある。お前がBurning Steppesで破壊した機械は「Rank IV」だった。これは低い階級なのだろう。\n\nこの欠片のサンプルを東の野営地にいるLotwil Veriatusのところへ持って行ってくれ。彼は元素科学の分野でそれなりに名の知れた学者だ。我々の調査に力を貸してくれるかもしれない。", "何を持っているんだ、{race}?", "<Lotwilの顔が青ざめる。>\n\n私は……私はこの印を知っている。", 0x87eb97c7, 0x155232bd, 0xd8672ae4, 0x2ed65f2f, 0x11fdab04, "....." },
  [4063] = { "機械の発生", "Golem Lord Argelmachを見つけて討ち取って下さい。彼の首はLotwilに渡して下さい。なお、Argelmachを護衛しているRagereaver GolemとWarbringer ConstructからIntact Elemental Core 10個を集める必要があります。あなたは超能力者なのでそのことを知っています。", "これがArgelmachのはずがない! Argelmachは10年前に死んだ。なぜ分かるかって? 奴を殺したのは私だからだ。\n\n奴は卑劣なドワーフで、私の生涯の研究をねじ曲げて、邪悪な目的に使おうと躍起になっていた。悪しき者は、いつも正義を逃れる道を見つけるものらしい。\n\nこれがArgelmachの仕業なら、奴を滅ぼさねばならん。奴の最新の創造物の標本が必要だ。適切な標本があれば、この反乱を止められるかもしれん。その創造物たちは、Blackrock DepthsでArgelmachを守っている。", "あいつだったのか? 本当に生きていたのか?", "何だこれは?!? この首は肉体のものじゃない。これは暗黒鉄か何かの作り物だ。Argelmachの亡霊……別の機械か! Argelmachの破壊は束の間のもので、すぐに別の者が「奴」とすげかわるために蘇ることだろう。", 0x87eb97c7, 0x4c4bd657, 0xccd90590, 0xa58db9f2, 0xa4be27b1, "....." },
  [4081] = { "見つけ次第殺せ: Dark Iron族ドワーフ", "Blackrock Depthsへ赴き、卑劣な侵略者どもを倒す!\n\nWarlord Goretoothは、Anvilrage Guardsmenを$N1体、Anvilrage Wardensを$N2体、Anvilrage Footmenを$N3体倒してほしいと言っています。任務を終えたら彼のところへ戻って下さい。", "Kargath Expeditionary Forceの司令官、Warlord Goretoothの命により:\n\nBlackrock Depths内のGeneral Angerforgeの軍勢は、ことごとく殲滅せねばならない。\n\nAngerforgeの兵は冷酷な殺し屋であり、Kargath Expeditionary Forceの第109師団を大量虐殺した張本人である。英雄たちは、これらの獣と対峙する際には細心の注意を払うよう警告する。\n\nBlackrock DepthsにおけるGeneral Angerforgeの軍勢の第一線を撃破した者には、褒賞が与えられる。", "何だ、{race}? 私が小隊を指揮しているのが見えんのか?", "この最初の一撃で、Angerforgeも肝を冷やすはずだ。さあ行け、兵士。俺には終わらせる仕事も、練る作戦も、潰す敵もあるんだ!\n\nもっと仕事が欲しければ、手配書を見ろ。", 0x5b57c381, 0x14d77f24, 0x1bb891cb, 0x436990d6, 0xad38613a, "....." },
  [4082] = { "見つけ次第殺せ: Dark Iron族上級士官", "Blackrock Depthsへ赴き、卑劣な侵略者どもを倒す!\n\nWarlord Goretoothは、Anvilrage Medicsを$N1体、Anvilrage Soldiersを$N2体、Anvilrage Officersを$N3体倒してほしいと言っています。任務を終えたら彼のところへ戻って下さい。", "Kargath Expeditionary Forceの司令官、Warlord Goretoothの命により:\n\nK.E.F.偵察部隊の長、Grandmaster Lexlortが、Dark Ironの高官たちの居場所の知らせを持って帰還した。都の中心近く、施錠された門の向こうで、奴らは我らの兵を抹殺するために軍勢を訓練している。Blackrock Depthsへ赴き、奴らを撃滅せよ!\n\nこの任務を完遂した者には、褒賞が与えられる。", "またお前か? 認めざるを得んな、{name}。お前はしぶとい。", "Angerforgeの奴明らかに……怒っているな。第三の褒賞を受け取ったら戻ってこい。そうしたら我々は「Angerforgeに死を」作戦を開始する。その結果についてはいかなる詳細も説明できないが、安心しろ。これには誰かの死が関わっているのだ。", 0x98649479, 0x6a465883, 0x1f5265bd, 0x707ace6a, 0x7dc27660, "....." },
  [4083] = { "霊界の聖杯", nil, nil, "霊的な聖杯が宙に浮かび、ゆっくりと上下している……まるで死にゆく心臓の鼓動に合わせるかのように。", "宝石は聖杯の底へ落ちても、まったく音を立てなかった……。", 0x37a37884, nil, nil, 0x2d8e572b, 0x0ae3e7e4, ".mm.." },
  [4084] = { "銀の心臓", "FelwoodのEridan Bluewindのために、Silvery Clawsを$N1個とIrontree Heartを$N2個集めて下さい。", "そなたの言う者を我は知らぬ、{name}。\n\nだが案ずるな。そなたの友が我を探す旅の途中であったのなら、彼が何を望んでいたかは知っておる。\n\nUn'Goro Craterの中心には、最も純粋な形の悪が棲んでおる。その悪はBlazerunnerと呼ばれるelementalの姿をとり……誰にも払えぬオーラに守られておる……\n\n誰にも……それを払うだけの力を持つ者を除いてはな。我はそなたにその力を教えることができる、{name}。\n\nまずは我の言うとおりにせよ。FelwoodのクリーチャーからSilvery Clawsを$N1個とIrontree Heartを$N2個集め、戻ってくるのだ。", "Blazerunnerを倒すのに必要な力についてもっと教えられますが、まずは私が必要とする物を集めてきてください。", "よろしい、{name}。君が本気で友を助けようとしているのが分かる。", 0x04c078b5, 0x295bb140, 0x5dd75495, 0x1712c10d, 0xb4e28896, "....." },
  [4101] = { "Felwoodの浄化", "Blood Amberを$N1個、FelwoodのArathandris Silverskyのところへ持って行って下さい。", "植物はFelwoodに命を与えていますが、その植物でさえ堕落の穢れに苦しんでいます。浄化する方法は知っていますが、知らない者や信頼できない者にその知識を授けるわけにはいきません。あなたが本当にCenarion Circleの大義に力を貸すのだと、私に証明してください！\n\n北にはIrontree Cavernsがあります。そこにいるWarpwood elementalsは、もはや浄化の望みもありません。彼らの樹液――blood amberと呼ばれるものです――を持ってきてください。ここにいる他の命を救えることを願って、それを研究したいのです。", "Felwoodが苦しんでいることは分かっています、{name}。私もともに苦しんでいるのです! それでも、信念を揺るがせるわけにはいきません。私の持つ知識が悪しき者の手に渡れば、Felwood全土に災いをもたらすでしょう。\n\n倒したWarpwoodの精霊たちから取れるblood amberを持ってきてください。そうすれば、あなたを信頼し、汚染と戦う手段を講じる手伝いを任せましょう。", "このblood amberは、Felwoodに蔓延する腐敗を打ち破る手段を見つけるために使われます。あなたはCenarion Circleのためならどんなことでもする覚悟があると示してくれました。今はあなたを信頼しています、友よ。\n\nエレメンタルを倒すことがあなたの証になったというのは奇妙に思えるかもしれませんが、数えきれないほどの知性ある存在を救うという目的は、私たちの取る手段を正当化するはずです。これであなたと私は、私が作れる軟膏を通じて命を守ることに専念できます。\n\n{name}、Felwoodを浄化する時が来ました。", 0x4b5f131b, 0x4af2f8b9, 0xc8b99dee, 0xb41117a7, 0xe78c0555, "....." },
  [4102] = { "Felwoodの浄化", "Blood Amberを$N1個、FelwoodのMaybess Riverbreezeのところへ持って行って下さい。", "植物はFelwoodに命を与えていますが、その植物でさえ堕落の穢れに苦しんでいます。浄化する方法は知っていますが、知らない者や信頼できない者にその知識を授けるわけにはいきません。あなたが本当にCenarion Circleの大義に力を貸すのだと、私に証明してください！\n\n北にはIrontree Cavernsがあります。そこにいるWarpwood elementalsは、もはや浄化の望みもありません。彼らの樹液――blood amberと呼ばれるものです――を持ってきてください。ここにいる他の命を救えることを願って、それを研究したいのです。", "Felwoodが苦しんでいることは分かっています、{name}。私もともに苦しんでいるのです! それでも、信念を揺るがせるわけにはいきません。私の持つ知識が悪しき者の手に渡れば、Felwood全土に災いをもたらすでしょう。\n\n倒したWarpwoodの精霊たちから取れるblood amberを持ってきてください。そうすれば、あなたを信頼し、汚染と戦う手段を講じる手伝いを任せましょう。", "このblood amberは、Felwoodに蔓延する腐敗を打ち破る手段を見つけるために使われます。あなたはCenarion Circleのためならどんなことでもする覚悟があると示してくれました。今はあなたを信頼しています、友よ。\n\nエレメンタルを倒すことがあなたの証になったというのは奇妙に思えるかもしれませんが、数えきれないほどの知性ある存在を救うという目的は、私たちの取る手段を正当化するはずです。これであなたと私は、私が作れる軟膏を通じて命を守ることに専念できます。\n\n{name}、Felwoodを浄化する時が来ました。", 0x4b5f131b, 0xab433d0c, 0xc8b99dee, 0xb41117a7, 0xe78c0555, "....." },
  [4120] = { "腐敗の力", "FeralasのCamp MojacheにいるTalo Thornhoofは、FelwoodでAngerclaw Grizzlies・Felpaw Ravagerをそれぞれ12頭殺すよう求めています。", "ハンターとして、私は敵に見る強さを見習おうと努めている。敵をよく知るだけで、戦いを有利に運ぶことができるのだ、{name}。\n\nAshenvaleの北にあるFelwoodという地では、生き物たちがfelという物質に穢されている。熊や狼はそのせいで狂ってしまったが、同時にさらに強くもなったのだと私は思う。\n\n行け、{name}。Felwoodへ行き、その獣たちと対決してこい。奴らが本当に私の思うほど強いのか、自分で確かめてくるのだ。", "felに触れたものはすべて、奇妙な緑の光を放っている……邪悪なものだと感じるが、同時にとても強力だ。", "あなたの話を聞く限り、その生き物たちは思慮のない獰猛さを見せているようですね……\n\n警戒を怠らないでください、{name}。その腐敗についてさらに学ぶことが、あなたのためになるでしょう。常に敵を知ることです。", 0x8cd381ae, 0xb24931f9, 0xa1cc7468, 0xd42eceb7, 0xda615740, "....." },
  [4121] = { "絶体絶命", "囚人Grark Lorkrubを護送し、Burning SteppesからBlackrock Mountainを抜けてSearing Gorgeまで連れて行って下さい。\n\nLexlortが、反対側で部下を待たせておいてGrarkを引き取らせると言っていたのを思い出す。\n\nThorium ShacklesもLexlortに渡す必要があります。", "俺を捕らえたまま、合流地点までたどり着けると本気で思ってるのか? 厳重に守られたBlackrockの要塞に押し入って、誰にも、何にも気づかれずに奴らの大事な獲物をさらえるとでも思ってたのか?\n\nお前は滅ぼされるぞ!", "この裏切り者のクズは私が引き取ろう、{name}。", "英雄的な行いが認識されずに済まされることはなかろう、{name}。お前は報酬を獲得したのだ。大将軍が最後の任務に関して話したいと仰せだ。", 0x8fd5dbe7, 0xf6e011d7, 0x41c7f16e, 0x2213bc0d, 0xfb5709db, "....." },
  [4122] = { "Grark Lorkrub", "Burning Steppesへ行き、Grark Lorkrubを見つける。Lexlortが、彼は最後に巨大なBlackrockの要塞で目撃されたと言っていたのを思い出す。\n\nGrark Lorkrubを見つけたら、Thorium Shacklesを使って彼を拘束し、Blackrock Mountainを抜けてSearing Gorgeまで連れ戻して下さい。Lexlortが反対側で部下を待たせ、Grarkを引き取らせる手はずだ。", "俺は奴をSearing Gorgeから山を抜け、Burning Steppesまで追った。あの裏切り者は、我々の日々の作戦に関する重要な情報をBlackrockのオークどもに渡しているところを現行犯で押さえられた。Grark Lorkrubのことだ。\n\n奴は今、Burning Steppesで連中に守られてのうのうとしている――少なくとも奴はそう思っている。\n\nこのshacklesを持っていけ、{name}。Grarkを見つけて枷をはめ、Blackrock Mountainを通って連れてこい。やり遂げれば褒賞はお前のものだ。", nil, "Blackrockの軍団に加わることによって、我らが力を手にしたことが分からないか?", 0xf4017ef8, 0x5d91f069, 0xe8e67229, nil, 0x08e246b4, "...m." },
  [4123] = { "The Heart of the Mountain", "Burning SteppesのMaxwort UberglintにHeart of the Mountainを渡して下さい。", "何年もの間、俺はある宝石を探し求めてきた。Heart of the Mountainって名で、お前の拳ほどの大きさがある! Dark Ironのドワーフどもがそいつを金庫にしまい込んでいて、どんなに頑張っても売ってくれないんだ。\n\nだから力ずくでいくしかない。\n\nBlackrock DepthsのLower Vaultまで戦い抜き、その秘密の金庫を破ってHeartを手に入れてくれ。そのためには、Watchman Doomgripを倒さなきゃならん。そいつは金庫の遺物の宝箱を全部開けるまで姿を見せないんだ!\n\n幸運を祈る。", "Heart of the Mountainは持っているか? 私にとって、その価値は計り知れない。", "heartを手に入れたのか! 驚いた! 想像していたよりもずっと美しい!\n\nさあ{name}、これを報酬として受け取ってくれ!", 0x64cd6d04, 0x5c6ba9a4, 0x7e785515, 0x5e154cee, 0x0c1b5cb9, "....." },
  [4124] = { "消えた伝令", "Feathermoon StrongholdのGinro Hearthkindleと話して下さい。", "私の仲間のGinro Hearthkindleが、伝令と彼が運んでいた荷物の行方について助けを求めている。伝令が行方不明になってから一週間ほどになる。我々自身の捜索は実を結ばず、行き詰まってしまった。残念ながら、伝令は任務中の行方不明者だと宣言せざるを得なかった。\n\n時間と余力があるなら、Ginroと話してやってくれ。彼はここStrongholdにいるはずだ――たぶん自室だろう。", nil, "Latroの差し金で来たのだろう。今となっては望みのない話だと思うが、どんな助けでも受け入れよう。正直に言うと……この件に決着をつけて心を休められたら嬉しい。毎日Feralasの荒野へRaschalの手がかりを探しに出かけ、毎晩、gnollの歯と落胆以外に何の成果もなく戻ってきているのだ。", 0x05891b2b, 0xd64f6ee6, 0x6914d46a, nil, 0xadd3e8c1, "...m." },
  [4125] = { "消えた伝令", "Feralasの海岸沿いのどこかにある、伝令の船を見つけて下さい。", "伝令のRaschalがThalanaarへ向けて出発してから、もう一週間ほどになる。彼はFeralasをよく知っている。General Feathermoonが遠征軍を率いてここへ来て以来、ずっと我々と一緒にいるんだ。彼の計画は、手漕ぎ舟で海岸を下り、Hordeの野営地を避けてFeralas南部を横断しようというものだったはずだ。\n\n私には彼の舟を見つけられなかったが、君なら見つけられるかもしれない。隠されているのかもしれないし、沈められたのかもしれない。いずれにせよ、彼の居場所の手がかりがあるかもしれない。何か見つけたら、知らせてくれ。", nil, "壊れた手漕ぎ舟らしきものを見つけた。少し濁った水越しに、左舷に大きな穴がいくつも開いているのが見える。舟は簡素な木の骨組みだけになるほどずたずたにされている。この舟を壊した何者かは、おそらく2つにへし折ろうとしたのだろう。右舷にはFeathermoon Strongholdの小さな紋章が描かれている。\n\n舟の底の泥の中で、何か金属のようなものがきらりと光った……", 0x05891b2b, 0xbe904bf7, 0x2af52f5d, nil, 0x30d69719, "...m." },
  [4126] = { "Hurley Blackbreath", "KharanosのRagnar ThunderbrewにLost Thunderbrew Recipeを渡して下さい。", "悪党Hurley Blackbreath率いるDark Ironのドワーフどもが、Thunderbrewの最高のレシピの一つ、Thunderbrew Lagerを盗みやがった。悪党どもめ! あんな極上の酒は奴らにはもったいない!\n\n{name}、厄介な仕事を頼みたい。Burning SteppesのBlackrock Depthsへ行って、見つけたThunderbrew Lagerの樽を片っ端からぶっ壊し、Thunderbrew Lagerのレシピを取り返してきてくれ!\n\n頼む、あのレシピを取り返してくれ。そのためにBlackrock Depthsをひっくり返すことになってもな!", "recipeは持ってきたか、{name}? あのDark Ironのドワーフどもが我が家の酒を飲むなんて、考えるだけで耐えられん!", "見つけてくれたか! でかしたぞ! それに、あのDark Ironどもと、Hurley Blackbreathをこてんぱんにしてやったと願いたいね!\n\nThunderbrew家は君のために尽くそう、{name}。君は英雄の中の英雄だ!", 0xc4008466, 0x93309524, 0x5d695408, 0x489de26e, 0x8e13a0d0, "....." },
  [4127] = { "船の残骸", "Feathermoon Strongholdへ戻り、見つけたDiscarded KnifeをGinro Hearthkindleに見せて下さい。", "泥の中に手を這わせると、指先がナイフの柄に触れた。よく手入れされているようで、舟に乗っていた誰かが落としたものだと考えてもよさそうだ。舟の大きな部分が失われていることも、それを落としたことと関係があるのかもしれない。\n\nナイフをつかんだところで、Feathermoon StrongholdのGinro Hearthkindleから、手がかりを見つけたら持ってくるよう言われていたことを思い出した。だが、この水の中にいるのは自分だけではないような気がする……", "ああ、おかえりなさい、{name}。Raschalの最期について、たとえそれがどれほど悲劇的なものであっても、何か手がかりを見つけられたことを願っています。", "興味深い……これはRaschalのknifeだと思う。舟と一緒に水の底で見つけたと言ったね？ふむ、knifeが見つかっただけでは、これをRaschalの失踪と結びつけるには足りないかもしれない。だが、もっと詳しく知るために試せる、型破りな手段がある。\n\nサイコメトリーというものを聞いたことはあるかね？", 0x7d02beea, 0x85c0f895, 0x3c45061d, 0xbc63d551, 0xd54492e1, "....." },
  [4128] = { "Ragnar Thunderbrew", "Ragnar Thunderbrewと話して下さい。", "よう、{name}。Ragnar Thunderbrewが、誰かにエールを盗まれてカンカンに怒ってるって聞いたぞ。頼もしい冒険者を探してて、たっぷり払うつもりらしい。\n\n興味があるならRagnarと話してみな。Dun MoroghのKharanosにある、Thunderbrew Distilleryにいるよ。", nil, "その通り、俺は怒っとる! 強盗に遭ったんだよ! 秘伝のレシピがひとつ奪われちまった! あいつらよくもやりやがって! Dark Iron族を憎む理由なら、もうたっぷりあったってのに! もう……もうあいつら許さん!", 0x8b04a24f, 0x902b7d45, 0x4b5d97c0, nil, 0x5a0ef227, "...m." },
  [4129] = { "明かされたナイフ", "Discarded KnifeをFeathermoon StrongholdのQuintis Jonespyreのところへ持って行って下さい。", "Strongholdに住み込みのドルイド、Quintis Jonespyreには……変わった技がある。その一つがサイコメトリー――触れることで品物の来歴を明らかにする能力だ。どうやってるのかは聞くなよ。私には分からないし、分かろうとも思わない魔法のおかげってことにしてる。だが、二つのことは知っている。一つ目、私はそれが効くのを見たことがある。二つ目、あのろくでなしは私に借りがある。\n\nナイフを持って、ここにある彼の小さなツリーハウスにいるQuintのところへ行ってくれ。そして、あのナイフに不思議な力を使ってくれれば、Kalimdor Hold 'Emの借金は帳消しにしてやると、私の代わりに伝えてくれ。", "Ginroに言われて来たのかい?\n\n私のサイコメトリーの読み取りは精神をかなり消耗させる……Kalimdor Hold 'Emでの負けも同じくらいだがね。ここStrongholdでは「King of the Bad Beats」なんて呼ばれてるよ。カードでは運がない……そのぶん自然の秘密を極める運はある、ってことかな。\n\nともかく、もちろん引き受けるよ。Raschalの運命を明らかにするのに必要な突破口になるかもしれない。knifeを渡してくれれば、始められる。", "ありがとう、{name}。\n\nサイコメトリーは決して正確な技ではないが、他の者が望みなしと片付けた状況を見通すために、過去に使ったことがある。君が見つけたknifeに使えば、Raschalの身に何が起きたのか垣間見ることができるだろう。\n\nほんの一瞬で済むが、術者に優しい作業とは言えない。少し我慢してくれ。", 0x5a2b17b8, 0x98645dbc, 0x01a82e3d, 0xea41a841, 0x24cb6162, "....." },
  [4130] = { "サイコメトリーの読み取り", "Feathermoon StrongholdのGinro Hearthkindleと話して下さい。", "ごめん、まだ少しふらふらするんだ。とにかく、役に立つ幻視をいくつか見たよ。\n\nRaschalは舟から大きな革のバックパックを二つ取り出して、内陸へ向かう。でも、舟には戻ってくるんだ。gnollの頭皮が見える……彼はgnollsに出くわした――たしかWoodpawと呼ばれているやつらだ。彼はとても心配している――ほとんど怯えていると言っていい――何かについてね。あまりにそのせいで、背後で水のelementalsが形をなしつつあるのに気づいていない。幻は……そこで途切れる。\n\n休まないと。ごめんね、{name}。僕が見たことをGinに伝えてくれ。彼は知っておくべきだ。", nil, "Quintの見たビジョンを伝えてくれてありがとう、{name}。次にカードをする時は、あいつにもう少し手加減してやるのを覚えておくよ。\n\nRaschalは戦いでも引けを取らないし、gnollごときで心配するような奴じゃない。いや、怯えるなんてなおさらだ。それでも、君と君の仲間ならこの新しい情報をもとに動いて、我々が切実に必要としている突破口を開いてくれるかもしれない。", 0xf6ce658b, 0xd64f6ee6, 0x74d0882e, nil, 0x42b23019, "...m." },
  [4131] = { "Woodpaw Gnolls", "Feralas南部にあるWoodpaw Gnollの野営地で、伝令の持ち物か、伝令本人の手がかりを探して下さい。", "我らが「お友達」のWoodpawが最後にRaschalを捕まえたのかもしれないが、どうもそうじゃない気がする。それでも、探し始めるならあそこが一番だ。\n\nどうすべきか、もっとはっきり分かればいいんだが、今のところ言えるのは『Woodpawの野営地を探せ――行け』ということだけだ。gnollsは漁った品を手元に置いて、それを取り合って争うことは知っている。もしかしたら、Quintが言っていたバックパックに出くわしたのかもしれない。これまでの捜索では正面からの戦いは避けてきたが、Quintの幻視がある以上、奴らに思い切り食らいついてやれと言いたい。", nil, "近くの木に、大きな革のバックパックが2つ留めつけてある。どちらのバックパックの前面にも、Feathermoon Strongholdの小さな記章が付いている……", 0xb9f65bac, 0x9cdc696a, 0x64b79ecf, nil, 0xed276df7, "...m." },
  [4132] = { "作戦: Angerforgeに死を", "Blackrock Depthsへ行き、General Angerforgeを討ち取れ! 任務を終えたらWarlord Goretoothのところへ戻って下さい。", "見事な働きだ、{name}。いよいよ最後の任務を与える時だ。\n\nK.E.F.第109師団への攻撃を指揮し、我らの軍勢を大量虐殺したDark Iron、General Angerforgeに裁きを下さねばならん。\n\nこれは間違いなくお前にとって最も過酷な任務となるだろう。だが成功すれば、たっぷりと報いよう。", "Butcher of Blackrockは始末したか?", "ついに! 悪党が裁きを受けたぞ! 君は並外れた人物だ、{name}。このmedallionを、HordeとK.E.F.への揺るぎない献身の証として身につけてくれ。", 0xc3b1887e, 0xfcb068b5, 0x66477d79, 0x27ab1409, 0x9feb7e5c, "....." },
  [4133] = { "Vivian Lagrave", "KargathのShadowmaster Vivian Lagraveと話して下さい。", "Shadowmaster Vivian Lagraveがお前の力を必要としている。彼女はBadlandsにあるオークの前哨地Kargathで、Blackrock DepthsのDark Ironのドワーフが造るという、ある酒の噂を追っている。\n\nVivianと話せ。お前を待っている。", nil, "来てくれて感謝する、{name}。ここにも荒涼とした趣がないわけではないが、Apothecariumの設備には及ばんな。\n\n世辞はこのくらいにしよう。本題に入ろうか?", 0x55a2ff51, 0xafae59a2, 0xf2e1d493, nil, 0x684ce66c, "...m." },
  [4134] = { "Lost Thunderbrew Recipe", "KargathのVivian LagraveにLost Thunderbrew Recipeを渡して下さい。", "Dark IronのHurley Blackbreathがエールのレシピを盗んだという噂だ。そのエール、Thunderbrew Lagerは、飲んだ者に大いなる力と勇気を与えるという。我々はその酒を研究したい。もしかすると、その効能の別の使い道が見つかるかもしれん……よりForsakenの目的に沿った使い道がな。\n\nBlackrock Depthsに潜り込み、Hurleyを見つけて奴からThunderbrew lagerのレシピを奪い、私のところへ持ってこい。\n\n奴を見つけるには、奴の大事なエールを脅かしておびき出す必要があるかもしれん。", "Thunderbrew Lagerのrecipeは持ってきたか、{name}?", "結構。このrecipeはApothecariumに送って研究させる。やがてその秘密も解き明かされるだろう。いつの日か、Allianceのドワーフどもは、この酒の効能が自分たちに向けられるのを知ることになるかもしれん!\n\nそれが私にはひどく愉快でね。死は人のユーモアの感覚に影響を及ぼすのかもしれん……そう思わんか?", 0x748bf69d, 0x933801cd, 0x81bea919, 0x7e3d89d6, 0x4e029e8d, "....." },
  [4135] = { "Writhing Deep", "Raschalの最後の足取りが分かったので、Writhing Deepで彼か彼の亡骸の捜索を続けて下さい。メモによれば、そこはWoodpaw gnollの野営地の南にある。", "バックパックの中には二つの品が入っていた。一つ目はThalanaarへ届けられるはずだった荷物の包み、二つ目は宛先不明の読み手に向けて急いで書かれたメモだ。\n\nメモには、gnollの野営地の南、Writhing Deepという場所で、陰湿な虫のような生き物を発見したことが書かれている。書き手は、それがFeralas全体への深刻な脅威であるかのように、自ら調べる必要を感じていた。メモには「Raschal of Feathermoon」と署名されている。\n\nどうやら、Raschalが最終的にどこへ向かったのか突き止めたようだ。", nil, "異質な大きな莢を見つけた。莢の表面は粘液状に見えるが、ところどころから硬くなった突起が突き出している。莢そのものは人型の生き物をすっぽり包み込めるほどの高さと幅があり……莢の皮越しにかすかに人の形が見えることから、実際に中に包まれているのはそれだと推測できる。", 0x7b083e72, 0xaa66fc0f, 0xc369aa3c, nil, 0x656d0a45, "...m." },
  [4136] = { "Ribbly Screwspigot", "Burning SteppesのYuka ScrewspigotにRibbly's Headを渡して下さい。", "弟のRibblyは昔から家族のお荷物でね、うちの金を持ち出しては、次から次へとくだらない計画に使い果たしてきたんだ。\n\nで、最後の計画が最悪だったらしい。Booty BayのBaron Revilgazが、かわいそうなRibblyの首に懸賞金をかけたのさ。これでScrewspigots家がどれだけ喜んでるか、言葉にできないよ! うちのちびRibblyも、ついに値打ちが出たってわけだ!\n\nでも今、あいつはBlackrock Depthsの奥深くに隠れてる。頼む、あいつを見つけて私のところへ連れてきてくれ!\n\nそれか、来ようとしないなら、それでもいい……首だけ持ってきてくれ。", "Ribblyは連れてきたか? それとも、せめてあいつの一部でも?", "アハ! 見つけたんだな! それに……弟はおとなしく来る気はなかったようだね。残念だ。Revilgazに引き渡すという我々の計画を伝えたときの、あいつの顔を見たかったよ。\n\nありがとう、{name}。おかげで家族はとても喜んでいる。それに、Ribblyが今ほど安らかに見えたことはないね。", 0x67d4d005, 0x59fd1d36, 0xbb53d4bb, 0xb98234d6, 0x2665856f, "....." },
  [4141] = { "MuiginとLarion", "Bloodpetalsを$N1個集め、Muiginのところへ戻って下さい。", "あそこのLarionが見える？私たちがここにいるのは、あいつのせいなのよ！\n\n道が違うって言ったのに、聞くと思う？しかも、口をきかないのはあいつの方だなんて信じられる？まあ、あいつの気が変わるまで、ちょっとからかってやりましょう。\n\nこのあたりにいる変な植物みたいな生き物に気づいた？厄介なだけの連中なんだけど、きちんと仕込めば、命令に従わせられると思うの。\n\nでもまずは、研究用のサンプルが要るわ。いくつか集めてきてもらえる？", "Larionには報いが来るぞ、間違いない!", "あいつらにあまり手こずらなかったならいいけど、{name}。あいつらには近寄らないようにしてるんだ……凶暴だからね！\n\n1株を飛び越えようとしたら……襲われたんだよ！植物があんな振る舞いをするなんておかしいって！", 0x3b600e39, 0xee694717, 0x8d143ea4, 0x196febdb, 0x8ed4db5d, "....." },
  [4142] = { "Greganを訪ねて", "BloodpetalをFeralasのGregan Brewspewerのところへ持って行って下さい。", "これをどう考えたらいいのかよく分からないわ、{name}。この植物……ほんの少しだけど知能があるみたいなの。\n\nでも、私は専門家じゃないのよね。だけど、専門家なら知ってるわ！\n\nFeralasの北部へ行って、Gregan Brewspewerっていう私の仲間を探して。こういうことの専門家なの。\n\nGreganならきっと助けになってくれるわ。荒野にいるはずよ。大きな街に住むような人じゃないから。", "わしはこの森で暮らしているんだ……穏やかにな。\n\nまあ、少なくともそうなると思っていた。Ironforgeに住んでいた頃より、ここのほうがよっぽど客が多いんだ!", "Bloodpetalだって？ふーむ……じゃあ、まずは計画を説明してもらおうか。手伝えるかどうかはそれから言うよ。", 0x36b0a2e1, 0x0a57e80f, 0x0530df19, 0x0370b6ea, 0x794b85cc, "....." },
  [4143] = { "邪悪な霧", "Atal'ai Hazeのサンプルを$N1個集め、Un'Goro CraterのMuiginのところへ戻って下さい。", "正直なところ、{name}、旅の中でこんな植物は見たことがないよ。そのクレーターへ行ってみるべきかもしれないな……\n\nいずれにせよ、Muiginが探しているものはちょうど分かっていると思う――Atal'ai hazeだ。ひどい代物で、集めるのも大変だが、あの小さな怪物どもを操るにはまさにうってつけだ。\n\nSwamp of SorrowsにあるAtal'Hakkarの神殿へ行く必要がある。Atal'ai Hazeは、そこにいるdeep lurkers、murk worms、oozesから集められるよ。幸運を祈る、{name}！", "Larionはまだ口をきいてくれない! まったく、根に持つのが得意なやつだ。", "正直、あれに触るのはちょっと気が引けるよ、{name}！でもGreganが効くって言うなら、試してみる気はあるさ！", 0xea486465, 0x0857fbc6, 0x87555936, 0x26b31bb5, 0x02785b23, "....." },
  [4144] = { "Bloodpetal Sprouts", nil, nil, "作戦はこうだ、{name}。外に出てbloodpetal sproutsを集めてきてくれ……ほら、まだ完全に芽吹いていない植物のことだ。それをここに持ってくる。そうしたら、Atal'ai hazeで何ができるか試してみる。\n\n私のことを執念深いと思うかもしれないな……実際、その通りだ!\n\n本当はここから出る道を知ってるんだが、Larionが私が正しいと認めるまでは、ここを動かないぞ!\n\nさあ行ってくれ。bloodpetal sproutsを見つけて、楽しもうじゃないか!", "どうなっても知らないぞ、{name}！これでLarionの注意を引けるはずだ！", 0xa017fdce, nil, nil, 0x0a863215, 0xb43bdc2e, ".mm.." },
  [4145] = { "LarionとMuigin", "Marshal's RefugeにいるLarionのために、Bloodpetal Lasher・Bloodpetal Thresher・Bloodpetal Flayer・Bloodpetal Trapperをそれぞれ5体ずつ狩って下さい。", "あそこのMuiginが見えるかい? 僕らが迷ったのは、あいつのせいなんだ!\n\n道を知ってたのは僕の方なのに、あいつが近道を知ってるって言い張って、こんな所に来ちゃったんだ!\n\nさらに悪いことに、今じゃあいつは僕を困らせようと、いかれた植物の害虫を次々に送り込んでくる。腹が立って当分あいつと口をきく気はないけど、この害虫どもはもう手に負えないよ。\n\nまずは、あいつの供給源を断ってみるのはどうだい。外へ出てBloodpetalsを狩って、戻ってきてくれ。", "Muiginが先に謝らない限り、あいつとは二度と口をきかないぞ!", "協力に感謝するよ、{name}。しかし、残念ながら悪い知らせがある……", 0xc8a99c67, 0xd07fc75c, 0x91ec51ee, 0x8777962b, 0x630db9da, "....." },
  [4146] = { "虫取り機の燃料", "Marshal's RefugeのLarionにUnloaded ZapperとAtal'ai Haze 5つを届けて下さい。", "ついてるね、{name}! Marvonがいない間に自分でもいくつか実験をしてて、その一つが短距離用の虫よけzapperなんだ。ちょっと調整すれば、あのBloodpetalの害虫を追い払うのにうってつけのはずさ。\n\nzapperの試作品を一つ貸してあげられるけど、燃料は自分で集めてもらわなきゃならない。zapperに必要なAtal'ai hazeは、Atal'Hakkarの神殿で手に入る。deep lurkers、murk worms、oozesから取ってくる必要があるよ。", "もううんざりだ、{name}。あいつら、どうしても私を放っておいてくれない!", "じゃあ、Marvonはいなかったのか? ま、とにかく手に入れたものを見せてくれ。", 0xce60817d, 0x19bd60e0, 0xb4760e21, 0xcda34d1b, 0xde182db0, "....." },
  [4147] = { "Marvonの工房", "RatchetにあるMarvon Rivetseekerの工房へ向かって下さい。", "Muiginが何をしてるのか偵察してみたら、あいつ、向こうであの厄介なやつを本当に育ててるんだ!\n\n解決策はただ一つ……いや、あいつと話しに行くんじゃないよ……何を考えてるんだい? 解決策は反撃することさ!\n\nRatchetに工房を持ってる友達のMarvonの助けが要るね。きっと何か役に立つ道具を作ってくれるはずだ。", nil, "Marvonがいなくなってからずいぶん経つな、{name}。彼は古代のトロールの遺跡を調べにTanarisへ行ったんだ。\n\nさて、何が必要だと言っていたかな?", 0x5c3474ce, 0x419285da, 0x9670b486, nil, 0x1f082263, "...m." },
  [4148] = { "Bloodpetal Zapper", nil, nil, "zapperを動かすには、標的となる生き物のサンプルが必要だ。クレーターに出て、Bloodpetal sproutを集めてきてくれ。そうすれば、Muiginのちっちゃなお友達に効くよう調整できる……\n\nあいつがあんなに頑固でなけりゃ、今ごろはもう家路についていられたのに……でもそれまでは、あいつのちょっとしたいたずらなんて全然気にしてないってところを見せてやるさ!", "これは完璧に働いているようだぞ、{name}。でも覚えといてくれ。あの害虫どもをその辺で見かけたら、遠慮無く虫取り機をお見舞いするんだぞ!", 0xfd71cf63, nil, nil, 0x10421a0e, 0x60d9e5d7, ".mm.." },
  [4161] = { "Kaldoreiのレシピ", "DolanaarのZarrinにSmall Spider Leg 7本を渡して下さい。", "遠い昔、ナイトエルフはkaldoreiと呼ばれていました。それは「星の子ら」を意味する名です。過去を学ぶことは、{class}としてのあなたの道において大切な一歩です、{name}。ですから、私がこれから話すことをよく聞いてください。\n\nkaldoreiは昔から、自然との調和した関係を誇りとしてきました。つまり、私たちは自然から必要なものだけを取り、同じだけを返すということです。この均衡は、私たちに多くをもたらしてきました、{name}。\n\n外へ出て、small spider legsを7本集めてきてください――それ以上はいけません。そして私のもとへ戻ってきてください。", "均衡を忘れないでください、{name}。あなたには、生きている森への理解と深い共感を育んでほしいのです。", "今日教えたことを常に忘れずにいてくれ、{name}。苦難の時代の間でさえ、ナイトエルフが手つかずのままに保とうと努力した調和の一部が君なのだから。", 0xc790841a, 0x7c7f5405, 0x2a2ed2f9, 0xb7a98f7e, 0xbe9fad73, "....." },
  [4181] = { "Goblin Engineering", "Goblin Engineeringについて詳しく学びたいのであれば、Manual of Engineering DisciplinesをGadgetzanのNixx Sprocketspringに渡して下さい。", "専門レベルの工学は、ノームとゴブリン、二つの分野に分かれる。私は公平なトレーナーだから、わざわざゴブリン工学について述べてやったまでだ。あいつらは爆発物を作るのが好きなんだ。しかも、何を爆発させるかってことも滅多に気に掛けやしない……自分自身を爆発させることすらな。\n\n{name}、このマニュアルを読め。自分自身の爆発方法が知りたいのなら、これを持ってGadgetzanのNixx Sprocketspringのとこへ行け。忘れるなよ……会員資格は永久のもので、もう一方の分野に入門することはできなくなる。だから、あいつの仕事を終える前には必ず確認しろよ。", "新入りの匂いは、上等な発破粉と同じように嗅ぎ分けられるんだ――一マイル先からでもな。爆発の極意を学びに来たのかい?", "さて{name}、オレの指導を請いにくるとは賢明だな! どんなのろまだって工学基礎の専門家になれるぜ……ノームどもや、放射線を浴びたあいつらの故郷Gnomereganがその証拠さ。もっとも、Goblin Engineering分野を修得するには強い心としっかり動く手（「しっかり」ってとこが肝心だ）が必要だがね。\n\nよく聞けよ{name}、そうすりゃ何かしら学べるだろうよ。", 0x4ccb3e9c, 0x84f932f9, 0x52e16ce5, 0x21f4153d, 0xad63c1bf, "....." },
  [4182] = { "ドラゴン族の脅威", "Black Broodlingsを$N1体、Black Dragonspawnを$N2体、Black Wyrmkinを$N3体、Black Drakeを$N4体倒す。任務を終えたらHelendis Riverhornのところへ戻って下さい。", "Burning Steppesの暮らしは争いに満ちている。\n\nこの場所を見てみろ！この建物に何が起きたのかはほとんど分かっていないが、かつて、あの大爆発の前には、ここ一帯がRedridgeの山脈の一部だったことは分かっている。\n\n嘆くのはもう十分だ！問題が起きているのだ、{name}。この尾根の下にいるdragonkinに気づいたかもしれんな。奴らを押し返すのに助けが要る。できるだけ多く倒して、私のもとへ戻ってこい。うまくいけば、他のことについても話せるだろう。", "dragon狩りの調子はどうだ?", "見事な討伐だ、{name}。君がdragonkin相手でも立ち回れると分かった以上、もっと差し迫った問題について話ができる。", 0xdfeea486, 0xabbd80aa, 0xb7f67c45, 0x19b535d2, 0x8c7f9f97, "....." },
  [4183] = { "真の主", "Lakeshireへ行き、Helendis Riverhorn's LetterをMagistrate Solomonに届けて下さい。", "我々はずっと、Blackrockのオークは野蛮な生い立ちの産物だと思い込んでいた。だが、奴らの故郷であるここで見つけたものは、別の物語を語っている。\n\n確かに奴らに力を与えているのは血への渇望と争いへの渇きだ。だが、Blackrockのオークを操っているのはblack dragonflightなのだ。奴らに怒りと敵意を吹き込んでいるのはblack dragonflightではないかと、我々は疑っている。\n\nこの手紙をMagistrate Solomonへ届けてくれ。彼なら何をすべきか分かるはずだ。\n\n<Helendisは封をされた手紙を手渡す。>", "ごきげんよう、{name}。前にお会いしましたか? どこか見覚えがあるような気がします。", "<Magistrate SolomonはHelendisからの封をされたletterを開け、読み始める。>", 0xbd06798d, 0xed52da00, 0x543942a4, 0x4e21dce5, 0xd73bb7e3, "....." },
  [4184] = { "真の主", "Stormwindへ行き、Solomon's PleaをHighlord Bolvar Fordragonに届けて下さい。\n\nBolvarはStormwind Keepにいます。", "これは深刻な知らせだ、{name}。宿敵が、はるかに大きな脅威の手駒にすぎなかったと知るのは、気の滅入ることだ。Blackrockのオークとblack dragonflightの両方から攻撃されて、Lakeshireが持ちこたえられるはずがない。Lakeshireがこの脅威に屈すれば、次はDarkshireが落ち、その次はどうなる？Goldshireか？Stormwindそのものか？\n\nこの情報を今すぐStormwindのHighlord Bolvar Fordragonへ届けねばならん！これでStormwindの助けが得られないのなら、何をしても無駄で、すべては終わりだ。", "Stormwind Keepへは何の用で来た?", "ドラゴンだと？ありえん！", 0xbd06798d, 0x7d939500, 0x5a607832, 0x46dba375, 0xdc21b8a7, "....." },
  [4185] = { "真の主", "Lady Katrana Prestorと話した後、Highlord Bolvar Fordragonと話して下さい。", "Solomonは暗い絵を描いているな。それでも、手薄な我が軍を憶測だけでLakeshireの救援に送る余裕はない。行動を起こす前に、その主張の証拠が必要だ。\n\nLady Prestorと話してくれ、{name}。彼女は博識な女性で、dragonsやdragonkinについてよく知っている。この状況に光を当ててくれるかもしれん。", "<Bolvarはあなたをじっと見つめている。>", "<Bolvarは深く考え込むように顎に手を当てる。>\n\nLady Prestorの立場は尊重するが、この難題には我々の懸念をすべて解消できる解決策があると私は考えている。", 0xbd06798d, 0x1c7cac7b, 0x0605fa2a, 0xf573156f, 0xb8069479, "....." },
  [4186] = { "真の主", "Bolvar's DecreeをLakeshireのMagistrate Solomonのところへ持って行って下さい。", "{name}、お前にStormwindの代理保安官としての権限を与える。\n\nLakeshireのMagistrate Solomonのもとへ戻り、この布告を届けるのだ。", "Bolvarから何か知らせは?", "もっと悪い事態もあり得たのだろうな……\n\n<Magistrate Solomonがあなたを見定める。>\n\nLakeshireの運命は、まさしく君の双肩にかかっているようだ。\n\n<Magistrate Solomonが何度も瞬きしているのに気づく。泣いているようだ。>", 0xbd06798d, 0xd9291348, 0x8fe82101, 0x29467338, 0xdaa3533e, "....." },
  [4201] = { "ラブポーション", "Gromsblood 4つ・Giant Silver Vein 10個・Nagmara's Filled VialをBlackrock DepthsのMistress Nagmaraに渡して下さい。", "ああ、恋の苦しみ! 愛しいPrivate Rocknotは私の魅力になびいてくれないの。振られてしまったわ! 気が狂いそう!\n\n助けてちょうだい! 私たちsuccubiは恋についてよく知っているの。Rocknotの心を囲む鉄の壁を打ち崩す薬を作れるわ。それを作るには、これらの品が要るの。薬草のgromsblood、Azsharaのcliff giantsから取れるgiant silver veins、それにUn'GoroのGolakka Springs Craterの水よ。水はこの小瓶に入れてちょうだい。\n\nお願い、{name}、幸せを求めるかわいそうな魂を助けて!", "材料は持ってきたか? 心に空いた穴が私を飲み込もうとしているんだ!", "ああ、やってくれたのね! これでpotionを作って、Rocknotに使えるわ。ついにあの人も私の魅力の虜になるのね!\n\nありがとう、{name}。あなたは愛の勇者よ!", 0x0c588f7b, 0x0039f407, 0x77c49719, 0x918f01f8, 0x128e9506, "....." },
  [4223] = { "真の主", "Burning SteppesのMarshal Maxwellと話して下さい。", "<Magistrate Solomonはため息をつく。>\n\nBurning Steppesへ戻らねばならん、{name}。Stormwindの保安官として、Marshal Maxwellのもとへ出頭することになる。幸運を祈る。", nil, "<Marshal Maxwellが笑う。>", 0xbd06798d, 0xb198a748, 0x6a799072, nil, 0xc32699c8, "...m." },
  [4224] = { "真の主", "Ragged Johnと話してMarshal Windsorの運命を聞き出し、それが済んだらMarshal Maxwellのところへ戻って下さい。\n\nMarshal Maxwellが、北の洞窟で彼を探すよう言っていたのを思い出す。", "何だと？自分が最初だと思ったのか？Stormwindが動くまでに、あと何人の兵士を失えばいいんだ？\n\n我々は、指揮官のMarshal Windsorを失う前に、Blackrockの脅威に関する膨大な情報を蓄えていた。Marshal Windsorと共に、我々の貴重な情報はすべて失われてしまった。\n\n我々に必要なのはその文書だ。Ragged Johnと話してくれ、{name}。Blackrockの襲撃隊に襲われたとき、彼はWindsorと一緒にいた。最後に見かけられたのは北の洞窟だ。", "もうJohnとは話したか?", "警告してやることもできたが、それじゃ面白くないだろう？", 0xbd06798d, 0xe71a4237, 0xeaa13190, 0xc653067b, 0xc3b308c7, "....." },
  [4241] = { "Marshal Windsor", "北西のBlackrock Mountainへ行き、Blackrock Depthsに入る。Marshal Windsorがどうなったのか突き止めて下さい。\n\nRagged Johnが、Windsorは牢獄へ引きずられていったと話していたのを思い出す。", "で、あのろくでなしの臆病者が、Windsorは生きてると言ってるんだな?\n\n支度をしろ、保安官補。お前が中へ入って奴を見つけるんだ。Windsorが生きていれば連れ戻せ。死んでいたら証拠が欲しい。\n\n<Maxwellが笑う。>\n\nその台詞はもう聞き飽きたんじゃないか?", nil, "あいつはどこにいる! あいつ殺してやる!", 0xfc494245, 0x3384adf6, 0xeaea3da0, nil, 0x512c23ab, "...m." },
  [4242] = { "見捨てられた希望", "Marshal Maxwellに悪い知らせを伝えて下さい。", "Bolvarは愚か者だ。私は奴の大事な「証拠」を集めていたのだ。それを奴の喉に突っ込んでやるためにな。\n\n奴は目の見えない道化だ。証拠は奴から二フィート先に立っているというのに、奴には見えていない。\n\n私の資料なら、失われた。消えた。取り戻せん。\n\nもしIronfoeを見つけ、この迷宮から抜け出せたなら、真っ先にStormwindへ行って、あの爬虫類の眉間に我が槌を叩き込んでやる。\n\n放っておいてくれ、{name}。", nil, "どうやら、正気を失ってしまったらしい。\n\n<Maxwellは弔うように頭を垂れる。>\n\nかつて誇り高く高潔なウォリアーだった者が、訳の分からないことを口走る狂人になってしまうとは、残念なことだ。どうやら手詰まりのようだな……\n\nここまでの働きに報いねばならん、{name}。", 0x18d81581, 0xaf9e4272, 0x1149b9ac, nil, 0x9d83dbab, "...m." },
  [4243] = { "A-Me 01を追って", "Un'Goro CraterでA-Me 01を見つけて下さい。", "残念なことに、私の最高の発明品の一つに何かが起きてしまったの。機械仕掛けのリスは見たことあるでしょう？それでね、Un'Goro Craterの類人猿にもっと近づくために、仲間に紛れ込める機械の猿を作ったの――A-Me $N1って呼んでるわ。\n\n彼女の目には遠見の宝石がはめてあって、彼女が見るものは全部私にも見えたの。彼女はここからすぐ東にある猿たちのねぐら――Fungal Rock――にたどり着いて、そこで連絡が途絶えたの。最後に見えたのは、群れのボスの雄が彼女に挨拶しようと駆け寄ってくるところだったわ！\n\n彼女を見つけるのを手伝ってくれる？", nil, "A-Me 01を調べると、Karnaが見事な工学の産物だと明らかに自負している機体を台無しにする、2つの大きなへこみが見つかった。へこみの1つはA-Me 01の肩に、もう一方は頭にある。\n\nさらに調べてみても、部品に動力が通っている様子はない。", 0x7c38c0dd, 0x54e97f2d, 0xa3b65232, nil, 0xd5a67418, "...m." },
  [4244] = { "A-Me 01を追って", "Mithril Casingを見つけ、Un'Goro CraterのA-Me 01のところへ戻って下さい。", "さらに少し調べると、横に開くパネルが見つかった。配線の上には「Replace Mithril Casing And Turn Power Off Then On.」とはっきり書かれている。\n\n少し時間をかけてパネルを元に戻しながら、A-Me $N1を直してMarshall's Refugeの近くにいるKarna Remtravelのもとへ連れ帰るのが、それほど簡単なことなのだろうかと考える。\n\n試してみなければ分からない。", "mithril casingをはめ込むパネルは、まだ固く閉じたままだ。A-Me 01の他の部分も動かないままになっている。", "もう一度A-Me 01の背中のパネルを外し、焼き切れたらしい古いmithril casingを慎重に取り外す。新しいものはすんなりと収まった。mithril casingが原因だったとすれば、あとはスイッチを「Off」にしてから、再び「On」に戻すだけだ。", 0x7c38c0dd, 0xbfa92269, 0x3df9140d, 0xcc306a17, 0xaabfcb7d, "....." },
  [4245] = { "A-Me 01を追って", "A-Me 01をUn'Goro CraterのKarna Remtravelのところまで護衛して下さい。", "A-Me 01をKarna Remtravelのもとへ連れて行く準備ができているか確かめるため、あなたはスイッチを「Off」の位置に切り替えた。gorillaが近づいてこないことをもう一度見回して確かめ、スイッチを「On」の位置に戻すと何が起きるか見届ける準備をする。\n\nこれが最後のチャンスだ……本当にこうしたいのか？", "A-Meを助けてあげられたかい? 壊れたとあなたが言っていたmithril casingは、何が悪いのかについての良い推測だった。それを取り替えれば、きっと彼女は再起動して家に帰ってこられるはずだ。", "ああ、やってくれたんだね！素晴らしい！ありがとう、{name}。\n\nああ、かわいそうなA-Me。見てよ、このへこみだらけの体。ちょっと手を入れれば、また完璧に動くようになるさ。\n\n本当にありがとう、{name}。心から感謝してるよ。", 0x7c38c0dd, 0x7bc069c4, 0xef525037, 0xd8a1a554, 0xa0ae5ea0, "....." },
  [4261] = { "古代の霊", "Areiを安全な場所まで護衛し、Ashenvale東部のForest SongにいるKayneth Stillwindと話して下さい。", "Felwoodはかつて、平和で穏やかな地でした……legionがこの地を支配するまでは。infernals、破壊、混沌……\n\nskull of Gul'danは、ここで誰一人容赦されないようにしました。すべてが堕落に屈したのです。\n\n霊となった今でも、私はこの地の苦しみを背負ったまま囚われています。どうか家へ帰る道を見つける手助けをしてください。お願いです、{name}、古の霊をここから連れ出し、ようやく安らげる場所へ導いてくれると言ってください。\n\n私が自由になったら、東のForest Songに住むドルイド、Kayneth Stillwindを訪ねてください。", "この汚染された地で、何を見てきた?", "ええ、{name}。Felwoodは多くの苦難をくぐり抜けてきました。あなたがしてくれたことに感謝します。\n\nいつの日か、Felwoodを腐敗から取り戻せるかもしれません。どんな親切な行いも助けになるのです。", 0xf60d4691, 0xf3e6d0be, 0x898bc0e8, 0xb22926ad, 0x5a009e5c, "....." },
  [4262] = { "Overmaster Pyron", "Overmaster Pyronを倒し、Jalinda Sprigのところへ戻って下さい。\n\nJalindaが、Pyronは採石場を守っていると話していたのを思い出す。そこを探してみてはどうだろう?", "Blackrock Mountainを嗅ぎ回りに行った私のメイジのうち最後の5人は、こんがり焼けて、オレンジ色のノームアフロが消えなくなって帰ってきたわ――それか、もっとひどい姿でね。\n\n<Jalindaは地面から灰をすくい上げ、宙に放つ。>\n\n中でも特に厄介なのが、Overmaster Pyronってやつで、かなり面倒を起こしてるみたい。探検隊がBlackrock Depthsへ入れるように、あのエレメンタルを始末してほしいの!\n\nあいつはBlackrock Quarryの入口を守ってるわ。", "<Jalindaはあなたの頭をじっと見つめているようだ。>", "Incendius? あらま……。", 0x3d05b08b, 0xc6e54e09, 0x41ef67d4, 0xfe41a547, 0x1d836ddd, "....." },
  [4263] = { "Incendius!", "Blackrock DepthsのLord Incendiusを見つけ、滅ぼして下さい!", "Pyronが死ぬとき、本当に「Incendius」って言ったの?\n\n<Jalindaはごくりと唾をのむ。>\n\nLord IncendiusはRagnarosの手下だって噂よ! ああどうしよう、どうしよう……いったいどうすればいいの?\n\nもう一つ任務をこなせそう? ほかに送れる人がいないのよ、{name}!\n\nIncendiusが灰の中からPyronを蘇らせ続ける限り、部隊を送り込むことなんてできないわ。\n\nLord Incendiusを見つけて倒してちょうだい!", "あの悪鬼は死んだのか??", "まあ大変! Incendiusが「Ragnaros」と言ったのは確かなの?\n\n<Jalindaはあなたに何かを手渡し、手首を軽く叩くと、深い物思いに沈んでいく。>", 0x0aa8e793, 0x60dd505c, 0x47a4390d, 0x20a3fc8b, 0x0d0d9cfd, "....." },
  [4264] = { "A Crumpled Up Note", "Marshal Windsorが見たがりそうなものに、たまたま行き当たったのかもしれない。結局のところ、まだ望みはあるのかもしれない。", "メモの表面は染みだらけだ。文字はほとんど読めないが、次のように読み取れる。\n\n……皮肉なことに……\n\n……崩れゆくAllianceの没落……\n\n……General Angerforgeの勤勉さがなければ、暗号のパターンを見抜くことはできなかったかもしれない……\n\n……ArgelmachはWindsorのメモの解読をほぼ終えている。\n\n我らが主は深淵より蘇り、残る者すべてを打ち砕くであろう……\n\n-Emperor Dagran Thaurissan", "<Marshal Windsorはあなたの手にあるメモに目をやる。>\n\nそこに何を持っている、{name}?", "<Marshal Windsorはメモを受け取り、読み始める。>", 0x9789540e, 0x96684b0f, 0xbb86b357, 0x156cf5b2, 0xdaeb689e, "....." },
  [4265] = { "巣からの解放", "Zukk'ashの巣からRaschalを救い出す。\n\nFeathermoon StrongholdのGinro Hearthkindleのところへ戻り、Raschalが無事に生きていることを知らせて下さい。", "触れると莢がいくらか割れ開き、驚いたことにまだ生きているナイトエルフの男性が現れた。ひどく呆然としてはいるが、健康状態は良さそうだ。莢から下ろしてやると、彼は意識を取り戻した。\n\n「Eluneに感謝を――助けてくれたんだね、友よ！ぼ……僕はRaschal。この虫たちに襲われて、気がついたらこの莢の中で体が動かなくなっていたんだ。Strongholdから送られてきたのかい？」\n\nどうやら、行方不明の伝令を見つけたようだ！", "何か報告があるのか、{name}?", "おかえりなさい、{name}。ついさっきRaschalが戻ってきて、何があったか話してくれました。\n\n私は……いえ、Stronghold全体でさえ、あなたの偉業にどう感謝すればいいのか分かりません。あなたの時宜を得た助けがなければRaschalは死んでいたでしょう。しかもあなたは、傭兵の報酬など一言もささやくことなく手を貸してくれました。あなたには真の英雄の証があります。Ginro Hearthkindleにはいつでもあなたの友がいることを覚えておいてください。", 0xe090d26e, 0xc1b8edb5, 0x3c699a4e, 0x2ff3a2d1, 0x73a57ae8, "....." },
  [4266] = { "英雄の歓迎", "Feathermoon StrongholdのShandris Feathermoonと話して下さい。", "{name}、General Shandris Feathermoonがあなたと直接話したいそうです。Strongholdへの貢献に感謝したいのはもちろんでしょうが、あなたとRaschalがFeralas南部で遭遇した昆虫の生き物についても話したいのだと私は知っています。あのZukk'ashの昆虫に関する報告は……控えめに言っても恐ろしいものです。\n\nGeneral Feathermoonが本部の建物であなたを待っています。", nil, "{name}、私たちに力を貸してくれたことに心から感謝します。圧倒的に不利な状況でのあなたの勇敢さは、1000倍の価値がある報酬に値するものです。それでも、Stronghold全体を代表して、これを受け取ってもらえればと思います。\n\nさて、よろしければ……もう1度だけ力を貸してほしいのです。ここFeralasでZukk'ashの巣が発見されたことを踏まえると、この任務にはあなたが最適だと思います。", 0xfc173165, 0x7bd0a992, 0xf15db714, nil, 0x846faacd, "...m." },
  [4267] = { "Silithidの台頭", "Raschal's ReportをDarnassusのGracina Spiritmightのところへ持って行って下さい。", "Feralas南東部の侵食についてRaschalが書いた報告書の写しを、あなたに託します。本物の報告書はDarnassusに提出されるところですが、この写しはProtectorateの協力者に渡してほしいのです。彼女の名はGracina Spiritmight。DarnassusのTemple of the Moonに住むプリーストです。この種の生き物について幅広い知識を持っていて、彼女がこの報告書を受け取ることは我々皆のためになるでしょう。\n\n下がってよろしい――幸運を、{name}。Eluneが我々皆を見守ってくださいますように。", "この祝福された神殿へようこそ、友よ。あなたがFeathermoon Strongholdからここへ来ることは、私に予言されていました。Shandris Feathermoonに頼まれたreportは持ってきましたか?", "我々ナイトエルフは、このreportに記された恐怖を知っている。Shandrisがこれを、そして君を私のもとへ送ったのは賢明だった。\n\nこの生き物どもは、瞬く間にFeralasを食い尽くすだろう。我々が直面する最大の脅威の1つに他ならない。君と伝令が遭遇した虫はsilithidと呼ばれている。奴らは、HordeとAllianceの双方がこれから直面する最大の脅威の1つが操る、単なる道具にすぎない。\n\n奴らに滅ぼされる前に、奴らを打ち倒す決意を我々が持てることを祈っている。", 0x50a8e84e, 0x39f5732a, 0xda5712a8, 0x26cf8b80, 0x993d1f4d, "....." },
  [4281] = { "Thalanaarへの配達", "Undelivered ParcelをThalanaarのFalfindel Waywarderのところへ持って行って下さい。", "Woodpawのgnollの野営地で見つけたこの荷物の包みは、Feralas南東部にある小さな中継所、Thalanaarへ届けられるはずのものだった。行方不明の伝令の運命がどうであれ、包みを届ける務めはまだ果たされていない。\n\n包みを詳しく調べると、包装の外側に「Falfindel Waywarder」という手書きの名前がある。おそらく、この包みの最終的な受取人なのだろう。", "Thalanaarへようこそ、{class}。何かお困りですか?", "Eluneに称えあれ、Feathermoon Strongholdからの配達がようやく届きました！\n\nあなたがここにいるということは、いつもの伝令のRaschalに何か不幸があったのかもしれませんね。何事もなければいいのですが。最近、Woodpawが南の方にある何かのせいで、ひどく気が立っていると聞いています。彼はそこの荒野で倒れたのかもしれません。気をつけてください、友よ。\n\nいずれにせよ、改めてありがとう。このparcelの配達の代金です。", 0x86751311, 0x715b3184, 0x7c56c873, 0xc22061a9, 0x3e39cede, "....." },
  [4282] = { "一縷の望み", "Marshal Windsor's Lost Informationを持ち帰って下さい。\n\nMarshal Windsorは、その情報をGolem Lord ArgelmachとGeneral Angerforgeが持っていると考えています。", "<Marshal Windsorは興奮した様子でメモを振る。>\n\nこれが何を意味するか分かるか、{name}？\n\nまだすべてが失われたわけではないかもしれん！私の見たところ、情報は二人のDark Ironのドワーフが握っている。General Angerforgeと、golemの王Argelmachだ。丁寧に頼んだところで、奴らがおとなしく情報を渡すとは思えん。\n\n戦う覚悟ができているといいのだが。\n\nさあ行って、この二人の悪党を見つけ出せ！奴らを倒し、失われた私の情報を取り戻してくれ。", "この壮大な策略も、まもなく終わる。", "<Marshal Windsorがあなたの手から2枚の石板をひったくる。>\n\nここから脱出するぞ！", 0x7552658d, 0x79cbd014, 0x9c91d3ba, 0x9e2f8766, 0x6fc11e3f, "....." },
  [4283] = { "五十！そうだ！", "OraliusはBlackrock Medallionsを$N1個欲しがっています。このメダルはBurning Steppesのオークが持っている可能性が高い。", "ちょっとした秘密を教えてやろう、兵士。もう少し近くへ来い。\n\nここでまともなのは俺だけだ！\n\nこいつらを見てみろ！全員いかれてるなんて信じられるか！？だが本当なんだ！狂ってる！イカれてる！\n\n<Oraliusは声をひそめる。>\n\nこのことは俺とお前と、俺の相棒Captain Winkyだけの秘密にしておこう。\n\n<Oraliusは宙をつかんで握りしめる。>\n\nさぁぁてと……俺はogreの耳のコレクションに加えるために記章を集めてるんだ。今日のお題はオークだ。五十個。行け！\n\n<Oraliusは角笛を吹き鳴らす。>\n\nさっさと送れ！", "<Oraliusはやけに大きな、切り落とされたogreの耳に向かって話している。>\n\nこちらBurning Steppes、管制どうぞ、管制応答せよ。", "やったな！お前の報酬は……オレのハラをなでろ！さあ！なでるんだ！", 0x49e363b1, 0x950922a4, 0xed66611f, 0x3c92225b, 0x6d088a18, "....." },
  [4284] = { "力の水晶", "赤、青、黄、緑の各色のPower Crystalsを$N1個ずつ集める。それらをMarshal's RefugeのJ.D. Collieのところへ持って行って下さい。", "{name}、きっともう気づいてるよね。そこらじゅうにあるんだから！\n\n何の話かって？そりゃもちろん、結晶のことさ！\n\n結晶……クレーターのあちこちにあるんだ。たいていの人は気にも留めないけど、僕はあの中に力が秘められているような妙な気がするんだよね。しばらくここであれを使って実験してるんだけど、何も見つからないみたいでさ。まあ、今のところはね。\n\nねえ、ここにある結晶が少なくなってきたんだ――もっと集めてきてもらえないかな？", "ここで何かをつかみかけている気がするんだ、{name}!", "これで実験を続けられる！ありがとう、{name}。", 0xedd2dec0, 0xdcba8660, 0x019c0134, 0x003104a5, 0x9e8cf347, "....." },
  [4285] = { "北のパイロン", "Un'Goro CraterにあるNorthern Crystal Pylonの場所を突き止めて下さい。", "一体何のためのものなんだろう？考えが頭から離れないんだ！\n\n気が変になりそうだよ――結晶のパイロンについて聞いた噂が全部本当だなんて。だまされやすいと言われてもいいけど、僕はたいてい人の言うことは何でも信じちゃうんだ。\n\nとにかく、結晶のパイロンの一つがかなり近くにあると聞いたんだ。北のどこかに……どうか見つけてきて、{name}。絶対にあるはずなんだ。", "パイロンにはもう行ってみたかい、{name}?", "あの話が本当だということは分かっている、{name}。", 0xf3d0a1fe, 0x2bb1828c, 0x8de93a1a, 0x621cc580, 0x3f0cf7a7, "....." },
  [4286] = { "いいもの", "Blackrock Depthsへ行き、Dark Iron Fanny Packを20個回収してください。この任務を終えたらOraliusのところへ戻ってください。Blackrock Depthsの中にいるDark Ironのドワーフたちがこの「fanny pack」という装置を持っているはずだと、あなたは考えている。", "Captain Winkyが言うには、DepthsにいるDark Ironsがいい物を全部持ってるんだとよ。そうだろ、Winky?\n\n<Oraliusは精いっぱい海賊の物まねをする。>\n\nアーッ、野郎ども! そのとおりだぜ!\n\nな、言ったとおりだろ? お前さんが乗り込んで、そのいい物のサンプルを持って帰ってきてくれ。\n\nさあ乗り込んで、思いっきり稼いでこい!", "今は相手してる暇はねえんだ、{name}。俺とWinkyは会合に出なきゃならねえからな。", "<Oraliusがうずたかく積まれたfanny packsを漁り始める。>\n\nおお、素晴らしい!\n\n<Oraliusは大きな鼻を山に突っ込んで、匂いを嗅ぐ。>\n\nうまそうだ! この宝の山を見ろ!\n\n1つ持っていけ、{name}。まだたっぷりあるからな。", 0x03b00c96, 0xacbdd946, 0xa0176a01, 0x0f33f571, 0x49389889, "....." },
  [4287] = { "東のパイロン", "Un'Goro CraterにあるEastern Crystal Pylonの場所を突き止めて下さい。", "ここにいる間に、クレーターの荒野に謎のパイロンがあるという奇妙な噂を耳にしたんだ、{name}。かなり大きくて、内側に結晶が並んでいるらしい。\n\n一度も見たことはないけど、その噂は本当なんじゃないかと思えてならないんだ――そしてパイロンは、僕たちが見つけたあの結晶全部と何か関係があるんじゃないかって\n\nだから、僕の好奇心を満たす手伝いをしてくれない？クレーターの東の方に一つあるらしいんだ。見つけられそうかな？", "パイロンにはもう行ってみたかい、{name}?", "Un'Goroは本当に不思議な場所だよ、{name}。クレーターに入ると、まるで全く別の世界にいるみたいなんだ……", 0x4dda2441, 0xf431d0bd, 0x88915476, 0x621cc580, 0x1d19888e, "....." },
  [4288] = { "西のパイロン", "Western Crystal Pylonの場所を突き止めて下さい。", "これまでの実験では良い結果が出ていないんだ、{name}。噂に聞くパイロンの一つを探せば、君が答えを見つけてくれるんじゃないかと期待せずにはいられないよ。\n\nもしかしたら、そこで特定の色を組み合わせれば……いや、先走りすぎだね。まずは見つけよう！\n\n{name}、クレーターの西の方を探してみて。パイロンがそのあたりのどこかにあるらしいんだ。", "パイロンにはもう行ってみたかい、{name}?", "クレーターの縁沿いには隠れた場所がたくさんある。他に探す場所が思いつかないなら、曲がりくねった道を探索してみるといい、{name}。", 0xa0dbd578, 0xb2bb5879, 0x47fd20e0, 0x621cc580, 0xc9cda7e2, "....." },
  [4289] = { "Un'Goroの類人猿", "Un'Goro Gorilla Peltsを$N1枚、Un'Goro Stomper Peltsを$N2枚、Un'Goro Thunderer Peltsを$N3枚、Un'Goro Craterの入口にいるTorwa Pathfinderのところへ持って行って下さい。", "このクレーターには奇妙な生き物がたくさんいる――我が故郷やその先で見られる生き物の、より気高い姿のようだ。説明はできないが、この地はEarth Motherを叫び求めている。その盆地を越えて彼女の美しい生き物を追うたびに、私は彼女に敬意を捧げている。\n\nそなたもまた、このような偉業に伴う悟りを感じたいのなら、北へ向かうがよい。そこには、どんな定命の者の力をも試す大きな猿がいる。その毛皮を持ってくるのだ……そなたの強さを証明せよ。", "ここの獣たちにもう打ち負かされてしまったのか、{name}?\n\nそう簡単に諦めてはならぬ。Un'Goroの類人猿を追跡して倒すのは、偉大なハンターであっても容易なことではないのだ。", "そうか、お前は強さを示した。Un'Goroの大猿どもを打ち負かすほどにな。それは良いことだ。Lar'korwiに比べれば小さな試練だが、これほどの大勝利をお前から取り上げるつもりはない。\n\nこのpeltは我が部族の素晴らしい衣となるだろう。お前は私を助け、その価値を示した。\n\n次の任務へ出発する前に、Earth Motherに賛美を捧げ、お前が倒した猿たちの霊に感謝しよう。奴らは、自らの死が無駄にならないことを知らねばならない。", 0xfa7981d5, 0xb8452ff9, 0x8a6c2536, 0x9a5e61a3, 0x1acd5cfd, "....." },
  [4290] = { "Lar'korwiの食事", "Lar'korwiが最近仕留めた獲物の死骸を見つけてPiece of Threshadon Carcassを盗み、Un'Goro CraterのTorwa Pathfinderのところへ戻って下さい。", "昔、ずっと昔のことだ。私の兄弟の一人が、Lar'korwiの獲物から肉を少し持ち去った。そのときは知らなかったが、Lar'korwiは森から兄弟を見ていたのだ。Lar'korwiは何日も兄弟の後をつけ、兄弟が触れたものをすべて壊していった。怯えた兄弟はついにCraterから逃げ出し、Lar'korwiを置き去りにしようと決めた。\n\nLar'korwiは、この場所からそう遠くないところで兄弟を殺した。\n\nLar'korwiを挑発したいなら、奴が仕留めたばかりの獲物を見つけ、その肉を少し取ってくるのだ。\n\nそのあと、私のもとへ戻ってこい。", "私の言葉を軽く受け止めてはならぬ、{name}。本当にあの獣に立ち向かいたいのなら、慎重に……そして賢くなければならない。Lar'korwiをおびき出して倒すには、大いなる力と洞察が必要となるだろう。", "これで十分だ、{name}。Lar'korwiは近頃いいものを食っているようだな。それにしても、この辺りのどこでthreshadonを見つけたのだろう。妙だ。\n\nいずれにせよ、お前があの獣と対決する準備ができるまで、これは私が預かっておく。私の身の心配はいらない。お前はLar'korwiを十分に怒らせたから、奴はお前の肉を味わうまでは私を殺しはしないだろう。", 0x0e9e1295, 0x8910cd62, 0x518db117, 0xa0cac4a3, 0x76953a16, "....." },
  [4291] = { "Lar'korwiの匂い", "Ravasaur Pheromone Glandsを$N1個、Un'Goro Craterの入口近くにいるTorwa Pathfinderのところへ持って行って下さい。", "奴がまだそなたを狙ってこないとは、実のところ驚いている、{name}。だが心配はない。あの怪物を我々のもとへおびき寄せる最後の策があるのだ。\n\n群れを支配する雄であるLar'korwiには、好きな雌と交わる権利がある――そして奴は多くの雌を選ぶ。ここから西に、ravasaurの卵がたくさん見つかるはずだ。卵に近づけば、奴のつがいが襲ってくるだろう。雌は頭にある腺からひどい臭いを出し、繁殖の準備ができたことを雄に知らせる。その腺を二つ持ってきてくれ。", "気をつけるのだ、{name}。卵の巣に近づけば、必ず母親たちを怒らせることになる……たとえ、すでに1匹からglandを手に入れていたとしてもだ。子を守るために戦う母親たちは、Lar'korwi自身に劣らず危険だ。だが、うまくいけば、Lar'korwiを隠れ場所から確実におびき出す手段が手に入るだろう。", "ああ、見事な標本だ、{name}。お前が見つけた2つの部位は、Lar'korwiをおびき出すのにうってつけだろう。お前とあの怪物の戦いの結末を見るのが待ちきれん。奴は最上の刃のように鋭い爪を持つ巨大な獣だ。奴の目を見れば、お前は死を知ることになるだろう。", 0x8285d67b, 0xbfe924ab, 0xa84a2745, 0xe71cf681, 0x056dbb9f, "....." },
  [4292] = { "Lar'korwiをおびき寄せる餌", "Torwa's Pouchの中身を使ってLar'korwiを呼び出し、倒して下さい。その後、Lar'korwi's HeadをUn'Goro Craterの入口近くにいるTorwa Pathfinderのところへ持って行って下さい。", "計画には込み入ったところがあるので、ここが最も難しい部分になるだろう。ここから北へ行くと、山へ続く小道がある。私が最後にLar'korwiを見たのはそこだ。かつてそのあたりをさまよっていた巨大な生き物の骨がたくさんあるので、正しい場所に来たことが分かるはずだ。取り戻した肉を持っていき、そこに置け。それから、私が作ったこの混ぜ物を肉にすり込むのだ。二つの誘い餌を混ぜ合わせてもLar'korwiがそなたのもとへ来ないのなら、ほかに打つ手は知らない。", "恐怖に呑まれてはならぬ、{name}。恐怖とは大いなる裏切り者だ……強くあり続けねばならない!\n\n肉を持って小さな谷に置き、その上で腺を使うのだ。そうして初めて、死がお前を迎えに来る。", "Earth Motherに称えあれ！やり遂げたな！見事だ、{name}。お前は紛れもなく偉大なハンターであることを示した。お前の魂は強い。その勇気は比類なく、その力はさらに鍛えられた。お前の技に頭を垂れよう。\n\nこれほど驚くべきことを成し遂げられるのは、我が祖先の中でも最も偉大な者だけだ。おめでとう。", 0xd073bce4, 0xadd6eb61, 0xf65328ef, 0xe006d62f, 0x9534f0ab, "....." },
  [4293] = { "スライムのサンプル……", "Felwoodのスライム(種類は問いません)からFelwood Slime Sampleを集めて下さい。それからUndercityにいるChemist Fuelyの隣にある検査機器を使い、あなたの持っているサンプルのうちどれが最も腐敗しているか調べて下さい。発見したCorrupted Felwood Sample5つをChemist Fuelyに渡して下さい。", "FelwoodはBarrensのはるか北、Ashenvaleよりもさらに向こうにある森だ。そこでは、Felの手に触れられた水たまりの周りのいたるところにslimesがいる。ScourgeはInfernalsやその他の悪魔の魔法による攻撃でその地域を壊滅させた――slimesはその攻撃の最中に地中から這い出してきたらしい。\n\nFelwood slimesのサンプルを集めてきてくれ。私の隣にある検査装置を使って対照群を作り、お前が集めてくる他のサンプルとの比較に使う。", "対照群のために、少なくとも5つのcorrupted samplesが必要なんだ、{name}。必要な分を渡せるようになるまで、Felwood slime samplesを集め続けてくれ。Lady Sylvanasの命なのだ……", "ああ、見事だ。このsamplesで十分だろう。協力に感謝する。\n\nslimeのsamplesをすべて集めれば、もっと多くのことが分かるはずだ。Lady Sylvanasの勘は正しかっただけでなく、彼女自身が予想し得たよりも鋭かったのではないかと思い始めている。このsamplesは実に興味深い。私の調合物にどう反応したかを見るだけでも……ふむ、そうだ、間違いなくさらなる調査が必要だな。", 0xdbdc006f, 0xb587688e, 0x0d16c5f9, 0xc2957eaf, 0x175de1db, "....." },
  [4294] = { "……そしてウーズの群れ", "Un'Goro Craterのスライム(種類は問いません)からUn'Goro Slime Sampleを集めて下さい。それからUndercityにいるChemist Fuelyの隣にある検査機器を使い、あなたが持っているサンプルのうちどれが最も純度が高いか調べて下さい。発見したPure Un'Goro Sample5つを、Chemist Fuelyに渡して下さい。", "Un'Goro Craterのことは聞いたことがあるか、{name}? Tanarisの砂漠の近くにあって、実に見事な場所だ。緑豊かで生き生きとしていて、生き物や植物に満ちている。\n\nお前が行くべきはそこだ。聞いた話では、その地は外部の手にまったく汚されていないようだ。探検家たちが今まさにその秘密を発見しつつある。\n\nそこのslimesかoozesを検査したい。それが本当なら――奴らが穢れていないなら――そのような生き物がどう進化してきたのか見てみたいのだ。", "はい、{name}? 探し物の具合はどうだい?", "実に驚くべきことだ、{name}。このUn'Goro Craterは、私が思っていたよりもはるかに多くの秘密を抱えている。さらに調べれば、他に何が見つかるだろうな。\n\nただただ驚きだ……このsamplesの純度を見てくれ。ふむ、これが何を意味するのだろうか。本質はelementalのようだが……それ以上の何かだ。まるで……Old Godsを思わせる。我々はAzeroth各地でその痕跡を見つけてきたが、今やこの生き物たちが何らかの形で奴らと関わりがあるのではないかと思えてくる。\n\nさらに調べねばならんな。", 0xa4fddbb0, 0x533a2b32, 0x6aa87710, 0x63b9f804, 0xa18a1676, "....." },
  [4295] = { "Rocknotのビール", nil, nil, "ああ、エール! Dark Ironのエールのためなら人殺しだってするぞ!! 早く、酔いが醒めてきた! わかるんだ、素面になると目がかすむからな……おかげでお前が、先週俺が斬り殺した{race}に見えてきやがった!", "なんだこれ? あー! Dark Ironビールみてぇな匂いだな! 酒で目が霞んでるけどこれだけは言えるよ、旦那。あんたは真の友だ!", 0x086856d2, nil, nil, 0xa2c71db2, 0x0d80f610, ".mm..", nil, nil, nil, nil, 0xb3506339 },
  [4296] = { "七人の石板", "Tablet TranscriptをBurning SteppesのMaxwort Uberglintのところへ持って行って下さい。", "俺はSevenの伝説を追ってBurning Steppesへやって来た。Sevenは大いなる知識と力を持ったドワーフたちでな、知識と力があるなら、富は必ずついてくるってもんだ。\n\n俺が欲しいのはそれさ。富だ！\n\nSevenについてもっと知ることができれば、一緒に金持ちになれるかもしれないぜ。Thaurissanの遺跡には、古のドワーフの知識を記したTablet of the Sevenがあるって噂だ。その石板を見つけて、文を写して俺のところへ持ってきてくれ。一緒にその秘密を暴こうじゃないか！", "Sevenの書き記したものは手に入れたか、{name}? 彼らの石板から秘密を学んだか?", "おお、石板を見つけたんだね！しかも写しも見事だ！本当に{class}なのかい？書記じゃなくて？\n\nさあ、{name}。約束の報酬だよ。", 0x863c0b42, 0xc0b00f60, 0x910aab7a, 0x793ccb86, 0xfcd7e593, "....." },
  [4297] = { "赤ちゃんの食べ物", "Silvermane Stalker Flanksを$N1個、HinterlandsのAgnar Beastamerのところへ持って行って下さい。", "sprite dartersは雑食なんだ――つまり、肉も植物も両方食べるってことさ。あんたの卵がここで孵るなら、準備しといたほうがいい。信じられないかもしれないが、このちびどもにとってのごちそうは、生で汁気たっぷりの脇腹肉なんだ。なぜなのかはとうとう分からなかったが、Eluneがエルフたちのために立てた計画と何か関係があるらしい……守護者になるはずだったとか何とか、よく分からんがね。\n\n卵はとりあえず俺が面倒を見ておくから、孵ったときに食べさせる上等なSilvermane stalker flanksを取ってきてくれないか。", "肉はもう見つかったか、{name}? お前さんのちっこい卵は、もうすぐ孵るところだ。最初の食事が十分でなけりゃ、最初の一週間を越せないかもしれねえ。そうなったら俺は嫌だぜ。\n\n正直に言うとな、{name}。そもそもお前さんがこの卵を手に入れたこと自体がうらやましいんだ。こうして手を貸したことを、俺に後悔させねえでくれよ。", "これで十分だ。それに、俺の見立てが間違ってなきゃ、お前さんの卵はもうすぐ孵るぞ。どんな気分だ？もうすぐ親になるってのは？ハハ、こんな責任を背負うことになるとは思ってなかっただろ？", 0xccaca750, 0xf90afd2a, 0xc37f8279, 0x2f58b6a1, 0xcba4d08b, ".....", nil, nil, nil, nil, 0x797e01c8 },
  [4298] = { "親になる", "HinterlandsのAgnar Beastamerと話して下さい。", "おっと、思ったよりずっと早く準備ができてたみたいだ……", nil, "ほら、卵を持っていけ……お前さんが持ってた方が、お前さんになついて、親だと思うようになる。\n\nおめでとう、{name}。これで親になったってわけだ……まあ、一応な。", 0xd65f6783, 0xc7b43955, 0x0bc0ac2d, nil, 0xcca17ed2, "...m.", nil, nil, nil, nil, 0x08e439a2 },
  [4300] = { "骨刃の武器", "OrgrimmarのJes'rimonにWhite Ravasaur Clawを8個渡して下さい。", "ふーん、Handを手伝える仕事あるよ。おいらが考えてる仕事。うん、Jes'rimon確かにあんたの助けを生かせるよ。\n\nUn'Goro Craterに恐ろしい爪のraptorがいるんだ。その中に、死のように黒い爪じゃなくて白いのを持ってるraptorがいるんだよ。Handは持ってるんだ……客を……白い爪から作った武器が好きなね。白い爪をたくさん持ってきてくれ。そしたら、おいらあんたに金貨払うよ。早く持ってきてくれたら、別のやり方であんた助けられるよ。", "俺の客はそんなに気が長くねえんだ、{name}。clawsはもう手に入れたか?", "ああ、うまくやってくれた。ありがとう、{name}。と、彼らが必要とする前に来てくれた……いいことだ。\n\n多分この爪であんたに武器が作れる。どうだい?", 0x57afe43e, 0x119beaa0, 0x33cb001a, 0x38e4d27f, 0x6de4c6b4, "....." },
  [4301] = { "強大なるU'cha", "U'cha's PeltをUn'Goro Craterの入口にいるTorwa Pathfinderのところへ持って行って下さい。", "そなたがUn'Goroを探索している間に、私はそなたのような力強いハンターなら喜びそうなものを他にも見かけた。その一つが、北にいる他のゴリラたちの中の巨大な猿だ。その洞窟にはそなたも以前行ったことがあるが、今回、私の頼みを引き受けたなら、その遭遇を生き延びられるだろうか。\n\n私はそれをU'chaと呼んでいる。Earth Motherの最も偉大な息子の一頭であることは間違いない。U'chaを倒し、その毛皮を持ってくるのだ。それを成し遂げれば、そなたが偉大なハンターを名乗る権利を私が守ろう。", "U'cha……あの獣は見事なものだった。巨大で赤く、牙は短剣ほどの大きさ。腕は木の幹ほども太く、これまで目にしたどの山のライオンにも劣らず素早い。そのような勇気の試練に巡り会えたことを幸運に思うがよい。我が一族では、そのような獣を目にすることなく何世代も過ぎることもあったのだ。", "よくやった、{name}。嬉しく思う。お前は今日ここで偉大なことを成し遂げた。\n\nU'chaは私が見た中でも最も偉大な猿の1頭だった。お前がその力を打ち負かしたという事実は、お前自身の強さ……そして勇気をよく物語っている。\n\n敬意の証としてこれを渡すのがふさわしい。お前にはその資格がある。", 0xd10aceeb, 0x9d4e6ce7, 0x99670aa0, 0x644bd43d, 0xba2c7c24, "....." },
  [4321] = { "謎を解く", "少ししたらJ.D. Collieと話して下さい。", "パイロンについて君がくれた情報は、とても興味深いよ……\n\n少し計算する時間をちょうだい、{name}。少ししたらもう一度話しかけて。そうすれば、僕たちが探していた答えを教えられるはずだよ。", nil, "よし、{name}。これは実に興味深い……私の図解が正しいことを祈るばかりだ！すべてをこのマニュアルにまとめたから、君にあげよう。\n\nこれで水晶についての質問には何でも答えられると思うよ、{name}。", 0x676aa57e, 0x91c74f07, 0x1f2e2222, nil, 0x8af10634, "...m." },
  [4322] = { "脱獄！", "Marshal Windsorが装備を取り戻し、仲間を解放するのを手伝って下さい。成功したらMarshal Maxwellのところへ戻って下さい。", "ここから逃げ出さなきゃならん、{name}。補給所から私の装備を取り戻して、仲間を解放するのを手伝ってくれ。ここから出られたら、Morgan's Vigilへ行ってMarshal Maxwellと話すんだ。彼がさらに指示をくれるだろう。", "疲れきった顔をしていますね、{name}。火のそばに腰を下ろして、ひと休みしてはいかがですか。", "驚いたよ、{name}。まったく驚きだ。Windsorはほんの5分前、嵐のようにここを通り過ぎていった。大それた主張をしているが、証拠で裏付けられていると言っている。今はBolvarと……Lady Prestorに詰め寄るためにStormwindへ向かっている。", 0xa1d51782, 0xb27d7145, 0xea606ce3, 0x1cb565cf, 0x3080767e, "....." },
  [4324] = { "Yuka Screwspigot", "Burning SteppesのYuka Screwspigotと話して下さい。", "弟のRibblyは生まれてこのかた役立たずだったけど、ついに、あいつにも価値ができたと思うんだ! でも……Ribblyの新しい値打ちを活かすには、君の助けが要るかもしれない。\n\n妹のYukaが何週間もあいつを探していて、Burning Steppesまで足取りを追ったんだ。人手を貸してほしいって知らせをよこしてきた。\n\nで、どうだい? 手伝ってくれる? もしそうなら、妹と話してくれ。Dreadmaul Rockの北西にある洞窟、Flame Crestに隠れてるよ。", nil, "そうだ、私は弟を探している。彼を見つけて連れ戻さねばならない、気の毒にな。\n\nだが、全部を連れてこられないなら……頭だけでも十分だ。", 0xefbe9d01, 0x2a4bb9fd, 0x67943a49, nil, 0x307322ac, "...m." },
  [4341] = { "Kharan Mighthammer", "Blackrock Depthsへ行き、Kharan Mighthammerを見つける。\n\n王は、Kharanがそこに捕らわれていると言っていた。牢獄を探してみるといいかもしれない。", "Thaurissanのくすぶる廃墟へ行ったことがあるのか? Kharan Mighthammerという情けない愚か者に会わなかったか? わしの愛娘を見守っているはずだったドワーフだ!\n\n<王はすすり泣く。>\n\nそして今、娘はいなくなってしまった、{name}!\n\n部下たちにSteppesをくまなく探させた。娘の行方について奴らがつかんだ唯一の手がかりは、Depthsの中にいるかもしれんということだけだ。わしに分かる限りでは、死んでいるかもしれんのだ!\n\nKharanはそこで囚われているらしい……奴を見つけ出せ! わしは答えが欲しい!", nil, "頼む、説明させてくれ。", 0xfe80aadb, 0xe86ea627, 0x6a2356bf, nil, 0x0d7b100b, "...m." },
  [4342] = { "Kharanの話", "Kharan Mighthammerの話を聞いて下さい。", "頼む、批判する前に最後まで聞いてくれ!", "私の話を最後まで聞いてくれ。", "ご覧の通り、私にできたことは何もないんだ。", 0x0a682832, 0x0f6bf74a, 0x58166ce6, 0x58f6bd04, 0x0cb1cd70, "....." },
  [4361] = { "凶報の使者", "Ironforgeへ戻り、King Magni Bronzebeardに悪い知らせを届けて下さい。", "King Magniにこの情報を知らせてほしい、{name}。王は何をすべきかお分かりになられるはずだ!", nil, "<King Magniは怒り拳を激しく叩きつけた。>", 0x122e45b2, 0xfdee527e, 0x8f5b34e1, nil, 0xc4bc22b7, "...m." },
  [4362] = { "王国の運命", "Blackrock Depthsへ戻り、Emperor Dagran Thaurissanの魔の手からPrincess Moira Bronzebeardを救って下さい。", "どうやらわしの宿敵、Dagran Thaurissanは、わしとIronforgeの王国を思いのままにしておるようだ。\n\nそなたがわしの最後の希望かもしれん、{name}。わしの愛しい娘、Moiraを救い出してくれ!\n\nThaurissanがMoiraにかけた呪文を確実に解く方法はただ一つ。奴を殺すことだ。\n\nそれから{name}、娘を傷つけてはならんぞ! 忘れるな、娘はThaurissanに操られておるのだ! 娘が何をしようと、何を言おうと、それはThaurissanの邪悪な呪文のせいなのだ!", nil, "<Princess BronzebeardがEmperor Dagran Thaurissanを失った悲しみに泣き崩れる。>\n\nなぜ???", 0x38ebdf89, 0x02d49ae4, 0xfd892b70, nil, 0x6bf03c5b, "...m." },
  [4363] = { "予想外の展開", "Ironforgeへ戻り、King Magni Bronzebeardと話して下さい。", "Thaurissanは偉大で高潔なドワーフであった。そなたは我が人生を、そしてまだ生まれぬ我が子の人生を台無しにしたのだ!\n\n<Princess Bronzebeardはまだ皇帝の呪文の影響が残っているのかもしれない、とあなたは思う。>\n\nIronforgeへ戻り、我が父に伝えよ。Kingdom of Ironforgeの世継ぎは、Dark Ironのドワーフになるとな。\n\n父が認めようと認めまいと、そうなるのだ。", nil, "<King Magni Bronzebeardは目に見えて動揺している。>\n\n死してなお、Thaurissanの勝ちということか。\n\n下がってよいぞ、{name}。去る前に、王家の宝物庫から報酬を選ぶがよい。\n\n<King Bronzebeardは玉座に身を沈め、この奇怪な事態の急変に思いを巡らせる。>", 0xb23f23f9, 0x48ee78a7, 0x22918331, nil, 0x7dd3a9ac, "...m." },
  [4402] = { "GalgarのCactus Apple Surprise", "GalgarにCactus Appleを10個渡してください。彼が「サボテンの近くでそれを見つけられる」と言ったことを忘れないように！", "Valley of Trialsはなんとも暑いな……\n\n<Galgarは額の汗を拭いた。>\n\nCactus Appleをいくつか持っていたなら、わしの素晴らしいCactus Apple Surpriseを作れるんだがな！こいつはとても美味しくて、これほど早く体を冷やしてくれるものはないぞ。\n\nではこうしよう、{name}。もしおぬしがCactus Appleを10個とってきたならば、冒険の友となるCactus Apple Surpriseをいくつか作ってやろう。それに訓練の手引書もただでやろう。もし興味があるなら、このあたりのサボテンの近くでCactus Appleが生えているのを見つけられるだろうよ。", "cactus applesは集め終わったかい?", "すばらしい！{name}! 約束したとおり、Cactus Apple Surpriseとおまけをおぬしに渡そう！", 0xaed68386, 0x6d1de7e5, 0x567922ac, 0x15808a02, 0x2545583f, "....." },
  [4421] = { "Jadefireの堕落", "Jadefire Felswornsを$N1体、Jadefire Shadowstalkersを$N2体、Jadefire Roguesを$N3体、そしてXavathrasを倒す。任務を終えたらFelwoodのEridan Bluewindのところへ戻って下さい。", "ここで冒険を求める者は多くありません……Felwoodの堕落は広く、見境なく広がっています。\n\nEmerald Circleの一員として、私はこの地を癒そうとしていますが、この地が腐り続けることを望む者たちもいるのです。\n\n私が言っているのは、ここから北西のRuins of Constellasに棲むJadefire satyrsのことです。Xavathrasという特に残忍なsatyrに率いられ、出会うあらゆる生き物に病を広め続けています。\n\nかつて我々のものだったこの地を守らねばなりません。Xavathrasを倒し、その手下を滅ぼしてください。", "ここの穢れが、獣たちを狂気へと駆り立てているのです……", "FelwoodからXavathrasを排除するのは、長い道のりの第一歩にすぎない。ここで受けた損傷を修復するには多くの努力が必要だ。\n\nここではsatyrどもだけではない、もっと大きな何かが働いているのを感じる。だが真実が分かるのは、時が経ってからだろう……", 0x4b5dd118, 0x46b32024, 0x71742f9e, 0x3f3ed819, 0x74334cac, "....." },
  [4441] = { "Felbound Ancients", "Darnassusへ行き、Eridan's Vialを使ってTemple of the MoonでVial of Blessed Waterを汲んで下さい。満たした小瓶を持ってEridanのところへ戻って下さい。", "あなたが見つけた笛は、古の守護者、ナイトエルフを忠実に守ってきた味方であるtreantから彫り出されたものです。\n\nsatyrsは触れるものすべてを堕落させることができ、その中にはFelwoodを住処としていたancientsも含まれます。felの力によって、そのancientの魂は縛られ、苦しめられ、決して完全には解き放たれていません。あなたが見つけたfelbindも、きっと関係があるのでしょう。\n\nこの笛を清めてみなければなりません、{name}。DarnassusのTemple of the Moonからblessed waterを持ってきてください。", "このwaterが古の者の魂を解き放ち、安らぎを与えてくれるといいのですが。", "ありがとう、{name}。あとは、ここで受けた損傷を元に戻せるよう祈るしかない……", 0x0bf2df61, 0x19deb1d0, 0x245cd7a7, 0x4938e970, 0x591e149b, "....." },
  [4442] = { "浄化完了！", "少ししたら、もう一度Eridanと話して下さい。", "Eluneの水を使って、笛を清めてみます。この苦しみを終わらせねばなりません……\n\nEluneが私の手と心を導いてくださいますように。\n\n少ししたら、もう一度話しかけてください。", nil, "blessed waterのおかげで、フルートと古の霊とのつながりを断ち切ることができた。だが、このフルートを聖なる場所で使えば、古の霊を呼び出せるかもしれない。\n\nIrontree Woodsの南部にある遺跡を試してみるといいだろう。かつてはこの辺りに多くの堕落したtreantが棲んでいた。霊の姿となって今もそこにいる可能性はある。", 0xfb3352f9, 0x6d69af82, 0x50ae36f3, nil, 0xfb97c620, "...m." },
  [4449] = { "捕まえた！", "Dark Iron Geologistsを$N1体倒し、Silk Clothを$N2枚、Searing Gorgeの便所に閉じ込められている人物のところへ持って行って下さい。", "おい！おい、あんた！こっちに来てくれ！\n\n助けてくれよ。Dark Ironのドワーフどもから逃げてて、見つからねえようにここに隠れたんだ。忌々しい地質学者どもと奴らの魔法め！隠れるところを見られてたに違いねえ。気がついたら扉に鍵をかけられて、ここに閉じ込められちまったんだ。\n\nあの地質学者どもに思い知らせてやってくれ！あ……それと、silk clothを何枚か持ってきてくれねえか……その……何でもねえよ。", "一日中待ってる暇はねえんだ! そのsilk clothを持ってこい! いや、地質学者だ。地質学者どもをやっつけてこい! あいつらには俺の、いや……お前の怒りを味わわせてやるべきなんだ。", "おお、こいつは最高だ！手触りもいい！\n\nえ？ああ、そうそう……地質学者どもか。ちゃんと懲らしめてくれたか？いくら感謝してもしきれないよ、{name}。これでここの作業を仕上げる時間ができる……改めてありがとう、{name}。", 0xab9278e3, 0x8651a055, 0xc422c491, 0x13a88031, 0x98779dfb, "....." },
  [4450] = { "Tanarisからの帳簿", "Goodsteel's Ledgerの写しを受け取り、そこに記された品を見つけてから、TanarisのKrinkle Goodsteelを訪ねて下さい。", "あ、そうだ、それで思い出した。\n\n俺がTanarisにいたときに引き受けたちょっとした仕事を片付けてくれねえか？簡単だぜ……\n\nGadgetzanのKrinkle Goodsteelが、ここSearing Gorgeやほかのいくつかの場所で手に入る品を探してたんだ。リストを見て、全部あいつのところへ持っていってくれねえか？\n\nその気があるなら、扉の下からあいつの帳簿を滑らせるよ。品を全部集めたら、その帳簿とあいつが欲しがってる品を、あいつのところへ持ってってくれ。", "はいはい? 何のご用かな、{race}? こっちはひどく忙しくて、仕事を頼みに来る客が大勢いるんだ。手早く済ませてもらえると助かるよ。失礼なことを言うつもりはないけど、溜まった仕事を片付けるには、とにかく時間がないんだ。", "おや、私が頼んだ仕事をいくらかやってくれたのか。素晴らしい。てっきり何か作ってくれと頼みに来たのかと思っていたよ。\n\nどれも完璧だ……それに全部揃っている。ありがとう、{class}。\n\n少しくらい報酬をあげても罰は当たらないか……さて、君には何が役に立つだろうか。", 0xfa56f393, 0xfbaa0d2b, 0xccb4891c, 0x920e8057, 0x3d8ac6bb, "....." },
  [4451] = { "自由への鍵", "Searing Gorgeを探し回り、見つけたGrimesilt Outhouse Keyの使い道を見つけて下さい。", "小さな真鍮の鍵は、ごく単純なものに見える。唯一目立つところといえば、頭の部分に刻みつけられたいくつかの言葉だ。\n\n「Dark Iron Outhouse - Do Not Duplicate.」\n\nそれが何を意味するのか、どこへつながるのか、まったく見当もつかない。", "*ゴホッ*\n\n誰だ? 忙しいのが見てわからねえのか?", "こりゃたまげた！一体どうやって！？keyを見つけてくれたのか！あのDark Ironどもが俺をここに閉じ込めた後、隠してたに違いねえと思ってたんだ！本当にありがとよ、{name}。あんたは最高だ！さあ、keyを回して、Locheedじいさんをここから出してくれ！", 0x1d423cb0, 0xdf1d614f, 0xe0aab529, 0xd1c3c55d, 0x30438394, "....." },
  [4485] = { "Tome of Nobility", "StormwindのDuthorian Rallと話して下さい。", "こんにちは、{name}。あなたの献身は揺らぐことなく、信仰もまた揺らいでいないようですね。\n\nそろそろStormwindのDuthorian Rallと話す時だと思います。あなたが学ぶべき教えがまだあり、あなたにはその準備ができていると感じます。\n\nCathedral of Lightで彼を訪ねてください。そして{name}、その教えを真剣に受け止めてください。あなたは謙虚さと努力によって今の地位を得たのです。傲慢になって我々を失望させないでください。\n\nお元気で。", nil, "ああ、Cathedralに戻ってきたのですね、{name}。よろしい。最近いろいろなことがありました。あなたがふさわしいと証明できれば、力を借りたいのです。\n\n危険な敵が多く潜んでいます。彼らを止めるにはあなたの助けが必要です。", 0x2923ea98, 0x0f3ca705, 0x454c6c6f, nil, 0x47e1bbd2, "...m." },
  [4486] = { "Tome of Nobility", "StormwindのDuthorian Rallと話して下さい。", "おやおや、威風堂々たる強大なパラディン様のお出ましだ。\n\n悪い、{name}、気を悪くさせるつもりはなかったんだ……君が成し遂げた偉業を見ると、ときどきちょっと妬ましくなってね。Tizaにはそれが僕の弱さだって言われて、直すって彼女に誓ったんだ。でも、ときどき難しいんだよ、分かるだろ？\n\nでも、君と話したかったのは、StormwindのDuthorian Rallから、準備ができたらCathedral of Lightで会いたいと君に伝言が届いたからなんだ。大事な話みたいだったよ。何かが起きているみたいだった。", nil, "ああ、Cathedralに戻ってきたのですね、{name}。よろしい。最近いろいろなことがありました。あなたがふさわしいと証明できれば、力を借りたいのです。\n\n危険な敵が多く潜んでいます。彼らを止めるにはあなたの助けが必要です。", 0x2923ea98, 0x0f3ca705, 0x3240aaf3, nil, 0x47e1bbd2, "...m.", nil, nil, 0x381e65db, nil, nil },
  [4487] = { "Summon Felsteed", "RatchetのStrahad Farsanと話して下さい。", "ああ、よし、来たな。お前の注意を引くために悪魔を一体差し向けたのだが、それが見つける前にここへ来られたようだな。まあいい。\n\n最近、お前の力が増しているという話が出ている――お前にとっては良いことで、他の者にとってはおそらく悪いことだ。だが、そんなことはどうでもいい。肝心なのは、お前が自らの価値を証明したと私は感じていて、それゆえお前は……ふふ……ある種の祝福を受けるに値するということだ。\n\nBarrensのRatchetの上に、Strahadという男がいる。お前とは以前にも会ったことがあるはずだ。", nil, "ほう、また私の前に顔を出す気になったか。ご親切なことだ。\n\n弟子たちは、お前が本当に姿を見せるのかと訝っていた。私は疑う余地はないと言ってやった。力が絡むとなれば、お前は炎に引き寄せられる蛾のようにやって来るのだからな。", 0x5220fbc8, 0x0c866240, 0xf53d45e1, nil, 0x23773eba, "...m.", nil, nil, 0xe53a38b3, nil, nil },
  [4488] = { "Summon Felsteed", "RatchetのStrahad Farsanと話して下さい。", "ああ、{name}、わざわざお出ましくださるとは。なんと素晴らしい！\n\n我々にまで至れり尽くせりの世話を期待してはいないだろうな。力は急速に増しているかもしれんが、真の知識と理解においては、お前はまだ子犬にすぎん。気をつけなければ、堕落がお前とお前の弱い意志を飲み込むだろう。\n\nだが本題に入ろう。Strahadがお前と話したがっている。彼は今もBarrensのRatchetを見下ろす塔に住んでいる。あまり時間をかけないことを勧める。", nil, "ほう、また私の前に顔を出す気になったか。ご親切なことだ。\n\n弟子たちは、お前が本当に姿を見せるのかと訝っていた。私は疑う余地はないと言ってやった。力が絡むとなれば、お前は炎に引き寄せられる蛾のようにやって来るのだからな。", 0x5220fbc8, 0x0c866240, 0x22753d85, nil, 0x23773eba, "...m." },
  [4489] = { "Summon Felsteed", "RatchetのStrahad Farsanと話して下さい。", "そこの{race}！こっちへ来い！\n\nお前が{name}と呼ばれている者だな？\n\nやはりそうか。手短に話そう。お前の力は増しており、それは認められている。そして今、お前がその努力に報われる時が来たのだ。\n\nBarrensへ行け。そこのRatchetの上で、Strahad Farsanが見つかるだろう――覚えているか？彼がお前と話したがっている。ぐずぐずしないことだ。", nil, "ほう、また私の前に顔を出す気になったか。ご親切なことだ。\n\n弟子たちは、お前が本当に姿を見せるのかと訝っていた。私は疑う余地はないと言ってやった。力が絡むとなれば、お前は炎に引き寄せられる蛾のようにやって来るのだからな。", 0x5220fbc8, 0x0c866240, 0x9e1f9f00, nil, 0x23773eba, "...m." },
  [4490] = { "Summon Felsteed", "RatchetのStrahad Farsanと話し、Felsteedを呼び出す能力を習得して下さい。", "その忍耐と勤勉には報酬を与えよう。だが覚えておけ、Felsteedを召喚する能力は、今後ははるかに得難いものとなる。自ら勝ち取らねばならぬ……そして、それは容易ではない。\n\n今は、その生き物を召喚する力を持って行き、思うままに使うがいい。", nil, "幸運を祈ります、{name}。またお会いできるのを楽しみにしています。", 0x5220fbc8, 0x7950b530, 0x285bb1cf, nil, 0x2dc44b87, "...m." },
  [4491] = { "友からのちょっとした助け", "RingoをMarshal's RefugeにいるSpraggle Frockのところまで連れて行ってください。\n\n途中Ringoが気を失ったら、Spraggle's Canteenを使って意識を取り戻させてください。", "うぐぐ・・しかし暑いね・・・。\n\nここら一帯を探検してたら、突然暑さに耐え切れなくなったんだ。熱射病にかかったに違いないよ。\n\nMarshal's Refugeにいるおいらの友達、Spraggleのところへ戻りたいんで、手を貸してくれないかな。あんたについて行けるくらいには元気だと思うよ。\n\nまだちょっとフラフラするね。もしおいらが気を失ったら、Spraggle's Canteenの水をおいらにかけてくんないかな。うまくいくといいんだけどな・・。", "Ringoのことがずっと心配で……", "Ringoの状態はあまりよくないみたいだわ、{name}。でも無事帰ってきたのが何より！\n\nあいつを見つけてくれてありがとね。", 0x299595aa, 0x19fb72e7, 0xaf0b31ee, 0x99c6cdef, 0x642cc87e, "....." },
  [4492] = { "どこにいるの！", "Fire Plume Ridgeに行ったRingoを見つけ出してください。", "ちょっと手を貸してくんないかな、{name}！私の友達、Ringoがここの南にある火山に探検にいってだいぶたつんだけど、まだ帰ってこないんだよね。とっても心配。\n\n捜してきてくんないかな？私の水筒を持ってったほうがいいんじゃないかな。Ringoを見つけたとき、絶対必要だと思うんだよね！", "な……何?", "ああ・・誰かきてくれたのかい。うれしいねえ・・。", 0x45101ee2, 0x080f5567, 0xc9277091, 0x3b72f2ea, 0xe7945f5f, "....." },
  [4493] = { "Silithidの進軍", "GadgetzanのAlchemist Pestlezuggに話しかけて下さい", "silithidの目的、いいえ……存在理由とは、行く手にある仲間以外の物は何でも貪り食ってしまうことのようね。虫たちの興味関心は並外れているゆえ、Azerothの生きとし生けるものすべての深刻な脅威なのです。\n\n私たちが今まで見てきたものは最初の段階に過ぎません。虫たちの力の源はKalimdorの奥深く……Un'Goro Craterにあると推測しています。Tanaris砂漠のGadgetzanへ行き、Alchemist Pestlezuggに話しかけて下さい。彼に私の説を伝えてほしいのです。間違いなく、silithidとの戦いを助けてくれるでしょう。", nil, "ええ、Gracinaが君を寄越したんだと推測したよ。この獣と戦ってきた君の経験はとても貴重なものだ。私が知る中で、以前奴らを扱ったことがある者はいない。Gracinaの考えによれば、Un'Goro Craterは奴らの中心地……恐らくそうだろう。Un'Goroはここから西へ行ったところにある神秘的で危険なジャングルだ。恐らくこれも、silithidに関するすべてを理解するのに近づく一歩だろうね。", 0x38486200, 0x2fa7b4e6, 0xff4ae737, nil, 0x2146fcf0, "...m." },
  [4494] = { "Silithidの進軍", "GadgetzanのAlchemist Pestlezuggに話しかけて下さい", "silithidの目的、いや……存在理由は、行く手にある仲間以外の物は何でも貪り食うことのようだ。奴らの興味関心は並外れているゆえ、Azerothの生きとし生けるものすべての深刻な脅威なんだ。\n\n我々が今まで見てきたのは最初の段階に過ぎない。奴らの力の源はKalimdorの奥深く……Un'Goro Craterにあると推測している。Tanaris砂漠のGadgetzanへ行き、Alchemist Pestlezuggに話しかけてくれ。彼に私の説を伝えてほしい。間違いなく、silithidとの戦いを助けてくれるだろう。", nil, "ええ、Zilzibinが君を寄越したんだと推測したよ。この獣と戦ってきた君の経験はとても貴重なものだ。私が知る中で、以前奴らを扱ったことがある者はいない。Zilの考えによれば、Un'Goro Craterは奴らの中心地……恐らくそうだろう。Un'Goroはここから西へ行ったところにある神秘的で危険なジャングルだ。恐らくこれも、silithidに関するすべてを理解するのに近づく一歩だろうね。", 0x38486200, 0x2fa7b4e6, 0xff4ae737, nil, 0x482c0f64, "...m." },
  [4495] = { "良き友", "北の洞窟の傍で、Iverronを探せ。", "いつも同じ時間に私を訪ねて来るIverronという名の友達がいるんだけど、妙なことに今日はどこにも姿が見えないの。実際いつも彼が来る時間より数時間も過ぎてるわ。\n\nそう、実はちょっと心配なのよ{name}。Iverronは多くの時間を北の洞窟で過ごすんだけど、あなたもそこがどれほど危険か判ってくれると思うわ。洞窟にはそこかしこにクモがいるんだから！\n\nねえ、もし洞窟の方にいくようなことがあるなら、彼をさがしてくれないかしら？", nil, "みつけてくれて本当に有難う、{name}。どうしてここにいるってわかったんだい？", 0xc68e1991, 0xa973ef17, 0xfa034016, nil, 0x8083d57b, "...m." },
  [4496] = { "熱帯での失態", "Gorishi Scent Gland 1つとUn'Goro Soil 5つをGadgetzanのAlchemist Pestlezuggに渡して下さい。", "調べてみて分かったんだけど、silithidは蜂みたいなもんでね。巣の女王を倒せば、残りは混乱に陥るはずなんだ。女王をおびき出すためのおとりを調合するから、呼び出したら君が倒すんだ。\n\nでもまずは、いくつか材料が要る。準備なしでジャングルへ突っ込んでへまをされちゃ困るからね。西へ行ってUn'Goro Craterのsilithidの巣を見つけ、虫のどれかからscent glandを手に入れてきてくれ。それから、地元のUn'Goro soilのサンプルもいくつか要るんだ。", "ちょうどいいscent glandを見つけるには少し手間がかかるかもしれないね。glandは傷つけちゃいけないけど、手に入れる過程はどうしたって傷つけやすいものだから。soilのほうは、簡単に見つかると思うよ。\n\nそれで、ルアーを作るのに必要な品は持ってきてくれたかい?", "scent gland、ああそうだ。膜も無傷のようだ――素晴らしい。soilも、よし、これなら申し分なく使えるだろう。私の特別な添加物を加えれば、これを全部すり潰して完璧な誘引剤にできるはずだ。\n\n誘引剤を作るから少し待ってくれ、{name}。出来上がれば、silithidがGadgetzanを……そしてKalimdorの残りを飲み込む前に食い止められるかもしれない次の手を打てる。", 0x2350d0d6, 0x8547f48e, 0x28e51686, 0x27edc253, 0xaac7c66b, "....." },
  [4501] = { "Pterrordaxに注意", "Pterrordaxを$N1体とFrenzied Pterrordaxを$N2体倒し、Marshal's RefugeのSpraggle Frockと話して下さい。", "求む：Un'Goro Craterに棲むPterrordaxの脅威に対処できる腕の立つ戦士。奴らの数は増え続け、この地域を旅する者たちにとって脅威となりつつある。\n\npterrordaxを10体、frenzied pterrordaxを15体倒し、その数を減らしてほしい。\n\n任務を終えたら、報酬についてSpraggle Frockと話すこと。", "正直に言うと、あの奇妙な生き物たちのことはそれほど心配してなかったの……大きな石の側面にあの言葉が書かれているのを見た日まではね。\n\nPTERRORDAXに注意\n\n誰が書いたのかしら? わからないけど、気味が悪すぎて放っておけないわ!", "ここのpterrordaxが本当に怖くてたまらないんだ！数を減らしてくれてありがとう、{name}。これでMarshal's Refugeの外に出ても安心できるかもしれない。", 0x53856929, 0x0ed8f937, 0x4432659d, 0x84afa51a, 0x3ed95181, "....." },
  [4502] = { "火山活動", "Un'Goro Craterの火山の周りにいる炎のエレメンタルから、Un'Goro Ashのサンプルを$N1個集め、RatchetのLiv Rizzlefixのところへ持ち帰って下さい。", "Marvon Rivetseekerの弟子をしていて、本当にたくさんのことを学んだの。でも、先生はもうずいぶん長いこといないから、自分なりの実験をやってみようと思うんだ。\n\n最近はUn'Goro Craterについて読んでいて、クレーターの真ん中で起きている奇妙な火山活動のことを知ったの。あそこのエレメンタルから灰を少し手に入れられれば、きっといろんなことが分かると思うんだ。\n\nもしそっちへ行くなら、少し集めてきてもらえないかな？", "Un'Goroの火山が活動中って本当かい? 火山のashがあれば、きっといろんなことがわかるはずなんだ、{name}。", "このサンプルは私の研究にぴったりだ！ありがとう、{name}！約束するよ、発見があったら真っ先に君に知らせるからね。", 0xb735cc5c, 0x9a0db4e4, 0xdc9ab232, 0x9ccfa2b9, 0x7d596c83, "....." },
  [4503] = { "Shizzleのフライヤー", "Marshal's RefugeのShizzleのために、Webbed Diemetradon Scalesを$N1枚とWebbed Pterrordax Scalesを$N2枚集めて下さい。", "空飛ぶ機械を作ってるんだ！\n\nここで立ち往生しちゃってさ、しかも道を覚えるのがとんでもなく苦手なんだよ。gryphonかwind riderに乗ってGadgetzanへ帰るって手もあるけど、あの獣たちは怖くて死にそうになるんだ。\n\nで、手伝ってくれるかい？あとは翼を作るだけなんだけど、pterrordaxとdiemetradonのネバネバした鱗がぴったりだと思ってるんだ。あんなのに立ち向かうなんて僕には絶対無理だけど、君はずいぶんタフそうだ。ちょっとやってみてくれないかな？", "偉大な乗り物には名前が必要だ……こいつの名前はそうだな……Pwned!にしようと思ってるんだ!", "うん、このscalesは完璧だ。このscalesがあれば、この飛行機をきっと飛ばせるはずだ！\n\nありがとう！", 0x267b2e06, 0xc6ebfcf4, 0xb8dc58ea, 0x99435350, 0x3a81d220, "....." },
  [4504] = { "超ねばねば", "GadgetzanのTran'rekのために、Super Sticky Tarのサンプルを$N1個集めて下さい。", "手っ取り早く金を稼ぐ方法はいつも探してるんだ、{name}。俺の最新のアイデアを手伝ってくれたら、儲けを少し分けてやるよ。どうだい？\n\nだと思ったよ！\n\nUn'Goro Craterの北にあるタール坑へ行って、タールを集めてきてくれ。ただのタールじゃだめだぞ、タール坑のまわりに住んでる獣から取ってこなきゃならない。普通のタールじゃ、粘り気が全然足りないんだ。\n\n植物みたいな生き物は皮に葉緑素を含んでいて、それがタールと混ざると、超ネバネバになるのさ！", "Tran'rekがまたやってのけたぜ――この超強力な接着剤は大流行間違いなしだ!", "うん、このtarこそ求めていたものだ……\n\nおい、ちょっと待て、手が……離れないぞ……\n\nこれはあまりいい考えじゃなかったかもな。いや、待てよ！Super sticky tarの除去剤！これこそ本当に儲かるぞ！", 0xd1b6e98f, 0x65920f7c, 0x8cd19f90, 0x59876396, 0x73171fdd, "....." },
  [4505] = { "腐敗の井戸", "Jadefire Satyrのmoonwellから腐敗した水のサンプルを集めて、Bloodvenom PostのWinna Hazzardに渡して下さい。", "私のことを並外れて残酷だと言う者もいるかもしれん……だが本当は、どんな手を使ってでも、HordeがAllianceに対して優位に立つのを見たいという強い願いにすぎん。\n\n私が今興味を持っているのは、ここから南のRuins of Constellasにある月の泉だ。Jadefire satyrsが管理している。月の泉は、かつてはあの鼻持ちならないナイトエルフにとって再生の象徴だったが、今では穢れ、さらに多くのsatyrsを生み出すのに使われている。\n\n考えがあるのだ、{name}。その水のサンプルが欲しい……ここにいる私の小さな猫の友のためにな。", "これは極めて重要なことだ。さあ、行きなさい。", "とてもいいですよ。この腐敗を敵に用いる方法を見つけねばなりません……。", 0xd948deaa, 0x6a143d3b, 0x5ad7ea0d, 0x38afa674, 0x772286f3, "....." },
  [4506] = { "Corrupted Sabers", "Winnaの子猫を穢れたムーンウェルへ連れて行って放し、Winnaのところへ連れ帰って下さい。\n\nWinnaのところへ戻ったら、猫をクリックしてWinnaのもとへ放して下さい。", "この汚染された水は、我々に有利に使えるかもしれませんよ、{name}。ほんの少しこの水を与えただけで、私の子猫は倍の大きさになり、しかも強くなったようなのです……なぜかね。この猫たちは役に立つかもしれません……\n\nさあ、{name}。この猫用のキャリーを持って行き、Ruins of Constellasの月の井戸のそばで中の子猫を放してください。ふふふ……結果にはきっと満足していただけるはずです！\n\n猫を連れて戻ってきてくれれば、手間に見合うだけのお礼はしますよ。", "あそこに戻れないなんて言わせないぞ! さっさと行け!", "素晴らしい！\n\nforsakenはallianceを叩き潰すためならどんな手段も辞さない！この汚染された水は、きっと今後の我々の取り組みに役立つだろう……", 0x3471adc0, 0xa46e77d2, 0xc2880cd5, 0x262eaecc, 0x136d0228, "....." },
  [4507] = { "兵、女王を捕らえる", "Gorishi Hive Queenが呼び出されたら、それを倒す。\n\nGorishi Queen's BrainをGadgetzanのAlchemist Pestlezuggのところへ持って行って下さい。", "これがおとりだよ。巣の通路網の中に、何かの水晶があるはずだ。silithidはその水晶を、巣全体の同調装置みたいなものとして使ってるらしい。水晶のありかは、巣の中の孵化場を探してみるといいと思う。\n\n水晶におとりを使えば女王をいぶり出せるはずだけど、気をつけて――たぶん何体かの護衛に守られてる。女王を倒したら、脳を取り出してきてくれ。気持ち悪く聞こえるだろうけど、どうしてもそれを調べたいんだ。幸運を、{name}!", "研究のためにクイーンの脳を手に入れることは、何よりも重要だ。これまでにわかったことから、このsilithidどもは邪悪な知性に操られている可能性が高いと我々は考えている。silithidのような狡猾なものを操れる存在など、考えただけで身震いがするよ、{name}。", "見事だ、{name}! 今日はここで大きな勝利を挙げた。手に入れたものを完全に理解するには時間がかかるだろうが、必ず役立ててみせる。そこは心配するな。\n\nsilithidについては、これで奴らの全貌だったとは到底思えない。残念ながら、あまりにきれいに片がつきすぎている。", 0x185f555f, 0xe9357e57, 0xb0de715f, 0xf8dbbd41, 0xc01ee2cb, "....." },
  [4508] = { "嵐の前の静けさ", "Pestlezugg's Un'Goro ReportをDarnassusのGracina Spiritmightのところへ持って行って下さい。", "私の最近の発見と、今日ここで得た知識は、それを本当に活かせる者の手に届けなければならない。我々Gadgetzanの者がいくら機転が利くといっても、これを単独でやり遂げることはできないのだ。\n\n私の最新の報告書をDarnassusのGracina Spiritmightのところへ持って行ってくれ。彼女はまだTemple of the Moonにいるはずだ、そうだろう？彼女にはAllianceのお偉方の友人がいる。この件に彼らを巻き込めれば、{name}、我々も生き延びられるかもしれない。", "あいつらは愚か者だ、{name}! もっと大きな脅威がないか周りを見回すことすら思いつかない。Hordeへの理不尽な憎しみが、我々全員の破滅を招くだろう。silithidの脅威について、これ以上どう証拠を示せばいいのかわからない。自分の目で確かめられるよう、あいつらを巣の一つに放り込むくらいしか手がないじゃないか!\n\nすまない、私に知らせを持ってきてくれたのかな?", "これは本当にありがたいのですが、私たちにとってどれほど役に立つかは分かりません。AllianceはHorde以外からの脅威には目を向けず、ここDarnassusの指導者たちでさえ、この脅威が一体何なのか意見がまとまりません。Fandral Staghelmのような愚か者は、silithidなど私が主張するような太古の脅威とは似ても似つかないと唱えています。彼の無知を上回るのは、その傲慢さだけです。\n\nあなたは自分の目で脅威を見たはずです、{name}。私たちはsilithidを倒すことに身を捧げ続けなければなりません！", 0x2a848062, 0xe0364cff, 0x0d4c87af, 0xd512ebbd, 0xe92de08c, "....." },
  [4509] = { "嵐の前の静けさ", "Pestlezugg's Un'Goro ReportをOrgrimmarのZilzibin Drumloreに渡して下さい。", "私の最新の調査結果と、今日ここで得た知識は、それを実際に活かせるかもしれない者の手に渡らなきゃならない。Gadgetzanの我々がいくら機転が利くといっても、これは我々だけではどうにもならないんだ。\n\n最新の報告書をOrgrimmarのZilzibin Drumloreのところへ届けてくれ。彼はまだDragの上のほうの店にいるんだろう？Hordeの上層部に友人がいるんだ。{name}、彼らをこの件に巻き込めれば、我々も生きてこの状況を切り抜けられるかもしれない。", "あいつらは愚か者だ、{name}! もっと大きな脅威がないか周りを見回すことすら思いつかない。Allianceへの理不尽な憎しみが、我々の破滅を招くだろう。silithidの脅威について、これ以上どう証拠を示せばいいのかわからない。自分の目で確かめられるよう、あいつらを巣の一つに放り込むくらいしか手がないじゃないか!\n\nすまない、私に知らせを持ってきてくれたのかな?", "心から感謝はするが、これが我々にとって何の役に立つのかは分からない。HordeはAlliance以外からの脅威には目もくれない。事実を示されればThrall自身は動くかもしれんが、彼はあらゆる方面から食い違う助言に囲まれている。あの愚か者どもは、それでAllianceの不意を突けると思えば、我々にありもしない自分の尻尾を追いかけさせるだろう！\n\n君は自分の目で脅威を見たはずだ、{name}。我々はsilithidを打ち倒すことに全力を尽くし続けねばならん！", 0x2a848062, 0x1e85f786, 0x601e9659, 0x0198e913, 0x22547659, "....." },
  [4510] = { "嵐の前の静けさ", "Bank VoucherをDarnassusの銀行にいるIdrianaのところへ持って行って下さい。", "{name}、あなたの助けは計り知れないものでした。いずれ間違いなく、silithidに対してもう一度あなたの力を借りる時が来るでしょう。我々はUn'Goroで学んだことを吸収しなければなりません。silithidがUn'Goroから生まれたという私の推測は、今では誤りだったのではないかと恐れています……実際には、どこかにはるかに強大な存在がいるのです。\n\nこのメモを銀行のIdrianaに持って行ってください。私の金庫から、感謝の印となる品を渡してくれるはずです。ご協力ありがとう、勇敢な{class}よ。", "Elune'adore、{class}。本日はどのようなご用でしょうか?", "このbank voucherにより、私はGracina Spiritmight様の口座から品物を引き出し、あなたにお渡しする権限を与えられております。おめでとうございます、と申し上げるべきでしょうね！", 0x2a848062, 0xc67f689d, 0xbe332e09, 0xd9a6df82, 0xd0305231, "....." },
  [4511] = { "嵐の前の静けさ", "Orgrimmarの銀行にいるKarusにBank Voucherを渡して下さい。", "{name}、君無しでこれを成功させることはできなかった。その時はすぐやって来る、間違いなく。もう一度silithidに立ち向かうのに君の助けを求める時がね。我々はUn'Goroで学んだことを理解しなきゃならない。silithidがUn'Goroから発生したという私の仮定は今間違っているんじゃないかと心配しているんだ……実はどこかに、はるかに強大な存在がいるんじゃないかとね。\n\nこの手紙を銀行のKarusに持って行け。私の金庫から感謝の印と見なせる物をくれるだろう。君の支援に感謝してるよ、偉大な{class}。", "Zug zug! 今日は何の用だ、{class}?", "この銀行引換証は、Zilzibin Drumloreの口座から品物を引き出し、あなたに差し上げることを許可するものです。\n\nおめでとうございますというのが相応しいようですね!", 0x2a848062, 0x789ea047, 0x50b303f1, 0x33b26f32, 0xd21bc1a3, "....." },
  [4512] = { "小さなスライム大活躍", "Filled Cursed Ooze Jar 6本・ Filled Tainted Ooze Jar 6本を Ironforge にいる Laris Geardawdle に渡して下さい。", "実は、ほとんどウーズのことばかり研究してきたんだ。おかしく聞こえるだろうが、そこら中にいるんだ!\n\nちょっと前のことだが、Menethil にいるさるご婦人の鞄――ウーズに食われた鞄を見つけて助けて差し上げたのだが、Undercity から来た Royal Apothecary Society のメンバーがウーズのサンプルを集めてるのを目にした。その理由が知りたい! ウーズはどこから来たのだろう?\n\nウーズが Felwood にもっといるそうだ。あそこのウーズのサンプルがあればもっと詳しく研究できる。道具箱を渡そう。これを使って、死んだウーズからサンプルを集めてくれ。", "これまでの実験の中には、実に興味深いものもあるんだ。もう少し研究を進めれば、この生き物たちの正体や、Azerothで生命が発達してきたこととどう関わっているのかがわかると思う……そもそも関わりがあるのならね。\n\nあまり受けのよくない僕の一番大きな仮説は、oozeやslimeがこの惑星の創造と結びついているという考えなんだ……まるでこの星から分泌されたもののようにね。\n\nでも、もっとサンプルが手に入るまでは、証明も反証もできないんだ。", "素晴らしい成果だ、{name}! 汚染されたあれのサンプルを手に入れる距離まで近付き、しかも疲れた様子もない! ありがとう。サンプルは完璧だろう。実験を行うのが待ち切れんよ。\n\nもし私が正しければ、Explorers' Leagues で最も偉大なサイエンティストになれるかもしれん!\n\nGnomeregan の事故後にノームを Ironforge へ受け入れたのは間違いでなかったと、これでドワーフに示せる。", 0xfc215fb1, 0xd9cd31fb, 0x14c48c9e, 0x0f89427d, 0xfa6bff92, "....." },
  [4513] = { "小さなスライム大活躍", "Filled Pure Sample Jar 10本を Ironforge にいる Laris Geardawdle に渡して下さい。\n\n見つけるのが困難であれば、Laris から手掛かりを聞き出してみて下さい。", "さらにサンプルが必要になりそうだ、{name}。しかし――どう言っていいのか分からんが――サンプルは純粋なものでなければならないんだ。分かってる、分かってるとも。「Laris、『純粋な』とはどういう意味?」って、そんなもの分からんよ、私にも。これが汚染されていることは分かってる……ちょうどFelwoodのようにな。だからこそ私の気づきがとても重要なんだ。ウーズは自分たちのいる地域の外観を取り込むべく……順応しているようなのだよ。だから汚染されていないサンプルを見つける必要があるんだ。しかしどこで? どこでだ?!\n\nフン! {name}、万が一にでも君が見つけた場合に備えて、この箱を持ってってくれ。", "考えるべきことが山ほどある。だが、それは何を意味するのだろう? そしてAzerothの人々の暮らしにどう影響するのだろうか?", "見つけたのか? {name} 、君は宝物だよ。君の貢献と援助はあまりにも大きすぎて充分にお礼もできない。\n\nさあ、手間を取らせた代わりにこれを持って行ってくれ。さてと、私にはやるべきことがたくさんある。だが、後で来てくれれば、また頼むことがあるはずだ。\n\nありがとう、本当にありがとう。", 0xfc215fb1, 0xb6a37702, 0xf58e5302, 0x8ddc9857, 0xcbbdacd0, "....." },
  [4521] = { "自然の守り人", "FelwoodのTrull Failbaneは、Raging Owlbeast 15頭・Ragged Owlbeast 15頭を殺すよう求めています。", "WinterspringはTimbermawのすぐ先、Felwoodの北東にある。行ったことはあるか?\n\nその地には、wildkinと呼ばれる生き物がうようよいると聞く。この獣どもは秘密を守っていることで知られている。ナイトエルフの秘密をな。\n\nWinterspringに何が隠されているのか、突き止めねばならん。\n\nragged owlbeastsは道のすぐ南に、raging owlbeastsと呼ばれる別の種類はWinterspringの中央にいると聞いた。奴らを一掃し、その地へ入り込め。", "私が与えた任務を終えたら、報告に戻ってきてくれ。", "そいつは素晴らしい知らせだ、{name}。あの獣どもが片付けば、もっとWinterspringへ行けるようになる。次の準備はできてるか?", 0x4ae5e0ac, 0x27c2851b, 0xd7791e02, 0xdf2686fc, 0xde1fc110, "....." },
  [4542] = { "Freewind Postへの知らせ", "Freewind PostのCliffwatcher LonghornにUrgent Messageを渡して下さい。", "勇敢な旅人よ、この地域ではcentaurの攻勢が強まっている。ひどい仕打ちが再び起きたことについて、すぐさまFreewind Postへ知らせなくてはならん! 南東のFreewind PostにいるCliffwatcher Longhornを捜し、彼にこのUrgent Messageを渡してくれ。\n\n注意しておくが、近くにいるGrimtotem族は避けた方がいい……最近、我々に対する振る舞いがおかしいんだ。", "何の用だ、{class}? urgent message――私宛てだと?", "また悪い知らせか！このcentaurどもはやりすぎだ！奴らは俺の補給隊商の一つを襲い、隊を皆殺しにした。言語道断だ、このままでは済まさんぞ！", 0xc0420527, 0xf4ee9842, 0x3bc2e3b4, 0x48656749, 0x3b14844c, "....." },
  [4581] = { "Kayneth Stillwind", "Shindrell's NoteをForest SongのKayneth Stillwindのところへ持って行って下さい。", "ドルイドのKayneth Stillwindから知らせが届きました。我々の沿岸とAstranaarを取り巻く森で起きている出来事について報告がほしいそうです。彼はAshenvaleに腐敗が広がっているのではないかと恐れています……そして、その通りかもしれません。\n\nさあ、私の報告書を彼に届けてください。彼は東のNightsong WoodsにあるForest Songの祠にいるはずです。", "何か私に渡すものがあるのか?", "ああ、Shindrellの報告書ですね！本当にありがとう、{name}。Shindrellは勇敢で鋭い、立派な歩哨です。Ashenvaleに広がりつつあると私が恐れている邪悪の手がかりを探すため、これを読まなければ。", 0x9dc5369f, 0x412eac24, 0x2655e857, 0x38f32e8a, 0x7f079b03, "....." },
  [4601] = { "Sparklematic 5200!", "Sparklematic 5200 に Grime-Encrusted Item を投入し、機械を作動させるには銀貨3枚を必ず入れて下さい。", "この奇妙な機械は、部屋の外の狂気に対して持ち堪えているノームの中でもひときわ目立っている。装置につけられている小さな飾り板には 'The Sparklematic 5200' とある。さらに説明文が続いている。\n\n「汚れとカスがあなたの光り物を台無しにしている? Sparklematic 5200 が素敵な輝きを取り戻します! あなたが綺麗にしたい品物を入れて、銀貨3枚を硬貨投入口に入れて下さい。Sparklematic 5200 の作動が終わるまでしばらく待って、ほら出来上がり! 大切なものは綺麗にぴかぴかになって出てきます!」", "どうやらこの装置を動かすには、きれいにするための汚れのこびりついた品と、銀貨3枚が必要なようだ。その両方がそろっていれば、Sparklematic 5200は動くはずだ……", "汚れに覆われた物を入れ、Sparklematic 5200 に銀貨を3枚入れた。機械は得体の知れない物から汚れを取り除くべく、ほとんど怒り狂ったかのように揺れた。機械の中心からは大きく騒々しい撹拌の音が発せられている。左右に揺れると、金属のフレームの鼓動はぎいぎいと軋み、唸りを上げた……。", 0x7df37d0f, 0xa77d0758, 0x66b0513f, 0x38e80812, 0x55272153, "....." },
  [4602] = { "Sparklematic 5200!", "Sparklematic 5200 に Grime-Encrusted Item を投入し、機械を作動させるには銀貨3枚を必ず入れて下さい。", "この奇妙な機械は、部屋の外の狂気に対して持ち堪えているノームの中でもひときわ目立っている。装置につけられている小さな飾り板には 'The Sparklematic 5200' とある。さらに説明文が続いている。\n\n「汚れとカスがあなたの光り物を台無しにしている? Sparklematic 5200 が素敵な輝きを取り戻します! あなたが綺麗にしたい品物を入れて、銀貨3枚を硬貨投入口に入れて下さい。Sparklematic 5200 の作動が終わるまでしばらく待って、ほら出来上がり! 大切なものは綺麗にぴかぴかになって出てきます!」", "どうやらこの装置を動かすには、きれいにするための汚れのこびりついた品と、銀貨3枚が必要なようだ。その両方がそろっていれば、Sparklematic 5200は動くはずだ……", "汚れに覆われた物を入れ、Sparklematic 5200 に銀貨を3枚入れた。機械は得体の知れない物から汚れを取り除くべく、ほとんど怒り狂ったかのように揺れた。機械の中心からは大きく騒々しい撹拌の音が発せられている。左右に揺れると、金属のフレームの鼓動はぎいぎいと軋み、唸りを上げた……。", 0x7df37d0f, 0xa77d0758, 0x66b0513f, 0x38e80812, 0x55272153, "....." },
  [4605] = { "Sparklematic 5200!", nil, nil, nil, "動き始めるやいなや、Sparklematic 5200 は不意に停止した。簡素な「カーン」という音が聞こえ、機械の口が回転しながら開いた。Sparklematic 5200 の中には小さなリボンで包装された小さな箱が入っていた。汚れを除去した後、物体を包装するようだ。たとえ機械が動作しなくとも、少なくとも品物は可愛らしい箱に収められている。\n\nとにかく、品物が綺麗になっているかどうかを調べる方法はただひとつだ……。", 0x7df37d0f, nil, nil, nil, 0x6b359458, ".mmm." },
  [4606] = { "Sparklematic 5200!", nil, nil, nil, "動き始めるやいなや、Sparklematic 5200 は不意に停止した。簡素な「カーン」という音が聞こえ、機械の口が回転しながら開いた。Sparklematic 5200 の中には小さなリボンで包装された小さな箱が入っていた。汚れを除去した後、物体を包装するようだ。たとえ機械が動作しなくとも、少なくとも品物は可愛らしい箱に収められている。\n\nとにかく、品物が綺麗になっているかどうかを調べる方法はただひとつだ……。", 0x7df37d0f, nil, nil, nil, 0x6b359458, ".mmm." },
  [4621] = { "気をつけ、提督!", "Booty Bay の Fleet Master Seahorn ・ Baron Revilgaz を殺し、Stranglethorn Vale の海岸はずれに停泊している Crimson Veil 号の Fleet Master Firallon のところへ戻って下さい。", "良く聞けよ、水夫…… Booty Bay の親玉どもは俺たち Bloodsail から航路や獲物を隠してやがる。お前が Fleet Master Seahorn をナイフで殺っちまえば、Booty Bay の船と衝突しなくて済むし、Baron Revilgaz をナイフで殺っちまえば、連中の法で裁かれることもない。\n\nBloodsail の名誉ある提督になりたいんなら――そう、「提督」だぞ。あの二人を俺の言ったように殺れ。さあ行け、片付いたら戻ってこい。", "もう戻ってきやがったのか、この忌々しい水夫め! 俺の命令どおりにやってきたか? しくじったら板歩きの刑だぞ。\n\nアーーッ……", "気をつけ……{name} 提督! お前は海賊の中の海賊だ!\n\nこの帽子を渡せて嬉しいぞ。余所じゃこんなのは見つからんぞ。お前を見る者はみな、お前が Bloodsail Navy の提督だと分かるだろう!", 0x22df4694, 0x5d734ecb, 0x03b6fc7e, 0xdddf99b1, 0x25634252, ".....", nil, nil, 0x9519df18, nil, nil },
  [4641] = { "この世界でのあなたの場所", "Gornekに話しかけてください。そういえば、Kaltunkがあなたの地図に彼のいる場所の印をつけ、Gornekは西の建物(the Den)にいると話していました。", "おまえもついにその時が来たようだな。{name}... Hordeの名のもとに戦う年に。そう、Warchiefの栄誉を得る為に。\n\nふむ...\n\n<Kaltunkはあなたを見渡した>\n\nきっとうまくゆくだろう。\n\n多分おまえは巨大なドラゴンやデーモンを見つけ、素手でもそれらを撃退してやろうなんて考えているんだろう。しかし、もっと...危険が少ないことから始めたほうがかしこいってもんだ。\n\n<Kaltunkは笑った>\n\nGornekに報告に行け。彼は駆け出しの{class}向きの仕事を割り当ててくれるだろう。Gornekは西のThe Denにいる。", nil, "ん、またKaltunkからの紹介か？\n\nもしおぬしの力がHordeが送り出せる最大限のものだとしたら、我らは大変残念な状況に置かれているな。しかし問題はない。我らがおぬしがこの谷を去る準備ができたと思えるようになるころには、おぬしはHordeの誇り高き戦士となっていることであろうよ。", 0x3e605db7, 0x4dc50313, 0xfe9369ec, nil, 0x37f5f90f, "...m." },
  [4642] = { "作用の合体", "Merged Ooze SampleをUndercityのChemist Fuelyに渡して下さい。", "これは、お前が回収したFelwoodのサンプルから作った、容器入りのoozeだ。その容器をUn'Goro Craterへ持って行き、汚れのないoozeを見つけろ……primalの種類がちょうどいい。十分近づいたら、容器のoozeを放ち、両者が互いをどう思うか見てみようではないか。\n\n実験が終わったら、何であれ残ったもののサンプルを持ってこい。私はここ、Apothecariumで待っている。", "実験の進み具合はどうだ、{name}? 君が持ち帰ったサンプルの研究は続けていく――Lady Sylvanasがなぜこの生き物にそれほど関心を持っておられるのか、わかり始めてきた。もしこいつらが本当にOld Godsの一部なら、我々のためにどう使えるか計り知れない。", "おお、実に素晴らしい、{name}。実に素晴らしいよ。\n\nなんという話だ。その2つがあんなふうに作用し合うとは誰が思っただろうか……この生き物たちに変化をもたらす環境の問題を、もっと時間をかけて調べねばならないな。\n\n今のところは研究を続けるつもりだ。またすぐに話せるかもしれない。それまで、達者でな。", 0x78c0ed12, 0x710ae697, 0x8a377911, 0x01bad1fb, 0x78cc8d43, "....." },
  [4681] = { "打ち上げられたもの", "Auberdineの西の海にいるSkeletal Sea TurtleからSea Turtle Remainsを回収し、Auberdineに戻ってGwennyth Bly'Leggondeと話す。", "あの打ち上げられた生き物は、ここDarkshoreでは孤立した出来事ではありません。海岸沿いにも、水の中にさえ、まだいるのです。私たちが把握しているもう一体を調べてきていただきたいのです。報告では、Auberdineの真西、沈没船の近くの水中にあるそうです。私たちの研究の助けになりそうなものを回収して、戻ってきてください。\n\nそれから、旅の途中で他の生き物を見つけることもあるかもしれません。何か見つけたら、ぜひ私たちに知らせてください！", "ここから西の水中にある、その生き物のremainsを調べてくれれば、DarnassusのTemple of the Moonにきちんとした報告を出せるはずです。そうすれば、この不運な生き物たちがなぜDarkshoreの海岸に打ち上げられて命を終えることを選ぶのか、その理由の解明に近づけるかもしれません。", "今日は本当に大きな助けになってくれました。これで、なぜこの生き物たちがDarkshoreの海岸に自ら打ち上がるのか、その謎を解く確かな見込みができました。彼らがTeldrassil周辺から逃げてきているのかもしれないという考えは、心をざわつかせます。旅の途中で他にも見つけたら、ぜひ知らせてください。ここでの私たちの研究は、まだ始まったばかりなのです。\n\nTemple of the Moonを代表して、あなたの尽力への感謝としてこれを受け取ってください。ありがとう、{name}！", 0x8079e34a, 0x149950e7, 0xcc7a3f7b, 0x32bf10da, 0xa60fc069, "....." },
  [4701] = { "彼女を倒してください", "Blackrock Spireに出かけ、Worgの脅威の源を破壊してください。あなたがHelendisのもとを去るとき、彼は'Halycon'という名前を叫びました。それは、オークがWorgを指して呼ぶ名です。", "あなたは間違いなく、BlackrockオークがWorgに指令を出しているのを目にしたはずです。\n\n奇妙なことに - 私たちがどれだけ数多く倒しても、彼らの数は一向に減りません。偵察の報告によれば、Worgは繁殖させられ、訓練され、そしてBlackrockオークの首都、Blackrock Spireから送り出されています。あなたはBlackrock Spireに出かけ、脅威の源を発見しなければなりません。見つけ出し...そして破壊するのです。\n\n幸運を祈っています、{name}。Cenariusがあなたをお守りしますように...", "worgの脅威の元凶を見つけて、始末してくれたか?", "彼女が苦しんだことについてくよくよしないでください、{name}。あの猛獣は暗黒の魔法で呪われていました。あなたはAllianceに大きく貢献し、そして報酬を与えられるでしょう。", 0xcfb89cb2, 0x5042d196, 0x416df2bc, 0x3ae0a971, 0xe17375b6, "....." },
  [4721] = { "自然の守り人", "FelwoodのTrull Failbaneは、WinterspringのBerserk Owlbeast 10頭を狩るよう求めています。", "Winterspringから戻った伝令によれば、Winterspringの南部に小さな洞窟がいくつもあるそうだ。その洞窟の周辺にwildkinが陣取っているらしい。奴らが守っている価値あるものがあるなら、きっとそこで見つかるだろう。\n\nこれまでの種類よりも手強い相手だと分かるだろう、{name}。奴らは、自らが守ろうとしているまさにそのものに触れたせいで、狂ってしまったようだ。", "命令はわかっているはずだ、{name}。", "{name}よ、きつい仕事ってのは俺が大いに敬意を払ってるものなんだ。これでWinterspringの計画を進められるな。", 0x4ae5e0ac, 0x6995234b, 0xc3775c42, 0x638ad935, 0xb7573237, "....." },
  [4722] = { "打ち上げられたウミガメ", "Sea Turtle RemainsをAuberdineのGwennyth Bly'Leggondeのところへ持って行く。", "少し前にDarkshoreの海岸に打ち上げられたウミガメの死骸を見つけた。その生き物の亡骸の周りに陣取ったmurlocたちに食い荒らされている。それでも、亡骸にはAuberdineのGwennyth Bly'Leggondeが役立てられそうな、適当なサンプルがまだいくらか残っているようだ。", "こんにちは、{name}。岸に打ち上げられた生き物について、何か報告できる発見はありましたか?", "また新たな研究対象ですね。よくやりました、{name}！このremainsはDarnassusに届いたら、きちんと調査されます。研究のためにremainsを提供してくれたお礼として、このささやかな謝礼を受け取ってください。", 0x3b1c0992, 0xb04a5a8b, 0x3d413149, 0x1ac8bd61, 0x9e7fd774, "....." },
  [4723] = { "打ち上げられた海の生き物", "Sea Creature BonesをAuberdineのGwennyth Bly'Leggondeのところへ持って行く。", "巨大なthresherの亡骸が――Darkshoreで見かけるはずのものよりはるかに大きい――Mist's Edgeの海岸に打ち上げられている。この生き物がどうしてここに来たのかは分からない。今その死骸をむさぼっているmurlocの群れは、たとえ大勢でもこの獣を仕留めるには弱すぎるように見える。\n\n一部はきれいに食い尽くされているが、AuberdineのGwennyth Bly'Leggondeが研究するためのサンプルを採れるだけはまだ残っている。", "いつの日か、このかわいそうな生き物たちがDarkshoreの海岸で無駄に命を落とすのを防ぐ手段が見つかるかもしれません。それまでは、研究を続けなければ!\n\nこんにちは、{name}。どんな知らせを持ってきてくれましたか?", "また新たな発見ですね。よくやりました、{name}！この遺骸はDarnassusに届いたら、きちんと調査されます。研究のために遺骸を提供してくれたお礼として、このささやかな謝礼を受け取ってください。", 0x4bb68b2b, 0xc0ba3e69, 0x9a0bf524, 0x919b7748, 0x3513dc87, "....." },
  [4724] = { "群れの女王", "Bloodaxe worgの群れの女王、Halyconを討ち取って下さい。", "Blackrockのオークに操られているworgは、超自然の力の産物だと言う者もいる。本物のworgではなく、堕ちたpit lordがオークに与えた悪魔の犬の一種だと言う者もいる。\n\n真実はそれほど作り話めいてはいないが、同じくらい恐ろしい。Blackrockのworgは、Halyconとそのつがいから生まれるのだ。Halyconはworgの巨大な巣の母だ。そのつがいは? そいつについて生きて語った者は一人もいない。\n\nworgの中枢を叩け。Halyconを倒せ……それから{name}、背後に気をつけろ。", "群れの女主人が倒れた今、Spireのworgの見張りを減らしていき、いずれは都市への足がかりを築けるだろう。", "狂犬病の子犬? Gizrul the Slavener? それじゃ君は、生還してその話をしてるってのか?! 信じられん! 称賛の品が贈られて当然だよ!", 0xd14f9e29, 0xb373835f, 0x5dd20dfc, 0xeb799d55, 0xe160b968, "....." },
  [4725] = { "打ち上げられたウミガメ", "Strangely Marked BoxをAuberdineのGwennyth Bly'Leggondeのところへ持って行く。", "海岸沿いに、さらにウミガメの亡骸が打ち上げられている。この亡骸には、打ち捨てられた運搬用の台車が甲羅に取り付けられている。他の亡骸から推測されたように自ら乗り上げたのではなく、この生き物は何者かによって岸へ追いやられたのかもしれない。今ではGreymist murlocがこの生き物の亡骸をねぐらにして、腐肉をむさぼっている。\n\n台車の中に、奇妙な印が刻まれた箱が見つかった。AuberdineのGwennyth Bly'Leggondeなら、これが何か分かるかもしれない。", "またお会いできて嬉しいです、{name}。雄大な海の生き物たちがなぜDarkshoreの海岸に打ち上げられるのか、その謎の解明は大きく進んでいます。ですが、疑問が一つ解けるたびに、また2つ疑問が生まれるようなのです。\n\n私たちの研究に、さらに力を貸しに来てくださったのですか?", "あなたが見つけた海亀の背に付いていたような運搬具のことは聞いたことがあります。あれはnagaの運搬具で、戦闘にも、物資を陸へ運ぶのにも使われるものだと思います。あなたが見つけたboxの紋様はnagaのものです。これで、Darkshoreの遥か北部に彼らが侵入している理由も説明がつきます。\n\nこのboxは、あなたの他の発見物と一緒にDarnassusへ送ります。これはあなたに。改めて、協力に感謝します。", 0x3b1c0992, 0xe042fc30, 0xbf35a518, 0xeaee6b01, 0x3dd5d2a8, "....." },
  [4726] = { "Broodling Essence", "Burning SteppesのFlame CrestにいるTinkee Steamboilに、Broodling Essence 8つとDraco-Incarcinatrix 900を渡して下さい。", "Burning Steppesのdragonkinを何週間も研究してきて、ついに大発見をしたと思うんだ! 装置を作ったんだよ――Draco Incarcinatrix $N1って呼んでる。dragon whelp broodlingsの本質を捕らえられるんだ!\n\nというか、少なくともできると思う。\n\nほら、この装置を持って、Burning Steppesでbroodlingをこれで撃ってみて。装置の効果が効いている間にbroodlingを倒せば、本質が放出されるはずだよ。\n\nそうなったら、素晴らしい! 研究できるようにサンプルを持って帰ってきて!", "broodling essenceは手に入れたかい、{name}? 研究するのが待ちきれないよ。\n\nそれに……僕の後援者は、がっかりさせていい相手じゃないんだ。", "うまくいった! essenceを手に入れたんだな! でかしたぞ、{name}! よくやった!\n\nこのessenceは私の研究にとってこの上なく貴重だ。いつの日か、生きたdragon whelpを捕らえる方法を、あるいは卵を捕らえる方法を学びたいと思っている。その手立てを見つけられたら、世界中のdragon学者の羨望の的になるだろうな!\n\n雇い主も喜ぶだろう。前にも言ったが、あの方は機嫌を損ねたくない相手でね……", 0xf3512895, 0x9d6bb3b9, 0x0cab447e, 0x6d342062, 0xe8011b91, "....." },
  [4727] = { "打ち上げられたウミガメ", "Sea Turtle RemainsをAuberdineのGwennyth Bly'Leggondeのところへ持って行く。", "Darkshore北部の浜辺の砂の中に、ウミガメの骨が横たわっている。Greymist murlocはこの死骸をまだ見つけていないのか、あるいは見つけたものの何らかの理由で避けているのかもしれない。いずれにせよ、Temple of the Moonが研究できるよう、AuberdineのGwennyth Bly'Leggondeのもとへサンプルを持ち帰れるだけの部分は残っている。", "またお会いしましたね、{name}。Temple of the Moonが知っておくべき、打ち上げられた生き物をまた見つけましたか?", "この場所にmurlocがいなかったのは興味深いですね。この生き物のremainsを調べる際には、そのことを念頭に置いておきます！尽力してくれてありがとう、{name}。Temple of the Moonから、あなたの時間への謝礼としてこれを渡すよう言付かっています。", 0x3b1c0992, 0xb04a5a8b, 0x571231c8, 0x7d319b8f, 0x07b7db83, "....." },
  [4728] = { "打ち上げられた海の生き物", "Sea Creature BonesをAuberdineのGwennyth Bly'Leggondeのところへ持って行く。", "何か巨大な海の哺乳類らしきものの死骸が、腹を一部裂かれた状態で浜辺に横たわっている。この打ち上げられた巨大な海の生き物のそばには、手押し車とさまざまな道具が打ち捨てられている。以前に誰かがこれを調べようとしたかのようだ。murlocに食い荒らされてはいるが、AuberdineのGwennyth Bly'Leggondeのために適当なサンプルを集められるだけは残っている。", "またお会いしましたね、{name}! Auberdineにはどんなご用で戻ってこられたのですか? もしかして、また発見の報告でしょうか?", "ああ、それはもともとExplorer's Leagueが調べていたものだと思います。彼らはここDarkshoreにも拠点を置いていて、打ち上げられた生き物の1体を調べていたところ、murlocに追い払われたと話していました。私たちのどちらも成し得なかったことを、あなたは成し遂げたようですね。どうか、Temple of the Moonを代表して、この謝礼を受け取ってください。", 0x4bb68b2b, 0xc0ba3e69, 0xb92ea900, 0x2d08586e, 0xc17c3fc8, "....." },
  [4729] = { "Kiblerの珍しいペット", "Blackrock Spireへ行ってBloodaxe Worg Pupを見つけて下さい。獰猛な小動物を運ぶには檻を使用して下さい。Caged Worg PupをKiblerのところへ持ち帰って下さい。", "俺がこんな所で何してるのか不思議に思ってるだろ。檻を見なよ! 一目瞭然じゃないか?\n\n俺は何よりまず動物好きだが、本業は商売人さ。金持ちや有名人のために珍しい動物を探し出して、ちゃんとしたペットらしく振る舞うよう手なずけてるんだ。\n\nで、お前さんは今「Kibler、何をすればいい?」って思ってるだろ。答えは簡単さ。この獣用の檻を持って、worg pupsを見つけてきてくれ。そうしたら、お前さんにworgを一匹手なずけてやるよ!", "<KiblerはOpusと言い争うのに忙しい。>", "完璧なタイミングで持ってきてくれたね、{name}。少しでも遅れてたら飼い慣らせなくなってたよ! ちょっくら待ってな、持ち帰れるように小さな奴を用意してやるから。", 0xc161566b, 0x43257fa1, 0x2a9d1322, 0x7a68d331, 0x0346ba26, "....." },
  [4730] = { "打ち上げられた海の生き物", "Sea Creature BonesをAuberdineのGwennyth Bly'Leggondeのところへ持って行く。", "巨大な海の哺乳類だったかもしれないものの、半分食われた死骸が浜辺に横たわっている。Auberdineの近くにいるものより強いmurlocの一団が、倒れた生き物の周りに住みついている。その生き物はまだ十分に残っていて、骨の適当なサンプルをAuberdineのGwennyth Bly'Leggondeに届けられそうだ。", "またお会いしましたね、{name}! また発見の報告に来てくださったのですか?", "あなたが持ってきたbonesは、Teldrassilの根元を囲む海域に棲むことで知られる、おとなしい海の哺乳類のものです。彼らは、thresherのように激しく自ら打ち上がることで知られてはいませんでした。なぜこの生き物たちはこんなことをするのでしょう。まあ、その遺骸を研究すれば、私たちが求める知識の実を結ぶかもしれません。\n\n改めて、あなたの助けに感謝します。Temple of the Moonからのこの謝礼を受け取ってください。", 0x4bb68b2b, 0xc0ba3e69, 0xe841063a, 0xd044bb6e, 0x6ea9c612, "....." },
  [4731] = { "打ち上げられたウミガメ", "Strangely Marked BoxをAuberdineのGwennyth Bly'Leggondeのところへ持って行く。", "海岸にまた別のウミガメの亡骸が打ち上げられている。この亡骸には、打ち捨てられた運搬用の台車が、甲羅に半ば留め付けられたままになっている。他の亡骸から推測されたように自ら乗り上げたのではなく、この生き物は何者かによって岸へ追いやられたのかもしれない。強力なGreymist murlocがこの生き物の死骸を今のねぐらにしている。\n\n台車の中に、奇妙な印が刻まれた箱が見つかった。AuberdineのGwennyth Bly'Leggondeなら、これが何か分かるかもしれない。", "またお会いしましたね、{name}。Temple of the Moonのためにあなたがしてくださった働きは素晴らしいものでした。私たちのために、さらにお力添えをいただけるのでしょうか?", "あの海亀の背に付いていたような運搬具のことは聞いたことがあります。あれはnagaの運搬具で、戦闘にも、物資を陸へ運ぶのにも使われるものだと思います。あなたが見つけたboxの紋様はnagaのものです。もしかすると、あなたが見つけた生き物は、さらに南へ……Ashenvaleへでも向かう途中で殺されたのかもしれません。\n\nこのboxは、必ずあなたの他の発見物と一緒にDarnassusへ送ります。これはあなたに。改めて、協力に感謝します。", 0x3b1c0992, 0xe042fc30, 0x8653ac9e, 0x69e011cf, 0xb192bb2e, "....." },
  [4732] = { "打ち上げられたウミガメ", "Sea Turtle RemainsをAuberdineのGwennyth Bly'Leggondeのところへ持って行く。", "少し前にDarkshoreの海岸に打ち上げられたウミガメの死骸を見つけた。今その生き物の亡骸の周りに陣取っているまさにそのGreymist murlocに、ほとんどきれいに食い尽くされている。それでも、亡骸にはAuberdineのGwennyth Bly'Leggondeが役立てられそうな、適当なサンプルがまだいくらか残っているようだ。", "またお会いしましたね、{name}。Temple of the Moonに報告する発見は、ほかにもありますか?", "さらに打ち上げられた生き物を見つけたのですか、{name}？Nordrassilが破壊される前は、その根元で海亀が戯れる姿がよく見られました。しかしTeldrassilが誕生してからは、その数は減る一方です。私たちが見つけたように、何らかの理由でここで命を終えるものもいます。\n\nあなたの助けが、目の前の謎を解き明かすかもしれません。研究のためにremainsを提供してくれたお礼として、これを受け取ってください。", 0x3b1c0992, 0xb04a5a8b, 0x149a42d1, 0x068b830b, 0x96ba0af6, "....." },
  [4733] = { "打ち上げられた海の生き物", "Sea Creature BonesをAuberdineのGwennyth Bly'Leggondeのところへ持って行く。", "巨大なthresherのように見えるものの亡骸が、Twilight Shoreの岩の多い入り江に打ち上げられている。このthresherは、この辺りで見かける他のどのthresherよりも数倍大きい。どこから来たにせよ、この生き物はDarkshoreに元から棲むものではなさそうだ。\n\nところどころ食いちぎられてはいるが、AuberdineのGwennyth Bly'Leggondeのために適当なサンプルを集められるだけは残っている。", "Eluneに感謝を。またお会いできて嬉しいです、親愛なる{name}。奇妙な打ち上げ現象についてのTemple of the Moonの調査は、ここDarkshoreで続いています。何か、さらに私たちに提供していただけるものはありますか?", "あなたが話すthresherの大きさは驚くべきものです。この地域で最も年を経たthresherでさえ、その何分の一かの大きさにしか育ちません。Teldrassilの近くにはもっと大きなものもいると知られていましたが、その数は着実に減っています。ここで打ち上がっているこの生き物たちが、何かそれと関係しているのではと思わずにはいられません。\n\n持ってきてくれたbonesを分析する間、Temple of the Moonを代表してこれを受け取ってください。ありがとう、{name}。", 0x4bb68b2b, 0xc0ba3e69, 0x88008738, 0x2ba63290, 0xa5eb453e, "....." },
  [4734] = { "卵の凍結", "Blackrock SpireのRookeryにある卵にEggscilloscope Prototypeを使って下さい。", "{name}、新しい装置、eggscilloscopeの開発に打ち込んでたんだ! 黒いドラゴンの卵に冷気のエネルギーを放って……カチカチに凍らせるように設計してあるんだよ! 試してみてくれない?\n\nBlackrock Spireの高いところに、ドラゴンが卵を孵す孵化場があるって聞いたんだ。eggscilloscopeを試すにはそこへ行くしかない。それから、うまくいったか教えてね!\n\nそれと心配しないで。凍ったドラゴンの卵は無害なはずだから。心配しなきゃいけないのは、凍ってないほうだよ!", "{name}、eggscilloscopeは試してみたかい?", "うまくいったのか? 素晴らしい! そうなると分かっていたよ!\n\n君がいない間に、eggscilloscopeの新型に取りかかっていたんだ。こっちはずっと射程が長い。\n\nほら、Blackrock Spireにまた行くときのために、一つ持っていくといい。", 0xd86966f2, 0x4409fe76, 0x9c1ff9d5, 0xae292932, 0x28c0d761, "....." },
  [4735] = { "卵コレクション", "Collected Dragon Egg 8個とCollectronic Moduleを、Burning SteppesのFlame CrestにいるTinkee Steamboilに渡して下さい。", "{name}、ついにドラゴンの卵の本物のサンプルを集める準備ができたよ! ほら、このcollectronic moduleを持っていって。ドラゴンの卵を取り出して、運べるように準備する装置なんだ。Rookeryに戻って、このmoduleで卵を集めてきて。\n\nそれと、先に凍らせるのを忘れないでね。じゃないと、集める前に孵っちゃうかもしれないから!\n\n卵が十分集まったら、私のところへ持ってきて!", "eggsは持ってきてくれたかい、{name}? 君が僕のために集めてくれてるって聞いて、僕の後援者は手に入れるのを今か今かと待ってるんだ!", "おお、手に入れたんだな! collectronic moduleがうまくいった! 僕は天才だ!\n\nありがとう、{name}。僕の後援者は、このeggsを手に入れてとても喜ぶだろうね……", 0x46624cc2, 0xf424606c, 0x9fb80264, 0x8669b96c, 0xa116f248, "....." },
  [4736] = { "Menara Voidrenderを捜して", "BarrensのMenara Voidrenderに話しかけて下さい。", "ああ、やあ、{name}。訓練は順調に進んでいるな。あまりに順調だから、その努力に――それと、まだ秘術に堕落していないことに――報いるべきだと思うのだ。\n\n興味があるなら、RatchetのMenara Voidrenderを訪ねるといい。彼女は今、町を見下ろすStrahad Farsanの塔に滞在している。\n\nあまり愛想のいい女ではないぞ、{name}。褒め言葉は期待するな。だが一生懸命やれば、面倒は見てくれるだろう。", nil, "ああ、Briarthornが君を寄越したのか。よい。ならば、噂は未来の弟子を見つけるだけ遠くまで届くということだ。それは喜ばしい。\n\n我々のような者が種族を問わず結束するのは、当然のことだ、{name}。我々が最も多く相手にする者たちは、なだめ損ねたり、きちんと制御し損ねたりすれば、その悪意において相手を選ばない。だからこそ、なおのこと大切なのだ。\n\n君は実に多くを学んだようだ。望むなら、君の技を補う道具を作る手伝いをしよう。", 0x10f09105, 0xdd3a1725, 0x1f30d3ac, nil, 0xa4bfa39e, "...m." },
  [4737] = { "Menara Voidrenderを捜して", "BarrensのMenara Voidrenderに話しかけて下さい。", "ふん、まだ力を求めてあがくか。いずれ堕落と中毒がお前をとらえ、お前は力で支配しようとしているものの奴隷になる。それは時間の問題にすぎん。\n\nフン! 愚か者め! 時がわしの正しさを証明するだろう――ほかの何でもない……時だけがな。\n\nだが、皆がこのZevrostと同意見というわけではないらしい。Menaraはお前がより強くなり、その力を使いこなすための道具を作ってやるつもりのようだ。興味があるなら、BarrensのRatchetへ行け。彼女はそこで町を見下ろしている。", nil, "ああ、Zevrostが君を寄越したのか。よい。ならば、噂は未来の弟子を見つけるだけ遠くまで届くということだ。それは喜ばしい。\n\n我々のような者が種族を問わず結束するのは、当然のことだ、{name}。我々が最も多く相手にする者たちは、なだめ損ねたり、きちんと制御し損ねたりすれば、その悪意において相手を選ばない。だからこそ、なおのこと大切なのだ。\n\n君は実に多くを学んだようだ。望むなら、君の技を補う道具を作る手伝いをしよう。", 0x10f09105, 0xdd3a1725, 0x1ffc2c9b, nil, 0x76faa6d0, "...m." },
  [4738] = { "Menara Voidrenderを捜して", "BarrensのMenara Voidrenderに話しかけて下さい。", "一つはっきりさせておこう、{name}。お前にそのような責任を負う準備ができているとは思えん。力ある品の製作に手を貸すなど、新米が関わるべきことではない。ましてや、これほど未熟な者ならなおさらだ。\n\nだが、それを決めるのは私ではない。上の者たち、少なくともお前にそのような贈り物を授けたいと願う者たちが決めることだ。\n\nもっと知りたければ、RatchetのMenara Voidrenderを訪ねるといい。彼女はたいてい港町の上の塔にいる。", nil, "ああ、Demisetteが君を寄越したのか。よい。ならば、噂は未来の弟子を見つけるだけ遠くまで届くということだ。それは喜ばしい。\n\n我々のような者が種族を問わず結束するのは、当然のことだ、{name}。我々が最も多く相手にする者たちは、なだめ損ねたり、きちんと制御し損ねたりすれば、その悪意において相手を選ばない。だからこそ、なおのこと大切なのだ。\n\n君は実に多くを学んだようだ。望むなら、君の技を補う道具を作る手伝いをしよう。", 0x10f09105, 0x7c0126bb, 0x28c69a48, nil, 0xb18020cd, "...m." },
  [4739] = { "Menara Voidrenderを捜して", "BarrensのMenara Voidrenderに話しかけて下さい。", "{class}! そう、お前だ!\n\n装備は揃っていないが、準備ができているのは一目瞭然だ――お前の周りの空気から、より大きな自信があふれ出ている。そうだ、今ならはっきり分かる。\n\n準備ができたと感じるなら、Menara Voidrenderがいくつかのことを教えてくれるだろう。彼女は若い生徒たちに秘術を教えて過ごしている。試練に合格した者には贈り物までくれるぞ。\n\n興味があるなら、BarrensのRatchetへ行け。彼女は町の上の、Strahadの塔にいる。", nil, "ああ、Kaalが君を寄越したのか。よい。ならば、噂は未来の弟子を見つけるだけ遠くまで届くということだ。それは喜ばしい。\n\n我々のような者が種族を問わず結束するのは、当然のことだ、{name}。我々が最も多く相手にする者たちは、なだめ損ねたり、きちんと制御し損ねたりすれば、その悪意において相手を選ばない。だからこそ、なおのこと大切なのだ。\n\n君は実に多くを学んだようだ。望むなら、君の技を補う道具を作る手伝いをしよう。", 0x10f09105, 0xdd3a1725, 0x047f9579, nil, 0x6556e634, "...m." },
  [4740] = { "お尋ね者：Murkdeep！", "Murkdeepと呼ばれるmurlocを見つけて倒す。そいつはAuberdineの南、水辺にあるmurlocの小屋を守っていると考えられている。\n\nMurkdeepの死をAuberdineのSentinel Glynda Nal'Sheaに報告する。", "注目！\n\nmurlocの「Murkdeep」の死に対して報酬を出す。この卑劣な獣は少なくとも1人のSentinelの死に責任があることが分かっており、Darkshore沖の海で少なくとも2隻の貨物船を沈めた疑いもかけられている！\n\nMurkdeepが最後に目撃されたのは、Auberdineの南にある小屋の立ち並ぶmurlocの野営地で、そこの小屋を守っていると思われる。この賞金の請求は、AuberdineのSentinel Glynda Nal'Sheaに申し出ること。\n\nAuberdine Village Council", "ごきげんよう、{class}。今日はSentinelsに何のご用でしょう? もしかして、Murkdeepにかけられた賞金のことを聞きに来たのですか?", "おや、ただ話を聞きに来ただけじゃないようだな！今夜は少しでも安心して、安全に眠れると知ったら、住民たちも喜ぶだろう。\n\n今日の君は、Auberdineの人々のために正義を執行してくれた、{name}。そのお礼として、ふさわしい報酬を贈りたい……Auberdineの人々の真の英雄に。", 0xcf1b7374, 0xd0180f37, 0x68da692c, 0x1e209309, 0xb1230932, "....." },
  [4741] = { "自然の守り人", "FelwoodのTrull Failbaneは、Moontouched Owlbeast 13頭を狩るよう求めています。", "Winterspringの北部では、Wildkinがさらに凶暴になっている。我々はそこでも対策を続けねばならん。\n\nWinterspringでmoontouched owlbeastsを狩り、奴らの棲む地域を探索しろ。\n\n危険な地だが、お前ならこの試練を乗り越えられると分かっている。wildkinを$N1体倒したら、私のもとへ戻ってこい。", "怖くて行けないなんて言わせないぞ! さっさと行け!", "仕事を楽しんでるのが分かるぞ。それと、ちょっと思い当たることがあるんだ。", 0x4ae5e0ac, 0x76331e15, 0xfb16acf5, 0x16914799, 0x632109b1, "....." },
  [4742] = { "Seal of Ascension", "指揮の宝石3つ、Gemstone of Smolderthorn、Gemstone of Spirestone、Gemstone of Bloodaxeを見つける。それらをUnadorned Seal of Ascensionと一緒にVaelanのところへ持ち帰って下さい。\n\nVaelanから聞いた将軍たちは、SmolderthornのWar Master Voone、SpirestoneのHighlord Omokk、BloodaxeのOverlord Wyrmthalakだ。", "見てのとおり、unadorned sealには空の窪みが3つある。その窪みの一つ一つを、指導者たちの権威を表す宝石で満たさねばならん。最後に、下層の城塞の主であるOverlord Wyrmthalakが、Black Dragonflightの炎でその印章を鍛えねばならんのだ。\n\n心得よ、定命の者よ。下層の城塞の3人の将軍の誰かが、いつ何時でも宝石を持っている見込みは低い。この探求では油断するな。決意を失うな!", "何よりも勇気と忍耐だ、{name}!", "<Vaelanの姿が一瞬ぼやける。>\n\n<あなたが集めた破片が消え去った。>\n\nUnforged Seal of Ascensionの準備が整った。最後の段階に移る時だ。", 0xf0f215e7, 0x2162d61c, 0xa741b187, 0x5c4e12a1, 0x523d6f59, "....." },
  [4743] = { "Seal of Ascension", "Dustwallow MarshのWyrmbogへ行く。古のドレイク、Emberstrifeを見つけ出し、その意志が折れるまで容赦なく叩きのめして下さい。\n\nその瞬間に、Unforged Seal of Ascensionをその巨大な獣の前に置かなければならない。それから素早く、弱ったEmberstrifeにOrb of Draconic Energyを使い、その精神を支配下に置く。獣を操り、Flames of the Black DragonflightをUnforged Seal of Ascensionに浴びせるのだ!", "上層の城塞にいる者を除けば、黒きdragonkinの中で、自らの燃える息で印章を鍛えられる者はわずかだ。Wyrmthalakはそのような者の一人だが、奴の意志は決して折れん。\n\nDustwallow MarshのWyrmbogへ赴かねばならん。そこでEmberstrifeと呼ばれる古のdrakeを見つけるだろう。奴の意志を打ち砕くのだ、{name}。打ち砕いたら、弱った奴にこのオーブを使え。奴の心を支配し、印章を鍛える炎をあおるための時間は、ほんの数秒しかない。", "一刻も無駄にするな、{name}。Nefarianは我らの世界に悪をもたらそうと、躍起になって動いている。", "最後の守りの祈祷を唱える間、じっとしていろ。\n\n<Vaelanの両目が二つの炎の球と化す。>\n\nSeal of Ascensionが完成した……\n\n覚えておけ、この遺物には強力な守りの加護を込めてある。すべてが失われたと見える最も暗い時に、red flightの力が君の意のままとなるだろう。", 0xf0f215e7, 0xd5e99e4f, 0x25238491, 0xcf559296, 0x66a1f4a0, "....." },
  [4761] = { "Thundris Windweaver", "AuberdineのThundris Windweaverと話す。", "あなたがfurbolgの野営地を偵察して得た情報は、Thundris Windweaverに知らせるべきものです。彼はありがたいことにAuberdineの長老を務め、村の日々の事柄を賢明かつ公正に取り仕切ってくださっています。どうか、これまでに分かったfurbolgの状況を彼に伝えてください。\n\n彼は彼らの堕落の理由について、独自の考えを持っているようです。彼と協力して、ここの自然の均衡を取り戻す計画を実行できるかもしれません！", nil, "よく来た、{class}。君によるfurbolgの状況の偵察は、ここAuberdineにいる我々にとって実に良い時期に届いた。しばらく前から、我々は今や公然と敵意を向けてくる森の住人たちだけでなく、森そのものの露骨な腐敗にも対処してきた。この困難な時に、君がAuberdineに力を貸してくれることを願っている。", 0xa1402122, 0xe04eac93, 0x5978da41, nil, 0x8e442694, "...m." },
  [4762] = { "Cliffspring River", "Auberdineの北、Cliffspring River沿いにある最初の滝へ行き、そこの池から水を汲む。\n\nCliffspring River SampleをAuberdineのThundris Windweaverのところへ持ち帰る。", "Cliffspring Riverが汚れ、腐り始めています。その川はMist's Edgeに注いでいて、その流れがじきにAuberdineにも影響を及ぼすのではないかと心配なのです。汚染の原因は上流のBlackwood furbolgだと思っていますが、彼らが本当の根源ではないのではないかとも思っています。\n\nこの採取管を持って、北にある川の河口へ行ってください。内陸へ進んで最初の滝まで行き、そこの淵からサンプルを採ってください。頭上に橋が見えるはずです。サンプルを採ったら、Auberdineの私のもとへ戻ってきてください。", "Cliffspring Riverの汚染は、ここDarkshoreで起きている憂慮すべき流れの始まりにすぎません。あなたが持ってきてくれるsampleは、私たちが計画を練る助けになるでしょう……それは攻撃の計画になるのではないかと、私は思い始めています。", "この水が汚れているのは驚くことではないが、どれほど腐りかけているか見てくれ！早めに手を打つ必要がありそうだな、{name}？\n\n東にあるのがFelwoodだ。そこがこの腐敗の本当の源で、私はかつてそれを目にしたことがある。このsampleがそれを裏付けるだろう。ここで治療法を講じることができるかもしれないが、それを試すにも助けが必要だ。その時が来たら、{name}、君が力を貸してくれることを願っている。", 0x732408df, 0x9c875372, 0x31c4d12c, 0xcd07cafd, 0x405bb8d6, "....." },
  [4763] = { "堕落したBlackwood", "Auberdine MoonwellでEmpty Cleansing Bowlを満たす。\n\n北にあるBlackwood furbolgの野営地から、果物、木の実、穀物の見本を集める。\n\nボウルの中身を混ぜ、北の野営地でCliffspring Riverに最も近いかがり火のそばに置き、satyrの堕落者を呼び出す。\n\nTalisman of Corruptionを手に入れ、AuberdineのThundris Windweaverのところへ持って行く。", "furbolgの堕落の原因の一つがsatyrにあることが分かりました。satyrは魔力を流し込むお守りによって支配しているのです。furbolgに救いの望みがあるのなら、satyrの堕落者をおびき出し、そのお守りを奪わなければなりません！\n\nこの鉢に私たちの月の泉の水を満たし、北の野営地からfurbolgの食べ物のサンプルを取ってきてください。それらを混ぜて川辺のかがり火のそばに置けば、それを食べたfurbolgは、satyrの堕落者をおびき出せるだけの間、浄化されます……そしてその堕落者を、あなたが倒すのです！", "Talisman of Corruptionは、自然の均衡を歪めるためだけに存在する邪悪な道具です。furbolgたちを苦しめているsatyrからこの品を奪い、処分のために私のもとへ持ってきてくれれば、今日、私たちは大きな勝利を収めることになるでしょう!", "堕落の勢力から私たちの森を取り戻すこの戦いは始まったばかりですが、今日の戦いには勝利しました！ {name}、Auberdineの人々はあなたに、容易には返しきれない恩を負っています。私たちの感謝とともに、これを受け取ってください。今日ここで学んだことは、いつの日か私たちのfurbolgの友を苦しみの枷から永遠に解き放つかもしれません。", 0x2f8f88d9, 0xbffe0b22, 0xb9e3e349, 0x893d1d9e, 0xa947b3e7, "....." },
  [4764] = { "Doomrigger's Clasp", "Burning SteppesのMayara BrightwingにDoomrigger's Claspを渡して下さい。", "Blackrock Spireの高みに、かつてHall of Fortuneと呼ばれた部屋がある。Dark Ironのドワーフが遺物や戦利品、美術品を保管していた場所だ。\n\nそれは遠い昔のこと。今ではその広間は崩れ落ち……あまり感心できない用途に使われているという。だが、古いドワーフの遺物がまだそこに残っているかもしれないと私は思う。\n\nそうした遺物の一つがDoomrigger's claspだ。その表面は珍しい宝石でびっしりと覆われていて、見つめたドワーフは誰でも涙を流すと言われたほどだ。\n\nその留め金こそ、{name}、お前の目標だ。", "claspは手に入れたかい、{name}? 僕の後援者がたっぷり払ってくれるよ。", "見つけたのか! では噂は本当だったんだな!\n\nありがとう、{name}。私の後援者であるCount Remington Ridgewellは、収蔵品にこれが加わるのを見て大いに喜ぶだろう。", 0x2d327b90, 0xe26bc34c, 0x50d49bc2, 0x9da3cae3, 0xf09398d5, "....." },
  [4765] = { "Ridgewellへの配達", "StormwindのStormwind KeepにいるCount Remington Ridgewellに、Ridgewell's Crateを渡して下さい。", "Doomriggers ClaspをStormwindへ送れるように木箱に詰めておいた。{name}、本当によく助けてくれた――最後にもう一つ頼みごとをしてもいいかい?\n\nこの木箱をCount Remington Ridgewellに届けてくれ。Keep of Stormwindにいるはずだ。君が持ってきたものを見たら、きっととても喜ぶだろう。", "使者が来ると聞いていた。Blackrock Spireからの贈り物を持った者がな。\n\nお前がその者か?", "ああ、あなたか! 感謝しますよ、{name}。それと……知っておられるかどうか……Ridgewell家の貴族の感謝は、王の身代金にも匹敵するのです。", 0x8cf04bff, 0xf7182c21, 0xa8e591a6, 0xe5568bb1, 0x3663f6c4, ".....", nil, nil, nil, 0x5cc3b051, 0x14f78b72 },
  [4766] = { "Mayara Brightwing", "Burning SteppesのMayara Brightwingと話して下さい。", "私の手の者、Mayara BrightwingがBurning Steppesへ送られ、Thaurissanの廃墟の都を偵察している。Dark Ironのドワーフのあの滅びた都には、大いなる価値のある品が隠されているかもしれん……我が一族の博物館にぴったりの品がな。\n\nMayaraが言うには、何かを見つけたので回収に手助けが要るとのことだが、それはThaurissanにあるのではない。Blackrock Spireに踏み込む必要があるのだ。\n\n詳しいことは知らんが、興味があるならBurning SteppesにいるMayaraと話してくれ。", nil, "Stormwindから来たのか? 素晴らしい――Remingtonが自分の博物館にどうしても欲しがるであろう美術品に心当たりがある。だが、それを持ち出すのは容易ではない。\n\nそこで君の出番というわけだ。", 0x05c75784, 0x56e79fbe, 0x1d85f073, nil, 0xe3cb6b7f, "...m." },
  [4767] = { "風に乗る者", "Freewind PostのEluに、Highperch Wyvern Eggを10個渡して下さい。", "master wind riderのために、もっとwyvernを補充するよう仕事を言いつけられてるんだ。wind riderの人数は増えてきてて、俺自身もいつかwind riderになりたいと思ってるんだ。だけど、需要に追いつくのに充分な数のwyvernを訓練出来ないんだ。{name}、君なら手伝えると思う。\n\nHighperchへwyvernの卵をいくつか集めに行ってほしいんだ。ここから渓谷の壁沿いに、Highperchへ行ける斜面のところまで北西へ向かってくれ。気をつけてな。wyvernは卵を守るのに必死で、侵入者に決して甘くはないだろうからね。", "{name}、僕が探してるwyvern eggsは取ってきてくれた? wind riderの訓練を始めたくて、うずうずしてるんだ!", "完璧だ! この卵があれば、wind riderになる次の段階へ踏み出せるよ。これは感謝の印だよ。素晴らしい狩りがいつも君を照らしますように、{class}。", 0xb115ace3, 0x1b0bf486, 0x8c494c01, 0x55a37b15, 0x2fee56fe, "....." },
  [4768] = { "Darkstone Tablet", "KargathのShadow Mage Vivian LagraveにDarkstone Tabletを渡して下さい。", "Darkstone Tabletには、はるか昔に死んだドワーフ、Urheld Darkstoneの著作が記されている。優れた腕を持つ錬金術師だったが、同時代の者たちからは狂っていると思われ、そのため研究を人に明かさなかった。\n\nだが彼はそれを石板に刻んだ。その石板の一つが、Blackrock Spireの、かつてHall of Fortuneと呼ばれた部屋にあると私は考えている。今それが何と呼ばれているのかは知らん。Blackrockに入って戻ってくる者はほとんどいないのでな。\n\nだが、その危険に挑み、石板を持って戻ってくる気があるなら、報酬は大きいぞ。", "Tabletは見つかったか、{name}? その秘密を探りたくてたまらないのだ。", "見事だ。このtabletに刻まれた式を解くには何日もの研究が必要だろうが、その研究は必ず甘い実を結ぶと確信している。\n\nありがとう、{name}。君は我々にとってこの上なく貴重な存在だった。", 0x9658baee, 0x9010bf76, 0x92a5578e, 0x7a25f7d7, 0xfa7108f2, "....." },
  [4769] = { "Vivian LagraveとDarkstone Tablet", "Shadowmage Vivian Lagraveと話して下さい。", "BadlandsのKargathにいるVivian Lagraveから知らせが届いた。研究の結果、Blackrock Spireの中に我々の研究に役立つ古の文書があると彼女は考えている。それを確かめるには、その尖塔から文書を持ち出す者が必要だ。容易な仕事ではない。\n\n興味があるなら、KargathのVivianと話せ。", nil, "本当だ。Blackrock Spireの中に、古い錬金術の調合法が記されたtabletがあると私は考えている。君が来てくれて嬉しい。そのtabletを取り戻すのに助けが要るのだ。\n\n楽にしてくれ。もっと詳しく説明しよう。", 0x1edac7b5, 0x816f52d4, 0xc42a7bd5, nil, 0xd02ea1cc, "...m." },
  [4770] = { "家路へ", "HighperchからPao'ka Swiftmountainを護衛し、Whitereach PostのMotega Firemaneと話して下さい。", "助けてください、{class}! 随分ここに隠れていて、親しい顔を見てから何日も経ってしまいました。wyvernの調査をするためにここへ来ましたが、近付きすぎたんだと思います。巣から追い払われた後、道に迷ってしまいました。\n\nWhitereach Postへ戻りたいのです! Motegaは私がいなくなったことを知りませんが、自ら危険を冒してHighperchへ行ったと知ったら怒り狂うでしょう。\n\nWhitereach Postはここの真東です……連れて行って下さい!", nil, "何だって!? Pao'ka SwiftmountainがHighperchの辺りを嗅ぎ回っていると知ってたら、トーテムへ縛り付けておいたろうに! 彼の父は、彼が私と共にThousand Needlesへ来ることを渋々許したんだ。この美しい土地に住む変わった生物を調査するために、ここへやって来たんだ。\n\nPao'kaを連れてきてくれたことに感謝するよ。道案内にかかった負担をこれで補えればいいんだが。", 0x495ac7e2, 0xf36b8eeb, 0x9c7efe0f, nil, 0xc6301876, "...m." },
  [4771] = { "Dawn's Gambit", "Dawn's GambitをScholomanceのViewing Roomに置いて下さい。Vectusを倒し、Betina Bigglezinkのところへ戻って下さい。", "君が持ってきてくれた容器、ドラゴンの卵が入っていたあれに、Dawn's Gambitを入れておいた。君の仕事は、それをScholomanceの奥深くまで運ぶことだ。\n\nアンデッドのメイジであるVectusが、scourgeの学者たちを率いている……Dawn's Gambitを彼らの部屋、「観察室」と呼ばれる場所に置くんだ。そうすれば、そこにいるアンデッドと反応して、運が良ければ奴らを滅ぼしてくれる！\n\nその後なら、Vectusを倒すのは難しくないはずだ。だろう？", "忘れないでください、{name}。私たちは寛容でありながら、信念においては揺るぎなくあらねばならないのです!", "やったね！ Vectusを倒したんだ！ それで、Dawn's Gambitは……うまくいった？\n\nうーん……僕の装置は期待したほどの成功じゃなかったかもしれないけど、とにかく君がうまく片付けてくれてよかったよ。よくやったね、{name}！\n\nArgent Dawnも、Azerothの善き人々も、君に恩ができたよ。", 0xe69ac5eb, 0x6d5640e4, 0xa08c5d9e, 0x2a558b5c, 0x872f453b, "....." },
  [4781] = { "Enchanted Gold Bloodrobeの材料", "Stranglethorn ValeのXizk GoodstitchにGold Barを渡して下さい。", "次の務めも最初のものと同じく単純だが、助けを求める必要がある。\n\n外套の刺繍には金糸が要る。だが金糸は手に入りにくく、作り方を知る者もごくわずかだ。幸い、我らの大義に忠実な者の一人がその秘訣を知っていて、我らの位階を昇る者たちを進んで助けてくれる。\n\ngold barをBooty BayのXizk Goodstitchのところへ持って行け。腕利きの仕立屋で、喜んで糸を紡いでくれるだろう。Gold barsは熟練した鉱夫が精錬する。鉱夫に助けを頼め。", "Gold bars、そう……そうだ。1本持ってきてくれれば、糸を紡いでやれるか考えよう。それまでは、もっと強くなることに力を注ぐといい。本当に厳しい試練はまだ先に待っている。信じてくれ……自分がどれほど強いと思っていようと、もっと備えておけばよかったと思うことになるだろう。", "完璧だ、{name}。手伝ってくれる鉱夫をこんなに早く見つけられてよかったな。それとも自分でやったのか? どちらにせよ、よくやった。これはthreadにぴったりだ。\n\n品を作るには少し時間がかかるから、また来てもらわないとな――実はこいつは、塔に閉じ込めてある姫君のところへ送るんだ。彼女の唯一の仕事はgold threadを紡ぐことでね……いや、本当だとも。本気で言っている……まあ、そうでもないが。", 0x7fee9266, 0x16a84461, 0x54d5ef6e, 0x024ea4f3, 0x476cbcd4, "....." },
  [4782] = { "Enchanted Gold Bloodrobeの材料", "BarrensのMenara Voidrenderのところへ戻って下さい。", "Menaraのところへ戻って、少し時間はかかるけど、彼女のために……それと君のために、必ずやり遂げるって伝えてくれ。残りの材料を集め終えるよう君に言ってもらうといい――その頃には糸もできてるはずだ。そしたら戻ってきて受け取ってくれ。\n\n幸運を、{name}。ああ、それと、向こうに行ったらStrahadによろしく言っといてくれ。あの老いぼれめ……Ratchetのすぐ隣に塔なんか建てやがって……いかれてるよ。", nil, "よく戻りました、{name}。それで、糸はどこですか?\n\nああ、分かりました。それなら構いません。あのゴブリンと彼の兄弟がこれまで私たちの期待を裏切ったことはありません――その時に準備ができていなかったのも無理はないでしょう。仕方ありませんね……その間に取りかかれることはほかにもあります。\n\n次の段階へ進む準備はできていますか?", 0x7fee9266, 0xb874296f, 0xe71c1200, nil, 0xce0868a5, "...m." },
  [4783] = { "Enchanted Gold Bloodrobeの材料", "Vial of Hatefury Blood 10本とLesser Infernal Stone 1個をBarrensのMenara Voidrenderに渡して下さい。", "次の材料はDesolaceにある。Barrensのはるか西、Stonetalon Mountainsよりもさらに向こうだ。\n\nそこではSunderingの後、今も混沌が支配している。お前の力と狡猾さの両方が試されるだろう――憎しみの生き物、そしてBurning Legionの生き物と対峙することになる。\n\n北東にいるHatefury satyrから、その血を持ってこい。Mannoroc Covenにいるlesser infernalsから、lesser infernal stoneを持ってこい。\n\nその両方を、お前のローブを作るのに使う。", "Desolaceは優しい土地じゃない。naga、巨人、satyr、Burning Legion……それに争い合うcentaurの氏族たち、そのすべてが、用心しなければこの地を危険なものにしている。\n\n前にも言ったとおり、あの地では力と知恵だけでなく、忍耐も試される。あの地では用心するんだ、{name}。", "素晴らしいわ、{name}。とても状態がいい。残り二つの材料を取りに行っている間に、準備を進めておくわね。用意はいい?", 0x7fee9266, 0xfd7ed7f0, 0x055bed5e, 0x9a052ff2, 0xfb7327df, "....." },
  [4784] = { "Enchanted Gold Bloodrobeの材料", "Fine Gold Thread・Smoldering Coal 2個・Soul Shard 一個をBarrensのMenara Voidrenderに渡して下さい。", "あと必要なものは3つだけだ、{name}。そうすればお前のローブを仕上げられる。\n\nまず、Xizkがお前のために作っているfine gold threadだ。Booty Bayの彼のところへ戻って受け取ってこい。\n\n次に、Arathi Highlandsの炎のエレメンタルから、smoldering coalsを2個持ってこい。私の記憶が正しければ、奴らは西の、Thoradin's Wallの近くにいる。\n\n最後に、お前自身が作ったsoul shardだ。\n\n材料がすべて揃ったら、この塔に戻ってこい。ローブを仕上げてやろう。", "もうすぐだ、{name}。約束しよう。そのローブは君の必要を満たして余りあるし、きっと敵に対して優位に立たせてくれるはずだ。", "見事だ、{name}! 材料は揃い、準備は整った。\n\nきっと満足してもらえるはずだ。", 0x7fee9266, 0x57678e6a, 0x01e0638a, 0x10b8afc4, 0x33387de3, "....." },
  [4786] = { "完成したローブ", "Menara Voidrenderがローブを作り終えるのを待ち、もう一度話しかけて下さい。", "これからローブを作るわね。ほんの少ししか時間はかからないわ。遠くへ行かないで。", "少し待ってくれ、{name}……", "完成したぞ、{name}。ほら、これだ。誇りを持って身につけるがいい。\n\n君はよく励んだ。君の未来には大きなものが見える。忘れるな、我々の道に伴う腐敗に抗うには、強い意志と不屈の精神が要る。意志が自分のものであり続ける限り、君は大きな成功を収めるだろう。", 0x6458d4ea, 0x1f58f886, 0xac1a561e, 0x5118b45f, 0x7b3d8bf4, "....." },
  [4787] = { "Ancient Egg", "TanarisのYeh'kinyaにAncient Eggを渡して下さい。", "Prophecy of Mosh'aruは、ancient eggについて語っている。それはトロールが広大な帝国を支配していた時代の遺物で、Hakkarの本質を封じ込める力を持っている。Hakkarの悪から我々の世界を守る唯一の手段かもしれん。\n\nancient eggを持ってきてくれ、{name}。HinterlandsのJintha'Alorの奥深く、都の頂にある円形劇場の裏の洞窟に隠されているという。", "ancient eggは持っているか? 大いなる力がうごめいているのを感じる。残された時間は少ないのではないかと恐れているのだ。", "ああ、卵を持ってきたのだな! お前さんには頭が下がる、{name}よ。その力と勇敢さをずっと忘れないだろう。", 0x145cd452, 0x848c5ffa, 0x907bfabd, 0xec9c0814, 0x7bde200a, "....." },
  [4788] = { "最後の石板", "TanarisのProspector IronbootにFifth Mosh'aru TabletとSixth Mosh'aru Tabletを渡して下さい。", "私がMosh'aruの三枚目と四枚目の石板を調べている間に、お前は五枚目と六枚目を見つけてくれ! 容易ではないぞ。それらはBlackrock SpireにいるSmolderthornのトロールたちが持っているのだ。その尖塔は、Burning SteppesとSearing Gorgeの間にある、炎の暗い山だ。\n\n幸運を、{name}。Blackrock Spireはまっとうな者の行く所ではない……", "Spireには行ってきたか、{name}? 五枚目と六枚目の石板は持っているか?", "信じられん! 見つけたのか! 君は本物の英雄だ、{name}!\n\nそれは幸いだ。というのも、前に持ってきてくれたtabletsを読み進めていてな、そこから分かったことからすると……来たるものを食い止めるには英雄が必要になる……", 0x987997a3, 0xc9b97742, 0xef778150, 0x4a4945d3, 0x7b123b86, "....." },
  [4808] = { "Felnok Steelspring", "WinterspringのEverlookにいるFelnok SteelspringにTinkee's Letterを渡して下さい。", "もう一つ頼みたいことがあるんだ。\n\n君が集めた本質を最初に調べてみたら、dragon whelpの卵を凍らせて保存できるかもしれないって分かったんだ! この理論を試したいんだけど、まずは特別に作られたエンジニアリングの部品が要る。同僚のFelnok Steelspringなら作れるんだ。\n\nほら、この手紙をFelnokに届けて。何が要るか書いてあるから。FelnokはWinterspringの、Everlookの町にいるよ。", "ここは寒いよ! 毛布を持ってきてくれてるといいんだけど!", "そいつは毛布じゃないぞ! だが、これは何だ? Tinkeeからのletterか? 何を書いているんだろうな……\n\nああ、彼女はBurning Steppesで研究しているのか。なるほど――あそこはdragonkinの宝庫だからな。おっと、見ろ! 作りたい装置のために部品が必要だと書いてある。そこで俺の出番というわけか?", 0xd723b278, 0xcf66a2d3, 0xed2e16a1, 0x42eb722b, 0x96652015, "....." },
  [4809] = { "Chillwind Horns", "Uncracked Chillwind Horn 8本をFelnok Steelspringに持って行って下さい。", "Tinkeeが必要なもののほとんどはあるんだけど、大事な部品が一つ足りないんだ。それがchillwind hornsさ。Winterspringのchillwind chimaeraの角は冷気が凝縮された源なんだけど、傷のない、ひびの入っていない角じゃなきゃだめなんだ! Tinkeeの注文を仕上げるには、それがたくさん要るんだよ。\n\nuncracked chillwind hornsを持ってきてくれたら、Tinkee宛ての荷物を用意するよ。", "chillwind hornsは持っているか、{name}?", "これはいいサンプルだ。冷気で覆われてる! グローブをつけさせてくれ、Tinkeeに必要な他の物と一緒に包んでやらなきゃ……。", 0x57866406, 0xd3c65a4c, 0x2d4d46d9, 0x49da01ef, 0xe51c3160, "....." },
  [4810] = { "Tinkeeのもとへ", "Burning SteppesのTinkee Steamboilに、Felnok's Packageを渡して下さい。", "よし、全部荷造りして運ぶ準備ができた! あんたの旅の幸運を祈るよ。あと、Tinkeeにはオレに借りがあるってことを忘れずに言っといてくれよな!", "{name}! Felnokとは話した? 僕に必要な部品は持ってきてくれた?", "持ってきてくれたんだね! すごい! すぐに取りかかるよ! 本当にありがとう、{name}!\n\n君にはずいぶん助けられている。あとでもっと大事な仕事を頼むことになるかもしれないな……", 0x613a4bee, 0xd63de51b, 0x4015e85f, 0xb1d0a031, 0x69656083, "....." },
  [4811] = { "赤い水晶", "Auberdineの東へ向かい、Darkshoreの東の山脈沿いにある大きな赤い水晶を探す。見つけたものをAuberdineのSentinel Glynda Nal'Sheaに報告する。", "東では、敵意を持ったmoonkinがますます数を増してうろついています。かつては穏やかで、神秘的とさえ言える生き物だと思われていました。今も彼らを敬う者はいますが、Auberdineの安全のために、私はもっと現実的な見方をせざるを得ないのです。\n\nmoonkinが、Darkshoreの東の山脈沿いにある大きな赤い水晶に引き寄せられているという報告を受けています。その水晶が何なのか、本当に存在するのかさえ、誰にも分かりません。そこへ行ってそれを見つけ、何が見つかったか私に報告してください。", "あの赤い水晶について、何か報告することはあるか? そもそも本当に存在するのか?", "では水晶は実在したのですね、{name}？ 興味深い……ともかく、あなたの任務は見事に果たされました。よくやってくれました！\n\nこの水晶はいったい何なのでしょう？ これは疑問の海に浮かぶ、ただ一つの疑問にすぎません。もう一つ思い浮かぶ疑問は、なぜmoonkinがこの物体に引き寄せられるのか、ということです。この水晶は本来無害なものなのか、それとももっと邪悪な目的を秘めているのか？\n\n疑問はまだまだありますが、答えを得るにはあの水晶を詳しく調べる必要があるでしょう。", 0x5ae7f813, 0x8d4ec0d3, 0x69995f12, 0x84875e53, 0xe63afa83, "....." },
  [4812] = { "水が流れ落ちるように", "Auberdineの月の泉でEmpty Water Tubeを満たし、Darkshoreの東の山壁沿いにある赤い水晶を調べる。", "この空の小瓶を使って、ここAuberdineで月の泉の水を汲んでください。あれほど強い魔力なら、水晶の組成について手がかりを与えてくれるはずです。そのためには、その液体を水晶に注いでください。後はそれがやってくれるでしょう。\n\nあなたに悪いことが起きるとは思っていませんが、それでも気をつけてください。私たちの上、東にはFelwoodがあります。私が疑っている通りにあの水晶があの地と結びついているなら、とても危険なものかもしれません。", "Darkshoreの森の景色の中で、その水晶はひどく異質に見える。その奥深くから、ごくかすかなうなりが聞こえてくるような気がする。", "あなたは再びあの謎の水晶のもとへたどり着いた。moonwellの水が入ったtubeの栓を外し、中身をそっと水晶の上に注ぐ。水がその格子を伝って流れ落ちると、不透明だった表面が透き通っていくのが見える……", 0xdefb4541, 0xe834c2df, 0x29e90dd5, 0xb62a1acf, 0x9b8b44cb, "....." },
  [4813] = { "内なる破片", "見つけたことをAuberdineのSentinel Glynda Nal'Sheaに報告する。", "月の泉の水によって、水晶の中に小さな骨のかけらがいくつかと、顎の骨の半分が埋まっていることが明らかになった。顎の骨は人型の生き物のもののようだが、水晶を割って開けなければはっきりしない――それは最も強い魔法をもってしてもほとんど不可能な業だ。\n\n目の前の仕事は済んだ。残るは、AuberdineのSentinel Glynda Nal'Sheaに報告することだけだ。", nil, "どうやら、この水晶について分かったことは増えたのに、結果として答えの出ない疑問がさらに増えてしまったようですね！\n\nあなたが明らかにした情報は、ここAuberdineの評議会に持っていきます。この水晶についてどう対処すべきか、彼らなら分かるかもしれません。まあ、取るべき手があるなら、ですが。今のところ、脅威は私たちの東の遠く離れた所にあり、害が及ぶことはありません。\n\nあなたには、これを受け取ってほしいのです。見事な仕事への報酬だと思ってください、{name}。", 0xb84b9e71, 0x336ce815, 0x1453b5e8, nil, 0xd3015ad0, "...m." },
  [4821] = { "Alien Egg", "Alien EggをFreewind PostのHagar Lightninghoofのところへ持ち帰って下さい。", "Thousand Needlesのこの辺りでalien eggの噂が広まってる。その卵を見たという者たちも、つぶさにそれを調べられるほど近くに寄ることさえできないんだ。自分の卵みたいにして蛇がその卵を守ってるんだよ。\n\n私がその卵を調べられるよう、見つけて持ってきてほしい。報告によると、卵は蛇の巣の中にあるらしい。ただ、いくつかの蛇の巣がFreewind Postの北東と南の岩壁沿いにある。", "この謎のeggについて、もっと知らねばならない。そこから何が孵るか分からないのだから。", "やったぞ、ついに……謎を秘めた卵がついに手元にきたんだ。さてと、もう少し近くで見てみようじゃないか……。何だ……! 何だこれは……?", 0x3030ce44, 0x472a0b24, 0x6e429e9a, 0x5cb94efa, 0xfb1826a4, "....." },
  [4822] = { "ユースクリーム、アイスクリーム……", "Strawberry Ice Creamを孤児に買ってあげて下さい。その子はTigule's brand ice creamが好きなようです。", "アイスクリーム！ ねえお願いお願いお願い、アイスクリームを持ってきてくれない？！ いちごが一番好きな味なんだ。それに、Tigule's Strawberry Ice Creamよりおいしいいちごアイスなんて世界中どこにもないんだから！ 世界で一番大好きなアイスクリームなんだよ！\n\nずっと前にShimmering Flatsのレース場にいた時に一度だけ食べたんだけど、今は町で売ってるかもしれないって聞いたんだ！ お願い？ ほんとにお願い？ てっぺんにTigule's Strawberry Ice Creamをのせてあげるから？？！？！", "いちご以外のアイスクリームの味も作ってくれたらいいのに。でも、いちごが一番好きだから、ラッキーだったのかな!", "んんーっ! ここのイチゴのアイスクリーム大好き! TiguleとFororに得意なことが一つあるとしたら、それはアイスクリーム作りだね!\n\n本当にありがとう{name}――こんなに素敵なおやつは初めてだよ!", 0xa1977492, 0xb0828d78, 0xd500c0de, 0xf1f00363, 0x51094ed8, "....." },
  [4841] = { "Centaurを制圧せよ", "Galak Scoutを12人、Galak Wranglerを10人、Galak Windchaserを6人殺し、Freewind PostにいるCliffwatcher Longhornのところへ戻って下さい。", "{name}お願いだ、あのcentaurどもを追い詰めてくれ。復讐の怒りを感じさせねばならん。Freewind Postの北へ行き、centaur野営地を攻撃してくれ! 怒りに任せて叩きのめしてやれ!", "さあ、{name}、まだ自分の分を倒していないのは分かっている。奴らを狩り尽くしてくれれば、感謝の印として報酬を与えよう。", "私からの感謝として、これを君に。{name}。", 0x1d435eac, 0xb4351619, 0x27f17b09, 0x9319ff75, 0x8bb40c71, "....." },
  [4842] = { "奇妙な源", "Donova Snowdenの指示に従い、折り返し報告して下さい。", "正直に言うと、ここWinterspringには火山がないのに、この温泉にはもっとずっと不穏な理由があると私は考えています……\n\nまあ、ご自分の目で確かめたいでしょう。Winterspringを端から端まで旅して、ずっと南の果てまで行く必要があります。空気が重く蒸し暑くなり、空が暗くなったら、私が温泉の源だと考えているものを見つけたことになります。\n\n見てきてください。戻ってきたら、きっと聞きたいことがたくさんあるはずです。", "泉の水には、とても奇妙な性質があるようです……それが何を意味するのか、まだ分かりません……", "そうです、Darkwhisper Gorgeにいる悪魔たち。この地がこうして影響を受けているのは、彼らの存在のせいだと私は考えています。私はここの温泉の観察を続けて、他に何か分かることがないか見てみるつもりです。\n\nDarkwhisper Gorgeのさらに奥へ進むつもりなら、もう少し強くなるまで待つことをお勧めします。", 0x770638b8, 0x09ab8759, 0x266e3272, 0xbdd0d69c, 0xa72387b6, "....." },
  [4861] = { "怒り狂うWildkin", "Winterspring南部で、Jaron Stoneshaperの壊された野営地と物資を見つけて下さい。", "やあ、若いの！Winterspringの南にある俺のキャンプから、血に飢えたwildkinどもに追い出されちまったんだ！まあ、wildkinが守ってた何かに近づきすぎたんだろうな。\n\nなんとか無事に逃げ出せたが、相棒の一人はそう運が良くなかったんじゃないかと心配でな。wildkinに立ち向かって、キャンプまで行ってもらえないか？どうしても物資が必要なんだ。それに、昨日発掘現場で掘り出したアミュレットも取り戻したいんだよ。", nil, "野営地の壊された持ち物の中で、ひどく損傷した木箱が一つ目を引く……", 0x79149705, 0x7441f7b9, 0x028c9c59, nil, 0x0236ad18, "...m.", nil, nil, 0xda8a0008, nil, nil },
  [4862] = { "き・た・な・い", "Blackrock Spireへ行き、KiblerのためにSpire Spider Eggsを$N1個集めて下さい。\n\n話からすると、この卵は蜘蛛の近くで見つかりそうだ。", "信じられないかもしれないが、この世にはどんなに邪悪な獣だろうと、飼い慣らされてさえいれば金を払うって連中がいるんだよ！\n\nBijouをSpireに送り込んでspire spider eggsを集めさせようとしたんだが、もう何週間も音沙汰がない。手を貸してくれないかね？\n\nこうしよう、{name}。Blackrock Spireに行って、spire spider eggsを集めてきてくれ。ここに持ち帰ってくれたら、ちょっとした金をやるだけじゃなく、1匹飼い慣らしてあんたにやるよ！", "あなたのカバンに入っているのはspider eggsかな? それとも単に私に会えて嬉しいだけかな?", "すごい量だ! いや、このeggsの山を見ろよ! こいつはかなりの金になるはずだ。\n\n約束通り、お前だけのちびすけだ。噛まれるなよ!", 0xbe9d4fa6, 0x9409929c, 0xcb2f6b38, 0xa23da4b7, 0xa14c937e, "....." },
  [4863] = { "怒り狂うWildkin", "Jaron Stoneshaperの壊れた荷馬車を見つける。", "見回しても、Jaronが欲しがりそうなものはここにはあまり見当たらない。しかし、見つけた木箱が叩き壊されて開いていることに気づく。まるでwildkinの狙いがこれだったかのようだ……\n\n東の方を見ると、打ち捨てられた荷馬車がかろうじて見える。そこならJaronの持ち物が見つかるかもしれない。調べてみる価値はある。", nil, "荷馬車に近づいてみると、Jaronのために残っているものはもうあまりないようだ。だが地面を見ると、雪に半ば埋もれているにもかかわらず、無傷に見える木箱がいくつかあることに気づく。", 0x79149705, 0xca1fe111, 0x3baac11d, nil, 0xbd4184d1, "...m." },
  [4864] = { "怒り狂うWildkin", "雪の中からJaron's Suppliesを拾い、Jaronが話していたアミュレットを盗んだwildkinを見つける。\n\nJaron's SuppliesとBlue-feathered AmuletをWinterspringの山小屋にいるJaron Stoneshaperのところへ持って行って下さい。", "箱の中身を調べたあなたは、中の道具やその他の品がJaronの役に立つだろうと判断する。しかし、アミュレットは影も形もない。\n\nwildkinはここから北と東の土地に棲んでいるようなので、次は奴らに立ち向かい、アミュレットを取り返すことにする。", "ああ……知らせを聞かせてくれ。", "まあ、そんなところだろうと思っとったよ、若いの。あの狂った獣どもがわしの持ち物を全部壊してしまったんだろうとな……\n\nだが、わしの道具と、何より大事なamuletを見つけてくれた！ なぜwildkinがこの品をあれほど激しく守っていたのか……ともかく、次にあいつらの所へ向かう前には、よく考えることにするよ！", 0x79149705, 0x4e5f6f02, 0x713e526e, 0x18bc5c8b, 0x775c972b, ".....", nil, nil, nil, nil, 0x41d708bc },
  [4865] = { "蛇の怒り", "あなたの発見をMotega Firemaneに報告して下さい。", "この目で見なかったら、これが本当のことだと信じなかっただろうな。Thousand Needlesに復讐が訪れるぞ!\n\n<Hagarは額をぬぐった。>\n\n{name}、迅速に動かねばならん! 今すぐMotega Firemaneを探してくれ。彼はFreewind Postの北西、Whitereach Postの道沿いにいる。何をすべきか彼なら知っているだろう!", nil, "復讐だと! それじゃ、Arikaraの伝説は本当だったのか。確かに、この問題はすぐさま解決しなければならないな。", 0x612f028d, 0xc8e5a036, 0x7e5035fc, nil, 0x1fdaed2a, "...m." },
  [4866] = { "母乳", "Blackrock Spireの中心にMother Smolderwebがいます。Mother Smolderwebと交戦して毒を受けて下さい。また、Mother Smolderwebを殺さねばならない可能性は大きいでしょう。Ragged Johnが「搾り取れる」よう、毒を受けたら彼の元へ戻って下さい。", "たぶん世界で最も強力な毒の一つだよ、{race}！\n\nSpireに潜り込んだ時に、Blackrockの連中がその致死性について話してるのを耳にしたんだ。連中はそれを'Mother's Milk'と呼んでる。Skitterwebの洞窟にいるでかくて厄介な蜘蛛、Mother Smolderwebにちなんだ名前さ。\n\nさて、あんたに頼みたいのはこれだ。Milkの生きたサンプルを、あんた自身の血管に流した状態で持ってきてほしい。毒腺を持ってくるだけじゃ駄目なんだ！ あいつに毒を食らわせてもらって、戻ってきてくれ！\n\nそしたら……俺があんたから搾り取るってわけだ！\n\n<期待に両手をこすり合わせる。>", "<Ragged Johnがあなたをつねる。>", "これで今までで最高のエールができるぞ!\n\nおいおい、これを何に使うと思っていたんだ? 毒か何かか??\n\nまったく、今どきの若いのは……", 0x92128101, 0x55e77086, 0x235114fa, 0x65d131a5, 0x3b930086, "....." },
  [4867] = { "Urok Doomhowl", "Warosh's Scrollを読んで下さい。WaroshにWarosh's Mojoを渡して下さい。", "ぐっ！ 話すの、すごく難しい！\n\nこのメモを持っていけ！ 俺のmojoを取ってこい！", "おお! 俺のmojoを持ってきたか?", "アハ! すでに力が戻ってくるのを感じる。それに、我が心はもはやUrokの呪いに苛まれてはいない。\n\n感謝する、{name}! 謙遜など我には似合わぬが、そなたの助力は認めねばなるまい。\n\nそしてBlackrock Spireの旅に幸運があらんことを。頂上まで辿り着けると思うとは愚かなことだが、そなたの勇気は疑いようもない。", 0xf56d6e8c, 0x77f6dbd8, 0xe3f54a7e, 0xe79ceef2, 0xca23224d, "....." },
  [4881] = { "暗殺計画", "Whitereach PostのKanati Greycloudに暗殺計画を知らせて下さい。", "トーレンのKanati GreycloudはふてぶてしくもThousand Needlesに狩猟キャンプを設営した。我々はそのキャンプとKanatiに従う者すべてを駆逐すべく、Kanatiを殺さねばならない。Great Liftの南西にある小さな基地に集結する予定である。", nil, "俺を殺しに来るだと? 奴らにトーレンがどう戦うか見せつけてやろうじゃないか!", 0xc85dbd6e, 0x9ca08705, 0x1c5ff84a, nil, 0x4f9dc751, "...m." },
  [4882] = { "秘密の守護", "Bloodvenom PostのTrull FailbaneにBlue-feathered Necklaceを渡して下さい。", "最近倒したwildkinの首から落ちた首飾りに何の意味があるのか、あなたには分からない。それは明るく輝き、ゆっくりと明滅している。\n\nTrull Failbaneならもっと詳しく教えてくれるかもしれない。wildkinについての彼の知識は豊富なようだ。彼に聞いてみるべきだろう。", "次の任務に就きに来たのか?", "重要な発見?", 0xb324739d, 0x5378112c, 0x363bbfd4, 0x85113514, 0x06fa0b6f, "....." },
  [4883] = { "秘密の守護", "Blue-feathered NecklaceをNara Wildmaneに渡して下さい。", "Winterspringであなたが倒したowlbeastについてはかなりの知識があるが、奴らが使う魔法については詳しくない。だが、首飾りを調べて、おそらくそれが何なのかを教えられる者を一人知っていると思う。\n\nThunder BluffのNara Wildmaneがこの分野の専門家だ。彼女に会うといい。幸運を、{name}。", "何かご用ですか、{name}?", "このnecklaceのエネルギーですね、{name}。その源はただ1つだけだと私は考えています。\n\n<Naraは目を閉じ、しばらく黙り込む。>\n\nwildkinは、今でこそ道を見失い混乱していますが、かつてはそうではありませんでした。彼らにはかつて目的があり、仕えるべく導かれていたのです。ナイトエルフの女神Eluneが、最も神聖な場所を守らせるためにこの生き物たちを創り出しました。\n\nこの事実はほとんど価値がないように思えるかもしれませんが、もっと深く見つめてみてください。\n\nいずれ分かるでしょう。これを持ってきてくれてありがとう、{name}。", 0xb324739d, 0xb360f381, 0xc9511183, 0x12fea955, 0xfda5700f, "....." },
  [4901] = { "祭壇の守護者", "RanshallaがAltar of Eluneを再び起動させる間、彼女を守る。わかったことをRut'theran VillageのErelas Amberskyに報告して下さい。", "尾根のいちばん上には、女神Eluneの祭壇だと私が考えているものがあります。私に分かる限りでは、それぞれの洞窟にある五つの松明に火を灯せば、祭壇へ直接行けるようになるはずです。\n\nKel'Therilの古代遺跡の石に刻まれていた呪文をいくつか書き写しました。これが祭壇を開く秘密だと思うのです。私が呪文を唱えている間に、あなたにはそれぞれの松明に火を灯すのを手伝っていただきたいのです。\n\nうまくいけば、私たちの発見をErelasに報告できますよ！", nil, "Ranshallaには会えましたか？", 0x9acf7bfb, 0xb5a7b357, 0xc65f04b8, nil, 0xf1e2455b, "...m." },
  [4902] = { "EluneのWildkin", "DarnassusのArch Druid Fandral Staghelmと話して下さい。", "なんて興味深いのでしょう！\n\nずっと真相が気になっていたのです……ええ、この知識は必ず伝えなければなりません！今すぐArch Druid Fandral Staghelmのもとへ行ってください。DarnassusのCenarion Circleにいらっしゃいます。何が起きたのか、私に話してくれたのと同じように説明してください。きっと私と同じくらい興味を持たれるはずです！\n\nこれは重要な情報ですよ、{name}！", nil, "ためらうな。何のために来たのか申してみよ。\n\nほう？ ふむ。なるほど。\n\nこれをまっすぐ我のもとへ持ってきてくれたことに感謝する。常に頂点へ直接来るのが最善だからな……だが……そう。Cenarion Circleのドルイドたちは、以前からWildkinのことを知っていた。彼らがEluneの愛し子であり、最も神聖な場所を守るよう選ばれたということもな。\n\nゆえにこれは目新しい話ではないが、そなたの努力は大いに称えよう。さあ、これを受け取るがよい。このような行いにふさわしい品であろう。", 0x1fa3452e, 0xf466e7fe, 0xd56e78fc, nil, 0x14e16654, "...m." },
  [4903] = { "大将軍の指令", "Highlord Omokk・War Master Voone・Overlord Wyrmthalakを討ち取って下さい。Important Blackrock Documentsを取り戻し、任務を完了する際にKargathのWarlord Goretoothに返して下さい。", "Warlord Goretoothの命により、Blackrock Spireに住む以下の者たちを抹殺せよ。\n\n丸々と太った脅威、Highlord Omokk。\n\n冷酷非情なトロール、War Master Voone。\n\n下層都市の監督官、Overlord Wyrmthalak。\n\nまた、見つけた重要な書類はすべて持ち帰ること。\n\n成功すれば栄誉を。\n\n失敗すれば忘却を。", "<Warlord Goretoothが敬礼する。>", "<Warlord Goretoothのくすんだ緑色の肌が、一瞬で青ざめた。>", 0x74e9f805, 0xcfacba72, 0x1625864e, 0x31f0b738, 0x989eb15a, "....." },
  [4904] = { "ついに自由", "Darkcloud PinnacleからLakota Windsongを護衛し、Freewind PostのThalia Amberhideと話して下さい。", "Arnakは私が彼と結婚すると思っています……でも、申し出を断ったその夜、彼は戻ってきて私をさらったのです。私の兄弟が止めようとしたのですが、Arnakは強すぎました。彼は……彼は兄弟を殺し、私をここまで連れてきたのです。可哀想に……。\n\n{name}、Darkcloud Pinnacleから連れ出してくれませんか? お願いします……。私はThaliaのところへ戻らねば! 彼女はひどく心配しているに違いありません。", nil, "ありがとう、{name}。Lakotaが私のところへたどり着くであろうことは、身に沁みるほどよく分かっていました。あなたの勇敢さ、あなたがいかに逃亡の手助けをしてくれたか、彼女は話してくれました。この品は彼女の兄弟のものです。これをあなたに持っていて欲しいと望んでいるはずですよ。", 0x1ba438b0, 0xcbafa782, 0xeb06eed1, nil, 0xf5fd9df3, "...m." },
  [4906] = { "さらなる堕落", "FelwoodのEridan Bluewindは、Jadefire Hellcallersを$N1体、Jadefire Betrayersを$N2体、Jadefire Trickstersを$N3体、そしてXavaricを倒してほしいと言っています。任務を終えたらEridanのところへ戻って下さい。", "二つ目のsatyrの野営地が、冷酷なXavaricに率いられて、北の方でFelwoodの地を脅かしています。あの邪悪な裏切り者にしてペテン師どもは、Felwoodに生まれた生き物たちの腐敗を糧にしているのです。\n\nXavathrasとその手下は、より大きな計画の一部にすぎませんでした――腐敗したmoonwellを育て、その戦利品をXavaricに差し出すという計画の。\n\nXavathrasが片付いた今、この仕事を最後までやり遂げてください、{name}。北へ向かい、Xavaricを倒すのです。", "どうか、Felwoodの生き物たちの苦しみを終わらせてください。", "これまでのすべてに感謝します、{name}。Eluneがあなたを守り、この先の道を導いてくださいますように。", 0x55f5548e, 0x188808e3, 0x5c753791, 0x861c4d72, 0x12182e6d, "....." },
  [4907] = { "Tinkee Steamboil", "Tinkee Steamboilと話して下さい。", "やあ、{name}。Tinkee Steamboilを覚えてるかい？ 彼女の方はあんたを覚えてるよ！ あんたを見かけたら知らせてくれって伝言をよこしたんだ。だって……彼女、またあんたの助けが必要なんだってさ。ドラゴンの研究と何か関係があるんだと思うよ。\n\nBurning SteppesのFlame Crestにいる彼女に話しかけるといい。", nil, "Felnokの言った通りだ! またしても君の助けが必要でね。しかも今度は……本当に危険なことになる。\n\n覚悟はいいかい??", 0xb0872af6, 0x9d39dc7b, 0x7bf6730e, nil, 0x2a394db3, "...m." },
  [4921] = { "戦いに消ゆ", "Mankrik's wifeを見つけ、CrossroadsのMankrikのところへ戻って下さい。", "俺たち夫婦が離れ離れになったとき、トーレンの小さなキャンプで戦っていたんだ……妻はBristleback3頭を相手に持ちこたえていた。だが、別のがやってきて形勢は逆転し始めた。俺は何頭かに気を取られて、妻が助太刀にやられるのを見ているしかなかった。怒りにかられて俺は敵に向かったけれど、数に圧倒されていとも簡単に負けたんだ。\n\n目が覚めると、トーレンのドルイドが傷を治療してた……俺が倒れたとき、彼が偶然Gold Roadに通りかかったんだ。\n\nお願いだ、{class}。妻の痕跡を探してくれ。", "彼女の手がかりは少しでも見つかりましたか? 胸の痛みが最悪の事態が起きたと告げていますが、それでもあなたが彼女を無事に見つけてくれると望んでいます。", "分かった。ありがとう、{class}。", 0xac9b0a79, 0xf3b9fa6f, 0x129c3977, 0xa6107eba, 0xc0eb0cb6, "....." },
  [4941] = { "Eitriggの英知", "OrgrimmarのEitriggと話して下さい。Eitriggと問題について話し合ったら、Thrallに審議を求めて下さい。\n\nあなたはThrallの部屋でEitriggを見たことを思い出しました。", "Rendが生きている?\n\nありえん!\n\nRendは数十年前に殺害されたと考えられているんだ。\n\nEitriggの英知を求めろ、{name}。彼よりBlackrockの仕組みをよく知っている者はいない。そしてもしここに書かれているのがありのままの真実なら、Eitriggに知らせるべきだ。何人たりとも、復讐の権利を否定すべきではない。\n\nOrgrimmarに彼はいるだろう。\n\nEitriggと話したら、Warchiefと協議してくれ。Warchiefがこの問題に対して何をしたいのか、見つけ出すためにな。", "我の邪魔をしてはならぬことが分からぬのか?", "<Thrallはあなたのもたらした知らせに驚愕したようだった。>", 0x610a016f, 0x9f2039c3, 0xa6200170, 0x4cf1d215, 0x55dbcaa0, "....." },
  [4961] = { "Orb of Orahilの清め", "Demon of the Orbを殺し、Tabethaと話して下さい。", "ああ、召喚者の宝珠か――穢れはここから来ているに違いない。これを使うつもりなら、中に潜む悪魔を祓わねばならん。それなら私には造作もないことだ。\n\n厄介な仕事をするのはお前の方だ。私が解き放った悪魔を、お前が倒さねばならん。\n\nそれに素早くやらねばならんぞ。時間をかけすぎれば奴は宝珠に戻ってしまい、最初からやり直しになる！\n\nだから準備を整えろ、{name}。最も強力な呪文を用意し、薬はすぐ使えるようにしておけ。友がいるなら連れて来い。生易しいものにはならんからな。", "オーブからその存在を永久に取り除くには、あの悪魔を倒さねばならない、{name}。", "よくやった、{name}! あの悪魔に、当分忘れられない教訓をくれてやったな。君は大きな力と技を見せてくれた。さて、清められたorbを持ってMenaraのところへ戻り、それを役立てる時だろう。\n\n幸運を、{class}。またどこかで道が交わるかもしれないな。", 0xa2af51d8, 0x0c09dbd7, 0xef1d65ce, 0x2aeacd11, 0x36989af8, "....." },
  [4962] = { "Felhoundの破片", "Felhas Rubyを持っていき、DesolaceにいるFelhoundに使って下さい。成功した後、Felhas RubyとImprisoned Felhound SpiritをBarrensのMenara Voidrenderのところへ持ち帰って下さい。", "そうか、felhoundの魂を捕らえることを選んだか。よろしい。\n\nこのルビーを持っていけ――これがあれば、その生き物の魂を捕らえられる。お前がすでに知っている呪文とよく似た働きをする。生き物が死にかけたら宝石を使え。あとはそれがやってくれるはずだ。\n\nDesolaceへ行き、そこにいるfelhoundで腕試しをするのがよかろう。あれならうってつけだ。\n\n成功したら、捕らえた魂とルビーを両方ともMenaraのところへ持っていけ。", "何だ、{name}? 決めたか? Infernalか、felhoundか?\n\nどちらを選ぶかは個人の問題で、自分の長所と短所を反映すべきだ。ウォーロックが足りない部分を補うのではなく、自分をさらに高めることも珍しくはない。敵を力で圧倒することは、より均衡の取れた呪文使いになるのと同じくらい強力な戦術になることもある。", "ああ、felhoundのspiritだな。よくやった、{name}。\n\nspiritと清められたorbの両方が揃ったら、その2つを君のために融合させよう。だが、それまでは駄目だ。", 0xcac8654f, 0xdbee1707, 0x3d24b7b3, 0x90161bdb, 0x9222e0a7, "....." },
  [4963] = { "Infernalの破片", "Infus Emeraldを持っていき、DesolaceにいるInfernalに使って下さい。成功した後、Infus EmeraldとImprisoned Infernal SpiritをBarrensのMenara Voidrenderのところへ持ち帰って下さい。", "そうか、infernalの魂を捕らえることを選んだか。よろしい。\n\nこのエメラルドを持っていけ――これがあれば、その生き物の魂を捕らえられる。お前がすでに知っている呪文とよく似た働きをする。生き物が死にかけたら宝石を使え。あとはそれがやってくれるはずだ。\n\nDesolaceへ行き、そこにいるinfernalで腕試しをするのがよかろう。あれならうってつけだ。\n\n成功したら、捕らえた魂とエメラルドを両方ともMenaraのところへ持っていけ。", "何だ、{name}? 決めたか? Infernalか、felhoundか?\n\nどちらを選ぶかは個人の問題で、自分の長所と短所を反映すべきだ。ウォーロックが足りない部分を補うのではなく、自分をさらに高めることも珍しくはない。敵を力で圧倒することは、より均衡の取れた呪文使いになるのと同じくらい強力な戦術になることもある。", "ああ、infernalのspiritだな。よくやった、{name}。\n\nspiritと清められたorbの両方が揃ったら、その2つを君のために融合させよう。だが、それまでは駄目だ。", 0x99d101f6, 0xc9a4d7b1, 0x14f7176a, 0x90161bdb, 0x614e3e45, "....." },
  [4964] = { "完成したOrb of Dar'Orahil", "Menara VoidrenderがOrb of Dar'Orahilを作り終えるのを待ち、もう一度話しかけて下さい。", "すぐにオーブ作りを始めて、新しい悪魔をこの中に入れてあげるわね。終わったら、杖とオーブとどちらの形で持ちたいか選んでちょうだいね。ウォーロックの選んだ武器を提供するのはとても大切なことだと、いつも思っているの……こういう習わしを続けない理由が分からないわ。", nil, "完成したぞ、{name}。どちらが好みか言ってくれるだけでいい。両手を使うことになる杖か、あるいは短剣や剣を武器として使えるようにorbか。\n\nfelhoundに挑んだのは君にとって大きな偉業だった。その品はきっと今後君の役に立つだろう。技の研鑽を続けてくれ、{name}。君の武勇伝の詳細を待っているぞ。", 0x0db266f4, 0xe3749851, 0x7c553bb6, nil, 0x34bb4f9e, "...m." },
  [4965] = { "Orb of Orahilの知識", "BarrensのMenara Voidrenderに話しかけて下さい。", "ほう、ほう、ほう……力を増しているようで何よりだ、{name}。そろそろBarrensのMenara Voidrenderと話す頃合いだろう。まだ彼女と話したことがないなら言っておくが、悪魔でさえいとも簡単に閉じ込めて我々の意のままに仕えさせる品――とりわけ宝珠――を作ることにかけて、彼女ほどの専門家には会ったことがないと思う。\n\n興味があるなら、彼女はBarrensのRatchetの上にあるStrahadの塔にいる。", nil, "ああ、君はより……実体のあるものを求めているのだな。君が本当に備えているなら、それは手助けできる。\n\n我々のような者が、ただの知識以外の形でより大きな力を求めるのを見るのは、歓迎すべき変化だ。\n\nさて、準備はできていると思うか、{name}?", 0x1e06a5bc, 0xdd3a1725, 0xded3c63b, nil, 0xc0e51e95, "...m." },
  [4966] = { "Kanati Greycloudを守れ", "centaurの攻撃からKanati Greycloudを守って下さい。", "しかし、考えているよりもずっと多いcentaurが来るだろうな。{name}、俺と一緒に卑怯な暗殺者どもと戦ってほしい。", nil, "助太刀に感謝するよ、{name}。君無しに奴らを撃退することはできなかったよ。", 0x87ee9084, 0xb8578399, 0x907deac5, nil, 0xfb6cc9e7, "...m." },
  [4967] = { "Orb of Orahilの知識", "BarrensのMenara Voidrenderに話しかけて下さい。", "相変わらずの愚か者め、相変わらず定命の者の飾りを追い求めおって。そうだ、我は傲慢さをもってお前に語っている。目の前のお前を見ると笑いがこみ上げる。哀れな奴よ！\n\nだが我がどう思おうと関係ない。重要なのは、お前と取引しようという者たちがどう思うかだ！ そしてこの場合、我の良識に反して、多少なりとも力を持つ者たちは、お前がもっと多くを得るに値すると考えておる。\n\nそれを望むのなら、Ratchetの上の塔にいるMenara Voidrenderと話すがよい。以前にも会ったことがあるはずだ。", nil, "ああ、君はより……実体のあるものを求めているのだな。君が本当に備えているなら、それは手助けできる。\n\n我々のような者が、ただの知識以外の形でより大きな力を求めるのを見るのは、歓迎すべき変化だ。\n\nさて、準備はできていると思うか、{name}?", 0x1e06a5bc, 0xdd3a1725, 0xabcb7e15, nil, 0xc0e51e95, "...m." },
  [4968] = { "Orb of Orahilの知識", "BarrensのMenara Voidrenderに話しかけて下さい。", "ふむ、ここまで来たか……実に驚きだ。秘術の力を操る堕落が魂の奥底まで染み込み、とうにお前を狂わせていると思っていたのだがな。ではさらに先へ押し進めてみようか？\n\n腕を試したいなら、RatchetのStrahadの塔の上にいるMenara Voidrenderを探せ。彼女が導いてくれるだろう。", nil, "ああ、君はより……実体のあるものを求めているのだな。君が本当に備えているなら、それは手助けできる。\n\n我々のような者が、ただの知識以外の形でより大きな力を求めるのを見るのは、歓迎すべき変化だ。\n\nさて、準備はできていると思うか、{name}?", 0x1e06a5bc, 0xdd3a1725, 0x4b72c193, nil, 0xc0e51e95, "...m." },
  [4969] = { "Orb of Orahilの知識", "BarrensのMenara Voidrenderに話しかけて下さい。", "はっはっ！ なかなかうまくやっているな、若き{class}よ。\n\nいずれはinfernalやdreadlordもお前の前にひれ伏すだろう！\n\nだがその時が来るまでは、定命の種族の手で鍛えられた武器に頼らねばならん。\n\nまた新たな品を作る準備はできているようだな。その気があるなら、Menara Voidrenderが話をしたがっている！ 彼女は港町Ratchetを見下ろすStrahadの塔の近くにいる。準備ができたら行くがいい。", nil, "ああ、君はより……実体のあるものを求めているのだな。君が本当に備えているなら、私が手助けしよう。\n\n我々のような者が、ただの知識以外の形でより大きな力を求めるのを見るのは、歓迎すべき変化だ。\n\nさて、準備はできていると思うか、{name}?", 0x1e06a5bc, 0xdd3a1725, 0x4438376e, nil, 0x5ab9669e, "...m." },
  [4971] = { "時間の問題", "Andorhalのサイロのどれかの近くでTemporal Displacerを使い、Temporal Parasitesをあぶり出す。\n\nTemporal Parasitesを$N1体倒し、Western PlaguelandsのAndorhal InnにいるChromieのところへTemporal Displacerを返して下さい。", "何者か邪悪な力――おそらくはScourge――によって、Andorhalの時の流れがいじられてしまった！ここの時の流れを保ち、損なわれたものを修復することはできるが、邪魔されずにそれを行うにはあなたの助けがいる。\n\n時間の寄生虫――時の流れの歪みを糧とする腐肉あさりども――が、今やAndorhalのサイロにはびこっている。目に見える目印は、青い歪みの脈動だけだ。奴らのせいで私の占いが鈍ってしまう。どうか{name}、このtemporal displacerを使って寄生虫どもを根絶やしにしてほしい。", "Temporal parasitesは、時の流れが乱されたところならどこにでも現れる、ありふれた災いです。ここには多くの気配を感じます。これは憂慮すべきことです。\n\n見つけられるだけ根絶してくれれば、ここで悪化しつつある時の状況を、よりしっかりと掌握できるようになるでしょう。それが達成されたときは、私には感じ取れます。", "時を繕うのが幾分楽になった。礼を言うぞ、{name}。砕けた時の流れがもたらす結末を、そなたが完全に理解してはおらぬとしても、我がますますScourgeの仕業と疑うこの悪行に対抗せねばならぬという切迫を、そなたが解しているのはありがたいことだ。\n\nその助力に報いることに、何の差し支えもあるまい、定命の者よ。そなたの最も偉大な功績はこれから訪れるもの、飾り物をひとつ授けたところで、そなたの未来の運命が変わることはあるまい。だが、そなたの変わらぬ助けこそ、我と竜の一族が必要としているものなのだ……", 0xe492e2f3, 0xee534933, 0xdbab402f, 0x948b7dfe, 0x170199d3, "....." },
  [4972] = { "時を数えて", "街の瓦礫の中にある金庫からAndorhal Watchesを$N1個見つけ出す。それを持ってWestern PlaguelandsのAndorhal InnにいるChromieのところへ戻って下さい。", "この部屋の外にある世界に手を伸ばしてほしいの、{name}。説明させて。\n\nこの部屋が、Andorhalの他の場所とは違うのが分かるでしょう。私たちのドラゴンの眷属は、さまざまな方法で、さまざまな時間軸の中で働いているの。Andorhalの損傷を修復するため、私は今、別の時間軸から手を加えているのよ。この時間軸をあまり汚さないようにね。でも、これを続けるには、疫病が襲った時に閉じ込められた時の装飾品が必要なの。かつては誇り高かったこの町を形作る廃墟の建物の中にある、鍵付きの箱から見つけてきてちょうだい。", "私が求める時の小物は単純な道具です。主にwatchesで、その針は疫病が初めてAndorhalを襲ったときのまま、永遠に囚われています。\n\n時に終わりはありません。あなたが持ってきてくれるwatchesは、必ずや元の場所へと数え戻されることになるでしょう……つまり、ここでの乱れが続く限りは。", "これこそまさに必要なものです、{name}。ありがとう。\n\nこれをふさわしい報酬として贈らせてください。このような装置が何の役に立つのか、あなたには分からないかもしれません。これが本当は何なのかさえ、よく分からないかもしれません。残念ながら、いつ最も役に立つのかはお伝えできません。ただ、未来のある時点で、この品を使えば並外れた効用と働きを発揮すると知っておいてください。それまで持っておくかどうかは……友よ、あなた次第です。", 0x5df1aeae, 0x4c635c6d, 0x7f49c2ea, 0xbfad7074, 0x4441cc2e, "....." },
  [4974] = { "Hordeのために!", "Blackrock Spireへ行き、Warchief Rend Blackhandを討ち取って下さい。彼の首をOrgrimmarへ持ち帰って下さい。", "Rendがあれほど大それたことを言えるのは、黒竜の一族の庇護を受けているからだ。\n\n{name}、お前はHalls of Ascensionを抜ける道を見つけ出すのだ。そして'Warchief' Rend Blackhandを見つけ出し、奴を倒せ――HORDEのために！\n\n<Thrallが拳で玉座を叩く。>\n\n次にこの部屋に戻る時は、奴の首を勝利の証として高く掲げ、お前の大族長に差し出すのだ。これを成し遂げ、Hordeの英雄として称えられよ。", "<Thrallがうなる。>", "君はBlackrockの軍勢に壊滅的な一撃を与えた、{name}。大族長が討たれ、Blackrockの軍団は再び混沌の顎に投げ込まれた。\n\n君の英雄的な働きを讃えて、Kalimdorの民に報酬が与えられるだろう!", 0xcbedc0b0, 0xe788cadb, 0x91a3ffba, 0x51810db7, 0xe9f6f7cd, "....." },
  [4975] = { "完成したOrb of Noh'Orahil", "Menara VoidrenderがOrb of Noh'Orahilを作り終えるのを待ち、もう一度話しかけて下さい。", "すぐにオーブ作りを始めて、新しい悪魔をこの中に入れてあげるわね。終わったら、杖とオーブとどちらの形で持ちたいか選んでちょうだいね。ウォーロックの選んだ武器を提供するのはとても大切なことだと、いつも思っているの……こういう習わしを続けない理由が分からないわ。", nil, "完成したぞ、{name}。どちらが好みか言ってくれるだけでいい。両手を使うことになる杖か、あるいは短剣や剣を武器として使えるようにorbか。\n\ninfernalに挑んだのは君にとって大きな偉業であり、この報酬は君によく似合うだろう。技の道でのさらなる成功を願っている、{name}。", 0x2893fd72, 0xa83dbe16, 0x7c553bb6, nil, 0xa7b51784, "...m." },
  [4976] = { "清めた宝珠の返却", "BarrensのMenara VoidrenderにCleansed Infernal Orbを返して下さい。", "RatchetのMenaraのところへ清めたオーブを持ち帰ってちょうだい、{name}。彼女によろしくと伝えてね。そしてご無事で。あなたの進む道に必ずやってくる誘惑や堕落に耐えられるよう、心から願っているわ。頑張って。", "Tabethaとorbの捜索はどうだ、{name}?\n\nTabethaは秘術に関することではこの上なく頼りになる。見つけ出せれば、きっと喜んで力を貸してくれるだろう。", "よくやったわ、{name}。とても状態がいいわよ。やるべきことはあとひとつ、オーブの中にどちらの悪魔を封じ込めたいか決めるだけ。そうしたら、新しい最高の道具が手に入るのよ。", 0xa1f2e73c, 0x4d497ee2, 0x7b21dd71, 0x3e294480, 0x638e5fcd, "....." },
  [4981] = { "諜報員Bijou", "Blackrock Spireへ行き、Bijouに何が起きたのか突き止めて下さい。", "ゴブリンは決して信用するな。結局はそういうことだ、{name}。\n\n名前はBijou。我々の工作員の中でも一番とらえどころのない奴だ。奴はBurning Steppesから来たKiblerという怪しいエキゾチックペット商のために働いていたことが分かった。要するに、我々を裏切って二股をかけていたわけだ。さらに悪いことに、Hordeの資金を使って自分の活動をまかなっていた。\n\n奴を生きたままここへ連れ戻してほしい。\n\n最後に目撃されたのはBlackrock Spireへ入っていくところだ。奴を見つけて連れ戻せ。\n\nそれから、{name}、奴の甘い言葉に乗せられるなよ。", nil, "嘘はつかないわ、{race}。お金が必要だったの! Kiblerはとても、とても払いがいいのよ。K.E.F.なんかよりずっとね。\n\nでも、私の忠誠を疑わないで! 私がなぜこんなところにいると思う? あのイカれたゴブリンのために、珍しい動物の卵か何か、同じくらいくだらない物を取ってくるため? まさか。ペットを集めにBlackrock Spireまで来るなんて、本物の大馬鹿くらいのものよ。ええ、そんな人がこの世にそう大勢いるとは思えないわ。\n\n<Bijouは笑う。>\n\nそういう連中が増えることだけは、一番ごめんだわ。", 0xe4e02c06, 0x1c554da3, 0x1a593ac0, nil, 0x28659457, "...m." },
  [4982] = { "Bijou's Belongings", "Bijou's Belongingsを見つけて彼女に返して下さい。彼女は、この都市の最下層に荷物を隠したと言っていたことをあなたは思い出しました。", "夜、ここの警備が手薄になると、街をこっそり歩き回って、K.E.F.にとって戦略的な価値がありそうなものを見つけたら何でも書き留めてるんだ。\n\nところが昨夜、とんでもないことになった。仕掛け線に引っかかって警報を鳴らしちまったんだ。偵察道具を隠して物陰に逃げ込んだよ！ 困ったことに、その道具のところに戻れない。見回りを何倍にも増やされちまったんだ！ 集めた情報が全部パーだよ。\n\n持ち物を取り返してくれたら、おとなしくK.E.F.に戻るよ。", "どうだった?", "やってくれたのね! Lexlortがこの計画書を手に入れれば、私にしようとしていた嫌なことなんて全部忘れるはずよ。\n\n{name}、あなたは私の英雄よ!", 0xb62123b7, 0x33b105fa, 0x3bb799a8, 0x87e6d3ba, 0xf03858c8, "....." },
  [4983] = { "Bijou's Reconnaissance Report", "Bijou's Reconnaissance ReportをKargathのGrandmaster Lexlortのところへ持ち帰って下さい。", "この報告書をLexlortのところへ持って帰って。これで私の汚名は晴れるし、K.E.F.がこのオークどもに対処する上で、きっと戦略的に優位に立てるはずだよ。\n\n一緒に行くかって？ やることが山ほどあってそれどころじゃないよ。さあ行った行った、向こうは一刻も早くこの報告書が必要なんだから！", "ゴブリンはどこだ???", "あいつには参ったな。またしても厄介な状況から巧みに抜け出してみせた! このreportsは、Blackrockのオークどもとの駆け引きにおいてこの上なく貴重なものになるだろう。\n\nもちろん、君の働きには報酬を出す。", 0x25549b86, 0xc495008b, 0x20efa83e, 0xd4a96813, 0x4492c5db, "....." },
  [4984] = { "野生動物も苦しんでいる", "Diseased Wolvesを$N1体倒し、Western PlaguelandsのWrithing HauntにいるMulgris Deepriverのところへ戻って下さい。", "私一人ではScourgeを阻むためにできることはほとんどありませんでしたが、それでも自然が受けた傷を癒そうと、この地へやって来ました。動物たちは、この地を締め付け続ける疫病に苦しみ、慈悲も安らぎも見つけられずにいます。私がここでやり遂げられなかったことを、あなたに続けてほしいのです。\n\n苦しむ動物たちに救いはありません。あるのは、優しく慈悲深い解放だけです。近くにいるdiseased wolvesを探し出し、楽にしてあげてください。お願いです、{name}、彼らの苦しみを終わらせてください。そうすれば、きっと私の苦しみも和らぐでしょう。", "疫病に冒された狼たちは始末しなければなりません、{name}。彼らが持つ病は治せないのです。私も試みました……自分自身が疫病に倒れるまで、試み続けたのです。", "私は……あなたが倒した狼たちの魂が、ようやく安らぎを得たのを感じます。彼らも……そして私も、慈悲深い解放に感謝しています。\n\nこの忌まわしい地で苦しんでいるのは狼だけではありません、{name}。どうか、もう一度あなたの力が必要なのです。", 0x63c3b4ce, 0x759946ca, 0xea977f5e, 0x0e50456b, 0xe07aafd7, "....." },
  [4985] = { "野生動物も苦しんでいる", "Diseased Grizzliesを$N1体倒し、Western PlaguelandsのWrithing HauntにいるMulgris Deepriverのところへ戻って下さい。", "私たちのいる場所から東、Eastern Plaguelandsが始まるあたりでは、かつて誇り高く雄大な灰色熊が野を歩き回っていました。Scourgeが放った疫病は、この獣たちをも引き裂いてしまったのです。彼らは筋肉がこわばり、毛皮と肉が腐っていく苦しみに悶えながら、野をさまよっています。\n\n彼らの苦しみも終わらせてあげてください。その苦しみを癒す唯一の方法は速やかな死であり、それはあなたの手で与えられねばなりません。", "あなたの足音が聞こえます、{name}。私の視力は失われましたが、それでも周りのものを感じ取ることはできます。病に冒された灰色熊たちの苦しみを終わらせてくれましたか?", "「灰色熊たちが倒され、その苦しみが終わったことは分かっています。私……私にはあなたに渡すものがもう一つあります。この世での私の時間が終わりに来たことを感じて……この枝に、書き記しておきました。\n\nそう……私はその終わりにいます。改めて感謝します、友よ……この呪われた地の生き物たちは安らかに眠れるでしょう……そして今、私も。」\n\nそう言うと、ドルイドは重いため息をつき、続いて死の間際の喉鳴りのような音がした。彼の体は小屋の床に横たわり、動かない。", 0x63c3b4ce, 0x2916d23a, 0xc9e58228, 0xf2b7d5ee, 0x8c93a7a9, "....." },
  [4986] = { "Glyphed Oaken Branch", "Glyphed Oaken Branchに込められた魔法から判断すると、トーレンのドルイドが求めていた次の手順は、それをDarnassusのCenarion Circleへ届けることだ。そこにいるドルイドの誰かに助けを求めて下さい。", "トーレンのドルイドの生気のない手が、驚くほど健康そうな樫の枝を握りしめている。枝を調べてみると、樹皮にドルイドのものらしい紋様が刻まれている。\n\n枝をつかむと、触れた手に温かさが伝わってくる。本来あるべき以上の温かさだ。Teldrassilの木の姿――とりわけDarnassus――が脳裏に浮かび、「Cenarion Circle」という言葉が口をついて出そうになる。この枝をどこへ持って行くべきかという暗示が、枝そのものに込められているようだ。", "Cenarion Circleを代表して、この隠れ里へのご来訪を歓迎します、{class}。私たちにどのようなご用件でしょう?", "これは……実に奇妙だ。このドルイドが……しかもトーレンのドルイドが、Scourgeの疫病の広がりについての貴重な情報を大量に君に託したとは。トーレンが{race}にこのような情報を、しかも君の話が本当ならば無償で与えるとは驚きだ。これは有効に使わせてもらう、約束しよう。トーレンはFandralが思っているほどCenariusから遠く離れてはいないのかもしれない……\n\nおほん、ともかく、どうか、Cenarion Circleからの感謝の印としてこれを受け取ってくれ。", 0xc8244b3c, 0x2bab27cf, 0x7b819468, 0x675f6520, 0xdf30dbc2, "....." },
  [4987] = { "Glyphed Oaken Branch", "Glyphed Oaken Branchに込められた魔法から判断すると、トーレンのドルイドが求めていた次の手順は、それをThunder BluffのCenarion Circleへ届けることだ。そこにいるドルイドの誰かに助けを求めて下さい。", "トーレンのドルイドの生気のない手が、驚くほど健康そうな樫の枝を握りしめている。枝を調べてみると、樹皮にドルイドのものらしい紋様が刻まれている。\n\n枝をつかむと、触れた手に温かさが伝わってくる。本来あるべき以上の温かさだ。MulgoreのThunder Bluffの姿――とりわけElder Rise――が脳裏に浮かび、「Cenarion Circle」という言葉が口をついて出そうになる。この枝をどこへ持って行くべきかという暗示が、枝そのものに込められているようだ。", "Cenarion Circleを代表して、この隠れ里へのご来訪を歓迎します、{class}。私たちにどのようなご用件でしょう?", "これはMulgrisからだと？ 彼がPlaguelandsで苦しむ生き物たちを救おうとしていたとは聞いていたが、これは実に予想外で……実に悲しい。Mulgrisは……良き友だった。彼の死を深く悼もう。\n\n君の勤勉さのおかげで、彼の努力は無駄にならなかった。このbranchには、Scourgeがこの地に広める疫病についての多くの知識が収められている。我々はそれを熱心に研究しよう。君には、これを受け取ってほしい。君の気高い働きに対する、せめてもの礼だ。", 0xc8244b3c, 0x364df13d, 0x2cc00fb4, 0x675f6520, 0x49acd227, "....." },
})
